/**
 * constants.js — every behavioral number in Landfall.
 *
 * Rule from SPEC §12: define the constant BEFORE the logic that uses it, and
 * attach the reason. No unexplained numbers anywhere in the codebase.
 *
 * Second rule, harder: DERIVE, NEVER HAND-TUNE TWICE. This file holds SOURCES;
 * anything downstream is arithmetic on them. Hand-set clearances drift out of
 * sync with the thing they were meant to clear.
 *
 * Imports nothing. Ever.
 */

/* ==> TABLE OF CONTENTS — 70 blocks, ten groups <==
 *
 * A map, not a boundary — everything below lives in THIS file. Search the
 * name to land on it. Generated by tools/constants-toc.mjs; the pre-push
 * hook fails if a block is added, removed or renamed without landing in a
 * group here.
 *
 * TIMING, POLLING AND FRESHNESS
 *   when we ask, how long an answer stays good, and when quiet becomes a fault
 *   ADVISORY_CADENCE BOOT POLL RETRYABLE_STATUS CACHE FRESHNESS RELAY_AGE
 *   SILENCE GEOMETRY_LAG_THRESHOLD
 *
 * WHERE THE DATA COMES FROM
 *   the addresses and the shapes of the feeds behind them
 *   ENDPOINT MAPSERVER TILES GDACS_GEOMETRY SATELLITES IMAGERY_SENDS_NO_TIME
 *
 * THE CAMERA AND THE GLOBE
 *   zoom ladder, dive, idle motion, and what the sphere itself does
 *   ZOOM GLOBE DIVE GLOW RIM MOTION APPROACH
 *
 * MAP FURNITURE
 *   borders, place names and label placement — everything under the storms
 *   ADMIN LABEL_PLACEMENT COAST_BAND SIMPLIFY
 *
 * STORM SCIENCE AND UNITS
 *   the numbers meteorology fixes, not numbers we chose
 *   UNITS CATEGORY_THRESHOLD_KT CATEGORY_TOP_KT JTWC_WIND CONE_CIRCLE_NM_2021
 *   CONE_CIRCLE_NM_2026 CONE_CIRCLE_BY_SEASON CONE_CIRCLE_SEASON_LATEST
 *   CONE_CIRCLE_BASIN
 *
 * DRAWING A STORM
 *   track line, cone, wind swath, glyph — the geometry of one storm on the map
 *   MESH_TRACK FORECAST_NOW TRACK_LINE CONE_SWEEP CONE_CURVE RING_POLISH
 *   WIND_SWEEP BAND_MERGE
 *
 * FEATURES WITH THEIR OWN SECTION
 *   each of these owns a spec section and a piece of the drawer
 *   OUTLOOK GENESIS SURGE GDACS_SURGE CAP RAIN FLOOD ENDED IMAGERY ENV_RIBBON
 *   ENV_HEALTH MODEL_GROUP MODEL_FAMILY MODEL_TRACKS ADVISORY_TEXT POPULATION
 *   SEASONS
 *
 * HOME
 *   the house on the map and the dashboard that reads from it
 *   HOME HOME_DASH GEOCODE
 *
 * THE INTERFACE ITSELF
 *   what the app remembers, and how it answers a finger or a key
 *   STORAGE_KEY FIRST_RUN KEYBOARD SLIDER TAP
 *
 * WATCHING OURSELVES
 *   frame budget and the anonymous numbers that say whether it held
 *   PERF TELEMETRY
 *
 * ==> END TABLE OF CONTENTS <== */

/* ---------------------------------------------------------------------------
 * TIME BASE — everything below derives from these
 * ------------------------------------------------------------------------- */

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;

/** NHC issues full advisories every 6 hours, intermediates every 2-3 hours.
 *  This is the cadence everything about staleness is measured against. */
export const ADVISORY_CADENCE = 6 * HOUR;

/* ---------------------------------------------------------------------------
 * OVERTAKE BASE — one distance, two readers (§7.14)
 * ------------------------------------------------------------------------- */

/**
 * How far BEHIND the storm a published forecast hour has to sit before it is
 * treated as history rather than as a forecast. Nautical miles, measured along
 * the storm's own published heading.
 *
 * ==> ONE NUMBER, DELIBERATELY NOT TWO. <== `FORECAST_NOW` (the track line) and
 * `WIND_SWEEP` (the wind swath) both read it. They are asking the same question
 * about the same hours of the same advisory, and two dials set to 15 today is
 * how one of them ends up at 20 next month and the corridor folds back around a
 * track that does not. Not exported: nothing outside those two blocks has any
 * business asking.
 *
 * WHY 15 AND NOT 0. NHC publishes positions on a 0.1° grid — 6 nm of latitude,
 * about 5 nm of longitude in the tropics — and the current position and the
 * forecast point are each rounded independently, so ~8 nm of pure rounding
 * noise sits under every one of these comparisons. At zero a stalled storm
 * would flip an hour in and out of the forecast between polls on nothing but
 * the grid.
 *
 * WHY 15 AND NOT 60. It has to be far below what the fault actually looks like.
 * MEASURED on the 2026-08-22T13:04Z archive: Lala's advisory-39 tau-12 sat
 * 43 nm behind her 09:00Z position. Fifteen catches that with room to spare,
 * and 15 nm of backwards leg against a corridor 130–150 nm wide is under a
 * pixel at any zoom the app allows — so an hour this rule declines to drop
 * cannot draw a fold anyone can see.
 */
const BEHIND_GRACE_NM = 15;

/* ---------------------------------------------------------------------------
 * POLLING
 * ------------------------------------------------------------------------- */

/** The boot screen (ui/boot.js, markup in index.html). */
export const BOOT = Object.freeze({
  /** How long before the screen admits something may be wrong.
   *
   *  ERRING LONG, and the reason is the shape of the mistake. Firing early on
   *  a merely-slow connection tells someone their app is broken when it is
   *  about to work — and they leave. Firing late costs a few seconds of a
   *  spinner they were already watching. The measured tail is the number: P99
   *  time-to-content was 8.6 s on real traffic (SPEC-OPS §17), so anything
   *  under that would fire on visits that went on to succeed. */
  stuckAfter: 12000,
});

export const POLL = Object.freeze({
  /** Storm sources. 30 min catches every intermediate advisory without
   *  hammering anyone. Poll runs ONLY while the page is visible — no
   *  background work, ever (SPEC §4). */
  storms: 30 * MINUTE,

  /** Imagery source cadence. Fetched only while an imagery layer is ON. */
  imagery: 5 * MINUTE,

  /** Genesis outlook (§45). NHC republishes the outlook with the text product,
   *  roughly 6-hourly, and JTWC reissues several times a day — so this could
   *  be far slower than the storm poll and lose nothing. It matches the storm
   *  cadence anyway, for one reason: a watched area and a storm are the same
   *  question asked at two ranges, and a user watching an 80% area turn into a
   *  depression must not see the list and the globe disagree for half an hour
   *  because two timers fired at different times. Same tick, one answer.
   *
   *  It is its OWN constant rather than a reference to `storms` so that
   *  slowing one down later does not silently slow the other. */
  genesis: 30 * MINUTE,

  /** Auto-retry backoff after a failed fetch. Then stop and wait for the next
   *  normal poll. Never auto-retry while the page is hidden. */
  retryBackoff: Object.freeze([5 * SECOND, 15 * SECOND, 45 * SECOND]),

  /** Show the error UI once auto-retries are exhausted — EXCEPT when the
   *  screen is empty, where feedback is needed fast or it reads as broken. */
  errorDelayWhenEmpty: 2 * SECOND,

  /** Per-request abort. 20 s is generous for a JSON list on cell data but far
   *  short of GDACS-geometry's legendary 90 s — that endpoint is relay-cached
   *  precisely so no phone ever waits on it. A request that takes longer than
   *  this IS a timeout, and timeouts are retryable. */
  /** ==> 20 s WAS A COIN FLIP AGAINST A 20 s RELAY, AND IT ALWAYS LOST. <==
   *  Measured 2026-08-01: an uncached `/api/gdacs/events` took ~20 s, and this
   *  abort fired at 20 s. Four attempts, four aborts, the §5 unavailable
   *  banner, and Super Typhoon DOLPHIN-26 absent from the app while GDACS was
   *  healthy the whole time.
   *
   *  THE RACE IS FIXED ON THE OTHER SIDE, NOT HERE. `gdacs/events.js` now
   *  answers from cache immediately and refreshes behind the response, and
   *  caps its own upstream wait at 10 s — so nothing should approach this
   *  number any more. 30 s is headroom for the one case that still blocks (a
   *  cold colo with an empty warm store), not a fix. If a feed is ever seen
   *  reaching 30 s, raising this again is the wrong move: it means a route
   *  lost its cache, and the route is where to look. */
  fetchTimeout: 30 * SECOND,
});

/** A 4xx is NOT retryable — that is "no data," not "try again," and retrying
 *  it burns battery for nothing. Retryable = timeout, network error, 5xx. */
export const RETRYABLE_STATUS = Object.freeze({
  min: 500,
  max: 599,
  /* ===> 429 IS THE ONE 4xx THAT MEANS "TRY AGAIN". <===
   * The rest of the 4xx range means "no data" — a wrong path or a malformed
   * request will be just as wrong in five seconds, so retrying is noise. 429 is
   * the opposite: it means the answer exists and we asked too fast, which is
   * the definition of retryable. Left out of the range above because the range
   * is a span and this is a single exception to it; listing it as a span
   * boundary would quietly make 430-499 retryable too.
   *
   * This matters now because the relay ISSUES 429s as of
   * functions/api/_middleware.js. Without this entry, one burst past the limit
   * would present to the user as a flat feed outage until the next poll, which
   * is both wrong and the §5 failure mode of a confident incorrect answer. */
  also: Object.freeze([429]),
});

/* ---------------------------------------------------------------------------
 * CACHE TTLs (SPEC §4)
 *
 * Starting values, each with a reason so it can be argued with later.
 * Not measured — tune on real data.
 * ------------------------------------------------------------------------- */

/* ---------------------------------------------------------------------------
 * THE TROPICAL WEATHER OUTLOOK IN WORDS (§45.9)
 *
 * NHC's text outlook is the independent check on its GIS layer — the same
 * forecaster, the same schedule, and it carries the areas in prose when the
 * polygons are missing. `lib/outlook.js` parses it.
 * ------------------------------------------------------------------------- */

export const OUTLOOK = Object.freeze({
  /** How old a bulletin may be before it stops counting as evidence.
   *
   *  ==> THIS NUMBER IS THE DEFENCE AGAINST A FROZEN MIRROR. <== The product
   *  is issued every six hours, so twelve is two missed cycles: late enough
   *  that a delayed issuance never triggers it, early enough that a mirror
   *  which has quietly stopped is caught the same day.
   *
   *  MEASURED, NOT ASSUMED. `https://www.nhc.noaa.gov/ftp/pub/forecasts/
   *  discussion/MIATWOAT` was found on 2026-08-11 serving the 24 JUNE
   *  bulletin — two months old, plain text, HTTP 200, indistinguishable from a
   *  healthy source by every signal except the issuance line inside the body.
   *  A source we trust to CONTRADICT another source has to be checked harder
   *  than one we merely read. */
  maxAgeMs: 12 * HOUR,

  /** How far a bulletin may appear to be in the future before its day-of-month
   *  is read as belonging to the previous month.
   *
   *  The product stamps DDHHMM and no month, so at a month boundary the same
   *  six digits are either tomorrow or four weeks ago. Assuming the current
   *  month is the unsafe half of that: it dates a bulletin FORWARD, which
   *  passes every staleness check there is. One day absorbs clock skew and
   *  nothing else. */
  futureToleranceMs: 24 * HOUR,

  /** How far above a formation-chance line to look for the area's title.
   *  An area's prose runs to roughly eight lines; twenty is generous without
   *  reaching back into the previous area, which would label an area with its
   *  neighbour's name — a wrong label being worse than "Unnamed area". */
  titleLookbackLines: 20,

  /** The two bulletins that between them cover everything NHC's GIS layer 3
   *  covers. Both are fetched every poll and BOTH must be readable before the
   *  app will believe a true all-clear — see `reconcileBasins` in
   *  `lib/outlook.js`. A closed table for the same reason the relay's is: no
   *  caller text ever reaches a URL. */
  basins: Object.freeze(['atlantic', 'epacific']),

  /** ==> THE TWO THINGS THE RELAY SAYS ON `X-Landfall-Held`, AND THEY LICENSE
   *  DIFFERENT BEHAVIOUR. <==
   *
   *  `upstream-empty` — the layer answered with nothing INSIDE one outlook
   *  cycle of having had areas. Shown on its own, because the shape of the
   *  drop is itself the evidence (a real all-clear arrives one area at a time,
   *  not all at once).
   *
   *  `upstream-empty-lapsed` — past that cycle. The relay still HAS the
   *  memory and offers it, and it is deliberately NOT shown on the relay's
   *  say-so: a full outlook cycle of emptiness is normally the truth. It is
   *  drawn only when the text outlook independently says the layer is wrong,
   *  which turns the hold from an inference into a reading. The relay never
   *  makes that call — it cannot parse a bulletin (§3/§4) and does not try. */
  heldMarker: 'upstream-empty',
  heldLapsedMarker: 'upstream-empty-lapsed',
});

export const CACHE = Object.freeze({
  /* RELAY: THE NHC STORM LIST'S WINDOW IS NOT HERE, AND `nhcListFresh` IS GONE.
   *
   * It said 5 minutes. The route has said 30 since 2026-08-01 (widened with its
   * GDACS sibling, for the reason that file records: a 5-minute window refilled
   * by a 5-minute cron expires exactly as its replacement is due, and every
   * request landing in that gap goes to the origin). Nothing on either side of
   * the wire ever read this constant, so it drifted for ten days looking
   * authoritative and being inert — the same failure the GDACS geometry note
   * below was written about, repeated one entry up.
   *
   * `functions/api/nhc/storms.js` owns the number, because Pages Functions run
   * in their own runtime and cannot import this file without a bundler step
   * this project must never grow (§3). SPEC §4's cache table is the truth and
   * the function file mirrors it. */

  /** Relay: model a-decks. Synoptic cycles are 6-hourly. */
  adeckFresh: 15 * MINUTE,

  /* RELAY: GDACS PER-STORM GEOMETRY — the numbers are NOT here, deliberately.
   *
   * They live in `functions/api/gdacs/geometry.js` (fresh 30 min, serve-stale
   * ceiling 12 h) because Cloudflare Pages Functions run in their own runtime
   * and cannot import this file without a bundler step this project does not
   * have and must never grow (§3). Three constants sat here for a day naming
   * TTLs that nothing on either side of the wire ever read, which is worse
   * than an honest pointer: they looked authoritative and were inert.
   *
   * SPEC §4's cache table is the truth; the function file mirrors it and says
   * so. If those numbers change, they change in two places on purpose.
   *
   * On the numbers themselves: the HA project's 90-second timeout did NOT
   * reproduce here — measured 375–984 ms (2026-07-23) and 1.3–1.5 s / 224 kB /
   * 44 features (2026-07-24, live via /api/gdacs/inspect). Two independent
   * reads, so the "slow endpoint" story is retired. The cache stays as cheap
   * insurance against a source that has misbehaved before, on top of the size
   * and distance argument that actually justifies it. */

  /** Client: per-STORM geometry — each storm's best-known bundle, not one
   *  entry per advisory (data/cache.js explains why that changed). The cap
   *  stops unbounded growth. Bound every cache. Sized 12 — geometry is WARMED
   *  for every NHC storm now (§9 ambient ladder), and the NHC basins have
   *  peaked at 8-9 concurrent storms in hyperactive seasons; a cap of 8 would
   *  evict bundles mid-warm. */
  geometryLruStorms: 12,

  /** How long an UNSUCCESSFUL geometry attempt is left alone before the app
   *  asks again. Only reached when a fetch failed or came back empty while a
   *  newer advisory is out — the success path is gated on the advisory key and
   *  never waits on this.
   *
   *  Five minutes because that is what the failure it exists for actually
   *  costs: NOAA moves a storm's bin at the advisory and publishes the new
   *  bin's geometry minutes to hours later (measured 2026-07-26 — Fausto's
   *  CP1 block was still empty 21 minutes after the advisory that created it).
   *  Retrying faster only re-reads the relay's own edge cache; retrying slower
   *  leaves a storm on visibly older geometry for no reason. Deliberately
   *  matched to the relay's short-TTL window for empty answers
   *  (functions/api/nhc/mapserver.js) so the two cannot fight. */
  geometryRetryMs: 5 * MINUTE,

  /** Warm-fetch concurrency: bundles fetched two storms at a time. Gentle on
   *  the MapServer and on a phone radio, still warm within seconds. */
  geometryWarmConcurrency: 2,

  /** Relay: the NHC genesis outlook (§45). Comfortably under the 30-minute
   *  poll, so a poll is never handed the copy it fetched last time. Shorter
   *  than the storm list's relay window (30 min) because the underlying
   *  product moves on a ~6-hour cadence rather than a 6-hourly advisory with
   *  intermediates in between; there is simply less to miss. */
  genesisFresh: 15 * MINUTE,

  /** Relay: NHC's text Tropical Weather Outlook (§45.9). THE SAME WINDOW AS
   *  THE GENESIS LAYER, and that is load-bearing rather than tidy: the two are
   *  compared against each other, so a skew between their cache windows would
   *  manufacture a "the layer is broken" verdict out of nothing but timing. */
  outlookFresh: 15 * MINUTE,

  /** Relay: JTWC's two area bulletins, `abpwweb.txt` and `abioweb.txt` (§45).
   *  Plain-text bulletins reissued a few times a day. Same window as the
   *  outlook so the halves of the watch list can never be served from wildly
   *  different moments — ONE constant for both routes, because a skew between
   *  the Pacific and the Indian Ocean is the same manufactured disagreement a
   *  skew against the outlook would be. */
  abpwFresh: 15 * MINUTE,

  /**
   * Relay: one RainViewer radar TILE (§4.9). Mirrors `FRESH_SECONDS` in
   * `functions/api/imagery/radar.js`.
   *
   * TWO DAYS, AND THAT IS A CONSEQUENCE RATHER THAN A DECISION. A tile URL
   * names ONE frame explicitly, and a frame's pixels never change, so the
   * answer is immutable and the only correct lifetime is a long one.
   * RainViewer serves these with `max-age=172800` themselves, for the same
   * reason. This is also the best defence available against the IP block their
   * terms warn about: a warm pan across the map costs nothing at all.
   */
  radarFresh: 2 * 24 * HOUR,

  /**
   * Relay: the radar frame INDEX (§4.9). Mirrors `FRESH_SECONDS` in
   * `functions/api/imagery/radar-frames.js`.
   *
   * SIXTY SECONDS, against tiles cached for two days, and the gap between those
   * two numbers is the whole design. This is the only thing that DISCOVERS a
   * new frame exists, so it has to be short; everything it points at is fixed
   * forever, so that can be long. Not zero, so a dozen tabs opening together
   * share one lookup.
   */
  radarFramesFresh: 1 * MINUTE,

  /**
   * Relay: RainViewer's coverage mask (§4.9).
   *
   * A DIFFERENT KIND OF THING FROM EVERY OTHER WINDOW IN THIS TABLE. The rest
   * cache weather, which is why they are measured in minutes. This caches
   * GEOGRAPHY — where the radars physically are — which RainViewer says it
   * updates rarely. A day is already far shorter than the truth changes, and
   * the cost of being a day stale is that a newly-added national network is
   * called "no coverage" for one more day, on a screen that is already saying
   * so honestly.
   */
  radarCoverageFresh: 24 * HOUR,

  /** Relay: the CAP alert feed (§50). Mirrors `FRESH_SECONDS` in
   *  `functions/api/cap/alerts.js`. Ten minutes rather than fifteen because an
   *  alert is a human act with no publication cadence to sit inside — an
   *  agency issues one when it decides to, and the only thing this window
   *  controls is how long a NEW one waits to appear. */
  capFresh: 10 * MINUTE,

  /** How long the BROWSER holds the alert list before asking again (§50.8).
   *  Deliberately shorter than the relay's window: the relay answers from its
   *  own cache in a millisecond, so a client that asks more often than the
   *  relay refetches costs one local round trip and gets a fresher answer the
   *  moment the relay has one. */
  capClient: 5 * MINUTE,

  /** How long the BROWSER holds the national flood alert list (§48.21).
   *
   *  ==> THREE MINUTES, AND IT IS THE SHORTEST WINDOW IN THIS TABLE. <== Every
   *  other entry here is set by how often a SOURCE republishes. This one is set
   *  by how fast its contents stop being true: the captured Hilo Flash Flood
   *  Warning expired **52 minutes** after it was issued, and a flash flood
   *  warning routinely outlives neither a poll nor a coffee. The relay holds
   *  fifteen and answers from its own cache in a millisecond, so a client
   *  asking more often costs one local round trip and gets the newer answer the
   *  moment the relay has one.
   *
   *  ==> IT IS NOT THE ONLY GUARD AND MUST NOT BE THE ONLY GUARD. <== Expiry is
   *  filtered again at render, off each row's own `ends`/`expires`, exactly as
   *  §48.6 does for the house rows. A shape on a map saying somebody is in
   *  danger who is not is worse than a stale number, which is also why neither
   *  this nor the relay keeps a last-good copy. */
  floodClient: 3 * MINUTE,

  /** How long the EDGE holds one NWS forecast-zone boundary (§56.4).
   *
   *  ==> THIRTY DAYS, AND IT IS NWS'S OWN NUMBER RATHER THAN OURS. <== Measured
   *  off the captured responses on 2026-08-23: every zone came back with
   *  `cache-control: public, max-age=2592000` — thirty days — and a
   *  `last-modified` of 2026-04-16, four months earlier. A county line is not
   *  weather. This is the longest hold in this table by three orders of
   *  magnitude and it is still shorter than the source says it may be.
   *
   *  ==> THE HAZARD IT AVOIDS IS SOMEBODY ELSE'S SERVER. <== A national flood
   *  day names dozens of zones, and without a long hold every reader who opens
   *  the app re-asks api.weather.gov for a boundary that last moved in April.
   *  The alert list beside it holds for fifteen MINUTES because its contents
   *  stop being true; a boundary does not. Two facts, two lifetimes, one
   *  payload only because the client joins them. */
  zoneFresh: 30 * 24 * HOUR,

  /** How long the BROWSER holds a resolved zone shape, in this session's
   *  memory. Same reasoning, one order smaller: the tab is not a CDN and a
   *  reader who leaves the app open for a day should not be holding a
   *  boundary the edge may have refreshed. */
  zoneClient: 12 * HOUR,

  /** Service worker: last-good storm data. ~1.5x advisory cadence, carried
   *  from the HA project. Served flagged stale with its age. */
  lastGoodStormData: 9 * HOUR,
});

/* ---------------------------------------------------------------------------
 * FRESHNESS BANDS — how the timestamp element reads (SPEC §16)
 *
 * Derived from ADVISORY_CADENCE, not hand-set, so changing the cadence
 * assumption moves all three together.
 * ------------------------------------------------------------------------- */

export const FRESHNESS = Object.freeze({
  /** Under ~4 h: quiet. Within a normal advisory cycle. */
  freshUntil: (2 / 3) * ADVISORY_CADENCE,

  /** 4-9 h: highlighted. We've missed at least one expected update. */
  agingUntil: CACHE.lastGoodStormData,

  /** Past 9 h: flagged. "⚠ Last update 11 hrs ago" */
});

/* ---------------------------------------------------------------------------
 * RELAY_AGE — is our PIPELINE healthy? A different question, different ruler
 * -------------------------------------------------------------------------*/

/**
 * ==> DO NOT DERIVE THIS FROM `ADVISORY_CADENCE`. IT IS THE WRONG RULER AND
 *     THAT MISTAKE HAS ALREADY BEEN MADE ONCE. <==
 *
 * `FRESHNESS` above measures A STORM: how long since NHC published a new
 * analysis, so 6-hourly cadence is exactly the right thing to divide by. This
 * measures US: how long since our relay last successfully reached NOAA.
 * `X-Landfall-Fetched-At` is stamped at OUR fetch, not at NHC's issuance, so a
 * quiet ocean with no new advisories still gets re-fetched and re-stamped on
 * every cycle. The two numbers look interchangeable and are not.
 *
 * ==> WHAT A CADENCE-DERIVED NUMBER WOULD ACTUALLY HIDE. <== The warm cron runs
 * every 5 minutes. A 6-hour-old copy is therefore not "NHC has not issued yet",
 * it is roughly SEVENTY-TWO consecutive failed refreshes — a completely dead
 * pipeline, unreported for most of a day. `isSourceStale()` in `data/store.js`
 * compared a fetch timestamp against `FRESHNESS.freshUntil` for exactly this
 * reason and could never mean anything; it is why that function sat with no
 * caller.
 *
 * THE HEALTHY WORST CASE IS ~35 MINUTES — a 30-minute relay window plus a
 * 30-minute client poll landing just after it turns over. Three of those is the
 * threshold: long enough that nothing routine trips it, short enough that a
 * broken pipeline surfaces inside one advisory cycle rather than after one.
 *
 * ==> AND IT REPLACED A FLAG THAT STOPPED MEANING WHAT IT SAID. <== The strip
 * used to fire on `X-Landfall-Stale`, which meant one thing — upstream failed —
 * until the storm-list routes started serving expired copies on PURPOSE and
 * refreshing behind the response. That header now covers both "NOAA is broken"
 * and "your copy is 31 minutes old and a fresh one is landing right now", so it
 * cannot drive an alarm. Age can: it is true regardless of which code path
 * served the bytes, and it works the same on both sources.
 */
export const RELAY_AGE = Object.freeze({
  /** Past this, the strip says the feed is delayed. */
  delayedAfter: 90 * MINUTE,
});

/* ---------------------------------------------------------------------------
 * SILENCE — a source that STOPPED PUBLISHING (SPEC §5)
 *
 * A FOURTH STATE, and it is not a flavor of the other three. `unavailable`
 * means the fetch died. `none_matched` means nothing was in scope. `clear`
 * means the ocean is genuinely empty. SILENT means all three succeeded — the
 * feed answered 200, the storm is still in the list, its record still says
 * current — and the newest fix in it is a day old. Nothing errors. Nothing is
 * missing. The data is simply frozen, and the app was drawing a forecast cone
 * off it as confidently as off a live one.
 *
 * MEASURED, TWICE, NOT GUESSED:
 *   - BERTHA (2026-07-24). NHC retired her: gone from CurrentStorms.json, her
 *     MapServer bin flushed to zero features, her advisory bin archived. GDACS
 *     kept `iscurrent: "true"` on her for ~58 hours with no new analysis. The
 *     Atlantic basin rule in data/merge.js hid the damage by accident — a
 *     GDACS copy of an NHC-basin storm is dropped regardless.
 *   - NOUL-26 (2026-07-26). West Pacific, where that accident does not apply.
 *     GDACS ran ~6 h fixes and then went silent at 2026-07-26T00:00:00Z as the
 *     storm came ashore in Guangdong. Seventeen hours later the app was still
 *     drawing her PRE-LANDFALL cone and forecast points as the live future of
 *     a storm that had already hit.
 *
 * THE DECOY IS `datemodified`. GDACS moved Noul's to 16:37Z on the day it had
 * published nothing since midnight. A backstop reading it would never fire, on
 * Noul or on Bertha. The only honest clock is the ANALYSIS time — the storm
 * model's `observedAt`, GDACS `todate` / NHC advisory issuance — and that is
 * what lib/silence.js reads. Do not "improve" this by reaching for whichever
 * timestamp looks freshest.
 *
 * FOUR CYCLES, and the number is the point rather than the caution. GDACS fixes
 * run 6-12 h apart and NHC's run 6, so 24 h is two missed cycles even for the
 * slowest publisher: it effectively cannot fire on a storm that is genuinely
 * live. That safety is affordable BECAUSE a silent storm is not dropped — it
 * keeps its dot, its past track and its badge, and the only cost of firing late
 * is a label arriving a few hours after it could have. Dropping the storm
 * instead would invert that trade and make a false positive expensive.
 * ------------------------------------------------------------------------- */

export const SILENCE = Object.freeze({
  /** Past this age with no new analysis, the source is treated as having
   *  stopped publishing. Aaron's call at 4 cycles; see the note above for why
   *  erring long is the cheap direction here. */
  after: 4 * ADVISORY_CADENCE, // 24 h
});

/** Geometry lag: when the MapServer's own timestamp trails the storm feed by
 *  more than one advisory cycle, the detail panel grows a second line saying
 *  so. When they agree, the line does not exist — silence means synchronized. */
export const GEOMETRY_LAG_THRESHOLD = ADVISORY_CADENCE;

/* ---------------------------------------------------------------------------
 * ZOOM LADDER (SPEC §9)
 *
 * Zoom controls DETAIL, not MEANING. A storm's category color, glyph, and
 * position never change with zoom. What changes is how much supporting
 * information sits around it.
 *
 * Four bands, not eight, so transitions are felt rather than guessed at.
 *
 * [DECIDE] Exact thresholds, once there is a real basemap to look at.
 * These are the spec's stated bands, unmeasured.
 * ------------------------------------------------------------------------- */

export const ZOOM = Object.freeze({
  min: 0,
  /** ==> THE CEILING WAS 8 UNTIL 2026-07-31 AND THE REASON IT WAS 8 DID NOT
   *  SURVIVE A READ OF THE STYLE. <== §11 said "past z8 you pull in street
   *  grids, which are noise for storm data". We never draw a street. The only
   *  OpenMapTiles source-layers `map/style.js` touches are `water`, `earth`,
   *  `boundary` and `place`, and `place` is rank-filtered — so what actually
   *  arrives past z8 is finer coastline and a few more town names, not a road
   *  network. The stated objection was to a layer set that does not exist.
   *
   *  ==> WHAT FORCED IT TO 11 IS GONE, AND THE VALUE HAS NOT BEEN RE-EARNED.
   *  <== 11 was chosen entirely for the 3D seamounts: their edifice handoff
   *  finished at z7.8, which left two tenths of a zoom level to look at fully
   *  drawn mountains, and the wave arithmetic said a person needs ~z11 to judge
   *  the water. Those seamounts were cut with Deep on 2026-08-08. Nothing that
   *  ships today asks for 11 specifically.
   *
   *  IT IS LEFT AT 11 ON PURPOSE, NOT BY OVERSIGHT. The old objection to going
   *  past 8 was measured and found false (see above) — we draw no streets — so
   *  reverting to 8 would restore a ceiling whose stated reason does not exist
   *  either. What the cyclone app actually wants at the top of the ladder is a
   *  judgement on glass: how far in is useful for reading a landfall point
   *  against a coastline. Until somebody makes that call on a phone, 11 is the
   *  known-good status quo and this comment is the honest reason why.
   *
   *  Downstream: `TILES.sourceMaxzoom` (8) is the DORMANT R2 archive's real data
   *  ceiling and is untouched — flipping `TILES.useR2` back on overzooms past 8
   *  rather than 404ing. `GEOCODE.confirmZoom` derives from `ZOOM.local`, not
   *  from here, so address confirmation did not move. */
  max: 11,

  /** Band floors. A band runs from its floor up to the next band's floor. */
  planet: 0,       // z0-2: continent fills, coast glow, graticule.
                   //       Glyph + category color only. NO LABELS.
  basin: 3,        // z3-4: + major islands, storm names
  regional: 5,     // z5-6: + full coastline resolution
  local: 7,        // z7-8: full coastline detail, surge bands, wind bands

  /** THE LAST TWO LAYERS THAT STILL WANT A HARD FLOOR: forecast TIME LABELS
   *  and the watch/warning coastal stripe. Text and stripes read badly at
   *  partial opacity over the cage; lines and dots do not.
   *
   *  ==> IT IS NO LONGER THE AMBIENT GEOMETRY FLOOR, WHATEVER THE NAME SAYS.
   *  <== Cone, both tracks, forecast points and the last-known-position mark
   *  all carry NO floor now — the MapLibre crossfade is the real gate, so they
   *  materialise with the map instead of popping at a threshold
   *  (map/layers/registry.js). This comment claimed otherwise until 2026-07-29,
   *  and a layer written to it arrived two zoom levels after everything it was
   *  supposed to appear beside. The original rule still holds where it applies:
   *  a staggered arrival reads as a rendering bug rather than as a ladder, so
   *  anything gated here must be gated together. */
  ambientGeometry: 4,

  /** THE FLOOD POLYGON RAMP (SPEC-FLOOD-PLAN §56.5). A county-scale alert
   *  shape is under about twelve pixels below z6 — §56.2 measured the median
   *  warning polygon at 0.270° wide — and at that size it reads as dirt on the
   *  screen rather than as a place. So it fades in across one zoom level
   *  instead of appearing at a threshold, which is the same reasoning the
   *  crossfade above rests on: a hard pop reads as a rendering fault.
   *
   *  ==> AN OPACITY RAMP AND NOT A VISIBILITY FLIP, SO THE COST IS PAID ONCE.
   *  <== The features are in the source either way; what changes is what
   *  MapLibre paints. Swapping `visibility` on the zoom would mean re-tiling
   *  the source every time a reader crossed the line.
   *
   *  Both are movable on glass and neither has been judged — nothing has ever
   *  drawn a flood polygon on this globe. */
  floodFadeIn: 6,     // first visible here
  floodFull: 7,       // full strength by here

  /** MapLibre resting zoom — where recenter() returns the camera, and the
   *  planet-band framing the dive lands near. (The old introStart retired with
   *  the MapLibre opening sequence; the 3D arrival uses camera distance, §2.) */
  introRest: 2.2,
});

/* ---------------------------------------------------------------------------
 * ADMINISTRATIVE FURNITURE (§11) — borders and place names.
 *
 * All of it comes out of the OpenMapTiles `boundary` and `place` layers that
 * OpenFreeMap already serves us. No new source, no new request, no new bytes:
 * this data has always been inside the tiles we download, we simply were not
 * drawing it.
 *
 * The governing rule is RESTRAINT. This app already draws coast glow, coast
 * core, the graticule, tracks, cones, forecast points, wind bands, and the
 * watch/warning stripe. Every mark added here competes with storm data for the
 * same dark pixels, so each one arrives as late as it can still be useful and
 * stays dimmer than the coastline (§9 — reference, not content).
 * ------------------------------------------------------------------------- */

export const ADMIN = Object.freeze({
  /** Zoom each mark starts fading in. Ordered by how much space the mark
   *  occupies and how early the question it answers gets asked:
   *  "which country" before "which state" before "which state is this" before
   *  "which city". Nothing appears at the planet band — z0-2 belongs to the
   *  mesh, and a border there is noise over a globe you are still orienting on
   *  (§9 zoom ladder: no labels at the planet band). */
  countryLineIn: 2.4,
  stateLineIn: 3.4,

  /** THE NAME LADDER — four bands, each `[startZoom, endZoom]`.
   *
   *  Each name begins rising while the thing before it is still on screen, so
   *  the map dissolves from one label to the next instead of switching:
   *
   *    cage fades out  2.48 -> 3.86   (derived, see below)
   *    country rises   3.40 -> 4.00   overlaps the cage's last third
   *    country holds   4.00 -> 4.40
   *    state rises     4.20 -> 4.90   begins BEFORE country starts leaving
   *    country falls   4.40 -> 5.00
   *    cities rise     6.40 -> 7.20   (`cityIn` + `fadeSpan`, below)
   *    state falls     6.60 -> 7.40   begins AFTER cities start arriving
   *
   *  THIS USED TO BE ONE SHARED BAND — country ran 1->0 and state 0->1 across
   *  the same pair of numbers, which made them structurally incapable of
   *  drifting. That is a real thing to give up, and it was given up on purpose:
   *  a shared band can only ever produce an EXACT crossfade, and the effect
   *  wanted on glass is an offset overlap where both names are briefly up
   *  together. Independent bands are the only way to express that.
   *
   *  So the guarantee moves from "impossible to break" to "stated, and checked
   *  by sampling the whole zoom range":
   *
   *    THE INVARIANT — NEVER A NAMELESS GLOBE. From the moment the cage starts
   *    dissolving until cities arrive, at least one name is on screen at every
   *    zoom. `countryIn` must start before the cage is gone, and `stateIn` must
   *    start before `countryOut` ends. Move any of these six numbers and
   *    re-sample; a gap is invisible in the constants and obvious on glass.
   *
   *  `countryIn[0]` is DERIVED FROM `fade.cage`, which puts the cage fully gone
   *  at z3.86 (the crossfade band is zSpace..zHandoff and `fade.cage` ends at
   *  p 0.62). RECHECK IT if the DIVE choreography is ever retimed. */
  nameLadder: Object.freeze({
    countryIn: Object.freeze([3.4, 4.0]),
    countryOut: Object.freeze([4.4, 5.0]),
    stateIn: Object.freeze([4.2, 4.9]),
    /** THE RUNG THAT WAS MISSING UNTIL 2026-08-07. State names used to rise at
     *  4.2 and then never leave — the only label on the map with no exit. Past
     *  the point cities arrived you carried both, forever, and over a place
     *  like Japan or the eastern seaboard that is dozens of area labels sitting
     *  on top of the point labels you were actually trying to read.
     *
     *  Shaped like `countryOut`, one rung down: it begins AFTER `cityIn` (6.4)
     *  so cities are already coming up when states start to go, and it ends at
     *  7.4, just past the zoom cities reach full strength (`cityIn` +
     *  `fadeSpan` = 7.2). Both names are briefly up together, which is the
     *  same offset overlap the country-to-state handoff uses.
     *
     *  ==> THE INVARIANT DOES NOT REACH PAST HERE, AND THAT IS ACCEPTED. <==
     *  "Never a nameless globe" is guaranteed by construction from the cage
     *  through to `cityIn`. Beyond 7.4 the only labels are cities, and a
     *  stretch of coast with no ranked city in frame WILL be nameless. That is
     *  the local band — you are looking at a coastline and a track, not
     *  navigating by region — and it was true of the shipped map at any zoom
     *  past the cities' arrival in an unpopulated frame anyway. If it reads
     *  badly on glass, raise these two numbers rather than deleting the rung. */
    stateOut: Object.freeze([6.6, 7.4]),
  }),
  /** Cities land LATE — well inside the regional band, close to the local
   *  one. Walked out twice on glass 2026-07-24: 4.6 -> 5.4 -> 6.4. Both
   *  earlier values put city names on screen while the question was still
   *  "which storm" or "which state", where they were pure clutter. By 6.4 the
   *  question is "where exactly does this come ashore", and that is the first
   *  point a city name is the thing you are actually trying to read. */
  cityIn: 6.4,

  /** Fade width in zoom levels. Marks arrive over roughly half a zoom step so
   *  they never pop; matched to the coast layers' own ramps. */
  fadeSpan: 0.8,

  /** `place.rank` ceiling for city labels. The schema ranks cities 1..10, most
   *  important first, and ranks ONLY notable places — an unranked village has
   *  no rank at all, so this filter is what makes "major cities" a real
   *  category rather than a guess. 10 admits every ranked city; label
   *  collision, sorted by that same rank, does the thinning from there.
   *  Lower this if the near bands feel crowded. */
  cityRankMax: 10,

  /** Country borders are `admin_level` 2; states and provinces are 4. The
   *  schema carries more levels (counties, districts) and they are deliberately
   *  never drawn — past state level this becomes an atlas, not a storm map. */
  levelCountry: 2,
  levelState: 4,
});

/* ---------------------------------------------------------------------------
 * FORECAST TIME LABEL PLACEMENT (§7)
 *
 * Consumed only by map/layers/label-placement.js. Every number the spoke
 * placement uses lives here — nothing in that file is a literal.
 *
 * These are unmeasured starting values. `charWidthPx` and `maxTextTiltDeg`
 * are the two worth tuning first against a real busy basin on a phone: the
 * first decides how tightly labels may pack, the second how steeply the text
 * is allowed to lean.
 * ------------------------------------------------------------------------- */

export const LABEL_PLACEMENT = Object.freeze({
  /** Distance from the DOT'S CENTRE to the NEAR END of the label, along the
   *  spoke. The text starts here and runs outward, so the line of text IS the
   *  spoke and it points back at the dot's centre.
   *
   *  IT IS THE NEAR END, NOT THE CENTRE, AND THAT MATTERS. This used to be
   *  the distance to the label's centre, which put a 80px-wide label 26px
   *  sideways from the dot — the label straddled the dot and the text landed
   *  on top of it. Visible on glass 2026-07-26 on Noul, a due-north storm
   *  whose spokes point sideways. Measuring to the near end gives the same
   *  clear gap in every direction. The dot is 10px radius plus a 1.5px
   *  stroke, so 18 leaves about 6px of air. */
  spokeStartPx: 18,

  /** The hardest limit here: the text never leans further than this from
   *  horizontal, in either direction. 45 is Aaron's call and it is a rule,
   *  not a preference — past it the labels stop scanning as text and start
   *  scanning as decoration. */
  maxTextTiltDeg: 45,

  /** The tilt is searched in steps of this many degrees, starting at 0 and
   *  working outward, so the SHALLOWEST angle that fits always wins. Five is
   *  fine enough that the chosen angle looks deliberate and coarse enough
   *  that the search stays cheap. */
  tiltStepDeg: 5,

  /** ONE ANGLE PER STORM. Every label on a track is drawn at the same tilt —
   *  they read as a set of parallel spokes rather than a fan, which is what
   *  Aaron asked for and what his reference photo shows. Only the DIRECTION
   *  each label runs from its dot varies, and that is the side choice below.
   *  This constant exists to name the rule; there is nothing to tune. */
  sharedAngle: true,

  /** Clear space kept between a label and any OTHER storm's-track dot it
   *  might run across. A shallow angle can lay the text straight along the
   *  track and through the next dot, which is how the Noul-style "text on
   *  the glyph" failure comes back by another road. The dot is 10px radius
   *  plus a 1.5px stroke; this is that plus a little air. */
  dotClearPx: 13,

  /** ==> THE TRACK LINE IS AN OBSTACLE, AND IT WAS NOT ONE FOR THIS FILE'S
   *  WHOLE LIFE. <==
   *
   *  Placement checked labels against other LABELS and against other DOTS.
   *  Both are things the reader can see; so is the forecast track drawn
   *  between them, and nothing was stopping a label from lying straight along
   *  it. On a fast west-moving storm that is not a rare case, it is the
   *  DEFAULT: the search starts at 0° because horizontal text reads best, the
   *  dots on such a track are far enough apart that horizontal clears every
   *  one of them, so 0° passes on the first try and the whole run of
   *  timestamps is laid down on top of the line. Aaron, on glass.
   *
   *  IT IS AN ANGLE AND NOT A DISTANCE, which is the whole design. The
   *  failure is PARALLELISM: a label three pixels off a line it runs beside
   *  for its whole length is as unreadable as one drawn on top of it, and a
   *  label crossing that same line at 40° is perfectly fine. 20° is roughly
   *  where a strip of text stops reading as attached to the line and starts
   *  reading as pointing away from it.
   *
   *  ==> A SECOND RULE WAS BUILT HERE AND THEN CUT, AND IT IS WORTH KNOWING
   *  WHY SO IT IS NOT BUILT AGAIN. <== The obvious companion is a CLEARANCE:
   *  the label strip must also keep N pixels from every distant leg of the
   *  track — the far side of a recurve, the leg a storm is turning back
   *  across. It was implemented, and then measured against straight tracks at
   *  four spacings, three recurve shapes, two self-overlapping loops with the
   *  legs 25px apart, a zigzag and a hairpin. It changed the outcome on NONE
   *  of them: closest approach was 14px on the worst fixture, against a 6px
   *  rule. The angle rule and the existing dot rule between them had already
   *  moved every label clear. Machinery that cannot be shown to change an
   *  outcome is machinery whose next edit nobody can test, so it went. */
  minTrackAngleDeg: 20,

  /** The storm's NAME is drawn under its position dot (map/markers.js) and it
   *  is now an obstacle too. It is the largest piece of text on the map and
   *  it sat in the one place placement was guaranteed to want — directly
   *  below the tau-0 point, which is the storm's current position and the
   *  anchor of the first forecast label. The two collided constantly and
   *  neither knew about the other: MapLibre could not arbitrate it either,
   *  because forecast labels carry `text-allow-overlap`, so they draw through
   *  the name rather than yielding to it.
   *
   *  ESTIMATED, LIKE EVERY OTHER BOX HERE, and for the same reason — no
   *  canvas round trip. The name is uppercase with 0.08em of tracking, so a
   *  character is wider than the time labels' 6.2px even before the larger
   *  type size. Multiplied by the label's own px size at the call site, so
   *  these stay correct if the name's size changes. Overestimating spreads
   *  labels; underestimating puts one through the storm's name. */
  nameCharEm: 0.78,
  nameLineEm: 1.25,

  /** Air the storm's NAME keeps from the drawn forecast line and from the
   *  forecast dots when it is choosing which side of its dot to sit on
   *  (map/layers/name-placement.js).
   *
   *  SMALL ON PURPOSE, and smaller than the time labels' `padPx` for a
   *  reason. This is not spacing — it is the tolerance on an ESTIMATED text
   *  box, and every pixel of it makes the name reject a spot it would
   *  actually have fitted in and shuffle around to a stranger one. The name
   *  has a 1.8px halo of its own, so it is legible right up against a line;
   *  what it must not do is sit ON the line. Four pixels is the width of the
   *  track stroke plus a little, which is exactly the miss this is buying. */
  namePadPx: 4,

  /** Collision box estimate. We cannot measure rendered text without a
   *  canvas round-trip, and `datelbl` is a short predictable string, so
   *  width is estimated per character. Overestimating is the safe direction:
   *  it spreads labels rather than letting them touch. */
  charWidthPx: 6.2,
  lineHeightPx: 13,
  padPx: 3,

  /** The most CONTIGUOUS GROUPS the labels may be split into. One group means
   *  every label on one side of the track, which is the goal. Two means one
   *  run then the other, e.g. four above followed by four below. Three is the
   *  ceiling on purpose: past that a "group" is one or two labels long and
   *  the result is indistinguishable from labels alternating sides dot to
   *  dot, which is the exact thing this replaced. When even three groups
   *  cannot fit the labels, the answer is to show fewer of them, never to
   *  add a fourth. */
  maxRuns: 3,

  /** How much of the best achievable label count a tidier arrangement is
   *  allowed to give up.
   *
   *  Fewest groups is the goal, so a run of eight on one side is preferred
   *  over seven plus a single rogue on the far side even though the rogue
   *  arrangement shows one more time. But that preference has to stop
   *  somewhere: a track that doubles back can jam one side completely, where
   *  insisting on a single group would throw away most of the forecast to
   *  keep the picture tidy. 0.75 means an arrangement must still show three
   *  quarters of the most any arrangement could show before its tidiness
   *  counts for anything. */
  minKeepFraction: 0.75,

  /** Search safety valve. The number of arrangements to try grows with the
   *  cube of the label count at three groups, so an unexpectedly long track
   *  drops to two groups rather than spending the frame budget. NHC publishes
   *  at most nine forecast points, so this should never fire in practice —
   *  it exists so a surprise from another source cannot stall a phone. */
  maxPointsForThreeRuns: 16,

  /** Placement recomputes on `moveend`, debounced by this. A pinch fires
   *  several moveends in a row on a phone; recomputing on each is wasted
   *  work the frame budget cannot spare. */
  recomputeDebounceMs: 90,
});

/* ---------------------------------------------------------------------------
 * GLOBE BEHAVIOR
 * ------------------------------------------------------------------------- */

export const GLOBE = Object.freeze({
  /** Fallback resting center when there is no home and no active storm.
   *
   * THE CONTIGUOUS UNITED STATES, not the mid-Atlantic. This used to be
   * [-52, 22] — a fixed view of the open Atlantic on the reasoning that the
   * basin is what Landfall watches. On glass that is the wrong answer to
   * "take me back": recentering dropped you on empty ocean with the coastline
   * you actually care about off the left edge. Home is the real reference
   * point and recenter uses it whenever one is set; this is only what happens
   * when there is no home to go to, and the honest default there is the
   * landmass, not the water. Roughly the geographic centre of the lower 48. */
  fallbackCenter: Object.freeze([-98.5, 39.5]),

  /** Zoom for "take me to my house" — tapping the home glyph on the globe.
   *  Inside the regional band (ZOOM.regional = 5): close enough that the
   *  coastline around home has real shape, far enough out that a storm two
   *  states away is still on screen. Not the local band, which is street
   *  grids and a view too tight to see weather coming. */
  homeZoom: 6,

  /** How much of the visible strip the Home drawer's opening frame fills with
   *  the house-and-storm pair (map/home-frame.js). The rest is breathing room,
   *  split evenly on all four sides — so 0.82 leaves 9% at each edge.
   *
   *  ==> THERE IS NO MINIMUM ZOOM HERE ANY MORE, AND THAT WAS A REAL BUG. <==
   *  This used to have a companion `homeFrameMinZoom: 3` that refused to pull
   *  further out than the basin band and fell back to the house alone. It was
   *  invisible on a desktop and wrong on a phone, because the two have very
   *  different amounts of globe: measured, a 390x844 phone leaves a 390x338
   *  strip beside a 1440x900 desktop's 1000x900. The same storm 1,600 nm out
   *  frames cleanly at z4.24 on the desktop and hit the floor at z3 on the
   *  phone, where the camera gave up and centred on the house. That is exactly
   *  the "it works on desktop, not on mobile" report. MapLibre's own `minZoom`
   *  (the derived space floor) is the only limit now, which is a limit of the
   *  planet rather than one we invented.
   *
   *  RAISE toward 1.0 for a tighter frame; the two ends then sit closer to the
   *  edge of the visible strip, which on a globe is the curve of the limb where
   *  a glyph foreshortens into a smear. LOWER for more air around the pair. */
  homeFrameFill: 0.82,

  /** How far off north the camera has to be before the view control switches
   *  from crosshair to compass, in DEGREES.
   *
   *  Not zero: MapLibre's bearing is a float and a two-finger gesture almost
   *  never lands on exactly 0, so a zero test would leave the button showing a
   *  compass at 0.03° — a control offering to fix something nobody can see.
   *  Half a degree is under a pixel of rotation on a phone-sized globe. */
  northTolerance: 0.5,

  /** Idle auto-rotate. Stops INSTANTLY on interaction; disabled under
   *  OS reduce-motion.
   *
   *  THESE ARE NOW DEFAULTS, NOT FIXED VALUES (2026-07-25). Whether the globe
   *  drifts, how fast, and how long it waits are settings — the right answer
   *  is personal, and the same drift that makes the globe feel alive to one
   *  person makes it feel like it will not sit still to another. This file
   *  still owns what "sensible" means; data/settings-prefs.js owns what the
   *  user chose. */
  idleRotateDegPerSecond: 1.6,
  idleResumeDelay: 12 * SECOND,

  /** Slider bounds for the two idle-rotation settings. Behavioural limits, so
   *  they live here rather than in the view — same rule as the imagery
   *  sliders. The speed floor is deliberately not 0: "off" is the toggle's
   *  job, and a speed slider that can reach zero gives the user two different
   *  ways to stop the drift, one of which leaves the toggle lying. */
  autoRotateSpeedRange: Object.freeze({ min: 0.2, max: 8, step: 0.1 }),
  /** In SECONDS. Up to a minute — long enough to read a storm without the
   *  globe wandering off under it. */
  autoRotateDelayRange: Object.freeze({ min: 2, max: 60, step: 1 }),

  /** Graticule generation. Drawn in code — no tile source carries it. */
  graticuleStepDeg: 15,
  graticuleDensifyDeg: 2, // vertex spacing along each line, so lines follow
                          // the sphere's curve instead of cutting through it

  /** Storm selection flyTo. Padding is applied so the camera centers on the
   *  VISIBLE globe area, not the viewport — the bottom sheet eats the lower
   *  60%, the rail eats the left third. Centering on the viewport lands the
   *  storm underneath the panel that just opened. */
  flyToZoom: 5,
  flyToSpeed: 1.1,
  flyToCurve: 1.42,

  /** KEYBOARD CAMERA STEPS (SPEC §10).
   *
   *  Pan is expressed in DEGREES, not screen pixels. panBy() converts pixels
   *  through the projection, which on a globe means a horizontal step near the
   *  poles maps to an enormous longitude change and no step wraps the
   *  antimeridian — left/right did nothing and up/down jammed at ~180°. Idle
   *  rotation already moves the camera in degrees via setCenter and spins
   *  forever without a stop; the keyboard now uses the same model.
   *
   *  Degrees per keypress is deliberately larger than it looks: at the space
   *  floor the whole planet is on screen, so a small step reads as nothing.
   *  [DECIDE] whether this should scale with zoom — measure on glass. */
  keyPanDegrees: 8,

  /** Latitude the camera may not pass. NOT a clamp on longitude — longitude
   *  wraps, which is what makes the globe endlessly rotatable. Latitude has to
   *  stop short of ±90: a globe camera exactly at a pole has no defined
   *  up-vector and flips the view.
   *
   *  88, not 82: at 82 the stop was hit early enough to feel like a wall.
   *  This is as close to the pole as the camera can get while staying stable.
   *  There is no value here that removes the stop — that would need pan-over-
   *  the-pole (continue past 90 by flipping longitude 180 and descending the
   *  far side), which is a different feature, not a bigger number. */
  keyPanMaxLat: 88,

  /** Zoom per +/- press. */
  keyZoomStep: 0.5,
});

/* ---------------------------------------------------------------------------
 * THE 3D CLEAR GLOBE + LOCKSTEP DIVE (SPEC §2, §9 — as-built)
 *
 * The wide "planet" view is a Three.js clear globe: a see-through wireframe
 * sphere with blue-family land, a floating cyan geodesic cage, storm severity
 * read as node elevation. Zoom in and it crossfades into MapLibre, which owns
 * the basin band inward. The crossfade IS the intended effect, not a seam.
 *
 * This block replaced the old MESH block: the flat MapLibre nodal mesh was a
 * stopgap for the planet band; the 3D cage owns that band now and map/mesh.js
 * is retired.
 *
 * Every number here is a SOURCE. The globe geometry and the dive choreography
 * are arithmetic on them. Ported from a standalone transition prototype
 * (preserved on the `worlds` branch), validated on a phone before integration.
 * ------------------------------------------------------------------------- */

/* The fog band, hoisted out of the frozen object below ONLY so `fogFadeStart`
 * can be arithmetic on it — an object literal cannot read its own siblings, and
 * a second hand-typed copy of these two numbers is exactly the drift this file
 * exists to prevent. Both are re-exported as `DIVE.fogNearBack` /
 * `DIVE.fogFarAhead`; nothing outside reads these names. */
const FOG_NEAR_BACK = 1.15;
const FOG_FAR_AHEAD = 1.70;

export const DIVE = Object.freeze({
  /* --- ENTRY FRAMING ------------------------------------------------------ */

  /** Three camera distance (globe radii) — the initial/fallback framing before
   *  MapLibre can be measured. While the 3D globe is visible the camera distance
   *  is recomputed each frame from MapLibre's on-screen globe radius, so the two
   *  stay pixel-locked at every zoom (§2). */
  spaceDistance: 3.05,

  /** Three camera field of view, degrees. The per-frame globe-match depends on
   *  it, so it is a source, not a literal. */
  fov: 42,

  /** Space CEILING — the furthest-in a session may start, and the fade
   *  band's fixed lower edge. The ACTUAL space floor (starting zoom AND
   *  minZoom) is derived per-viewport in globe.js `spaceFloorZoom()`:
   *  min(zSpace, the zoom where the full globe diameter fits the viewport's
   *  short side). A wide desktop fits at z2 so nothing changes there; a
   *  phone's floor lands near z1 so the whole planet is visible at rest
   *  instead of clipped at the sides. Viewport-derived, never device-sniffed
   *  (SPEC §10). Below zSpace the crossfade p clamps to 0 — deeper space,
   *  map fully hidden, cage at full strength. */
  zSpace: 2.0,

  /** How much of the viewport's short side the globe's diameter takes at the
   *  derived floor. <1 leaves breathing room for the cage's storm spikes. */
  fitFraction: 0.86,

  /** Handoff complete — at/above this MapLibre zoom the 3D globe is fully faded
   *  and MapLibre owns the screen. The crossfade band is zSpace..zHandoff, and
   *  the fade progress p = (zoom − zSpace) / (zHandoff − zSpace). */
  zHandoff: 5.0,

  /** Globe-match fudge. 1.0 = the two globes are pixel-locked; nudge only if a
   *  device shows a seam during the crossfade. */
  scale: 1.0,

  /* --- CLEAR-GLOBE GEOMETRY ----------------------------------------------- */

  /** Icosphere subdivision → cage/node spacing. Each step up ~quadruples the
   *  node count. Raised 2 → 3 on glass (2026-07-23): with sharp storm spikes
   *  (see stormSigma) the detail-2 lattice was too coarse for a peak to have
   *  a shape — nodes sat ~8° apart, wider than the spike. Detail 3 is 642
   *  nodes / 1,920 edges / 1,280 triangles — one draw call each, three total
   *  (the triangles are the storm-lit fill, SPEC §9). Counts corrected
   *  2026-07-24: this comment claimed 2,562/7,680, which is detail FOUR.
   *  [VERIFY] frame budget on a mid-range phone; the overriding lens is feel,
   *  and if it stutters this goes back to 2 and the spike widens instead. */
  geoDetail: 3,

  /** Cage radius as a multiple of the unit globe — the nodal network floats
   *  just above the surface. */
  cageRadius: 1.065,

  /** Fill everything south of this latitude solid: the only land that far
   *  south is Antarctica, and it closes the pole cleanly. */
  poleCap: -82,

  /* --- LAND TEXTURE: TWO SIZES, AND THE REASON IS TIME-TO-FIRST-PAINT ------
   *
   * The charcoal land fill is rasterised into an equirectangular canvas at
   * runtime (map/globe3d.js `landTexture`) and draped on the sphere. Measured
   * on a cold load, the full-size canvas costs ~202 ms to rasterise and
   * ~511 ms to hand to the GPU. That 713 ms sits in front of the FIRST FRAME,
   * on the one screen where there is nothing to look at yet — and the people
   * who open a hurricane app during a hurricane are the ones who feel it.
   *
   * So the globe boots on a draft, and the full size replaces it a moment
   * later. Nothing about the final picture changes; only when it arrives.
   *
   * WHY FULL SIZE IS 4096 AND NOT PERMANENTLY SMALLER. 4096 across is 9.8 km
   * per texture pixel at the equator, against ~11.6 km per screen pixel on a
   * full-screen phone globe — just finer than the screen, which is the whole
   * point. Halving it to 2048 (19.6 km) softens visibly above ~600 px of
   * globe and takes the small Lesser Antilles from ~3.5 texture pixels to
   * ~1.7, where islands start dropping out of the render entirely. That is
   * the wrong detail for THIS app to lose, so the size stays and the cost
   * moves off the critical path instead.
   *
   * WHY THE DRAFT IS 1024 AND NOT SMALLER STILL. 1024 across is 39 km per
   * texture pixel, against ~64 km per screen pixel at the space floor — where
   * the app always boots. The draft is therefore FINER THAN THE SCREEN at the
   * size the globe actually arrives at, so it looks correct on arrival rather
   * than looking broken for a second. It only reveals itself if you zoom in
   * during the first moment, and it costs about a sixteenth of full size.
   * ------------------------------------------------------------------------ */
  landW: 4096,
  landH: 2048,
  landDraftW: 1024,
  landDraftH: 512,

  /** How long after boot before the full-size land canvas is built.
   *
   *  The build is synchronous and will jank whatever frame it lands on, so it
   *  must not land while the globe is still arriving or while someone is
   *  making their first gesture at it. Idle time is used when the browser
   *  offers it; Safari does not implement requestIdleCallback at all, so this
   *  is BOTH the idle deadline and the plain fallback delay — an idle window
   *  that never comes must not mean a globe that stays soft forever. */
  landUpgradeDelay: 1.2 * SECOND,

  /** Faint fixed unevenness so a calm (storm-free) cage isn't dead flat. */
  baseLump: 0.012,

  /* --- STORM HEIGHTFIELD (SPEC §9) ---------------------------------------- */

  /** A Cat-5 pushes a node this fraction beyond the cage radius; a TS a small
   *  bump. Severity read as elevation — the cage peaks over storms.
   *  0.22 → 0.5 on glass: the old value read as "slight bump," and a signal
   *  you have to squint for is not a signal (§5 in visual form). */
  stormAmp: 0.5,

  /** Storm influence radius in radians of arc (~9°): how wide each peak
   *  spreads across the cage. Narrowed from ~17° with geoDetail 3 — only the
   *  nodes CLOSEST to the storm spike, a sharp local peak instead of a broad
   *  regional swell. Node spacing at detail 3 is ~4°, so a 9° sigma still
   *  catches a ring of neighbors and reads as a shape, not one stray node. */
  stormSigma: 0.16,

  /** Per-frame ease as node heights rise/fall toward the storm target
   *  (~1 s settle). Not an absolute ramp — see SPEC §13. */
  liftEase: 0.06,

  /** Severity ramp for elevation. Mirrors CATEGORY_THRESHOLD_KT: TS force is
   *  the smallest visible lift, Cat 5 is full lift. This is a VISUAL ramp for
   *  the cage, not a category assignment.
   *
   *  Tuned on glass 2026-07-23: the first (linear, minLift 0.04) ramp made a
   *  40 kt TS lift nodes ~1% of the radius — LESS than baseLump, i.e. a live
   *  storm read as flat ocean, which is the §5 failure in visual form. The
   *  ramp is now lift = minLift + (1-minLift) * t^sevCurve: the sqrt curve is
   *  a perceptual boost that keeps ordering (TS ≈ 0.4, Cat 1 ≈ 0.65, Cat 5 = 1)
   *  while every real storm clears the noise floor.
   *
   *  ==> `sevMinLift` 0.16 → 0.22, AND IT IS THE FLOOR FOR A WHOLE CLASS. <==
   *  Everything at or below `sevFloorKt` clamps here — which is every tropical
   *  depression there has ever been, since 34 kt IS the tropical-storm
   *  threshold. So this is not a "noise floor for edge cases", it is the height
   *  of the depression class, and at 0.16 a live depression stood at HALF the
   *  lift of a dead storm. At 0.22 it reads as a deliberate small bump, still
   *  comfortably under a 40 kt tropical storm (0.41) and comfortably over a
   *  storm nobody is analysing (0.08). Confirmed on glass: Cristobal. */
  sevFloorKt: 34,
  sevPeakKt: 137,
  sevMinLift: 0.22,
  sevCurve: 0.5,

  /** The head lift for a storm with NO CURRENT READING — ended, or silent.
   *
   *  ==> IT IS A PLAIN NUMBER AGAIN, AND SHORTER THAN EVERY LIVE STORM. <==
   *  This was `stormColorFull + 0.02` — derived, so that a dead storm's grey
   *  would arrive at full strength. The derivation was sound and the result was
   *  backwards: buying color with height put a finished storm at 0.32 while a
   *  live tropical depression sat at 0.16. A dead storm stood TWICE AS TALL as
   *  a live one, in near-white, on the loudest channel the globe has. Confirmed
   *  by arithmetic and on glass.
   *
   *  The color band is now a fraction of each storm's OWN peak
   *  (map/heightfield.js `litAmount`), so a low mark is a fully-colored mark
   *  and height no longer has to be spent on saturation. That frees this to be
   *  what it should always have been: the SHORTEST thing on the globe that is
   *  still a thing. 0.08 is about seven times `baseLump`, so it cannot be
   *  mistaken for the cage's own unevenness, and it is a third of the weakest
   *  live storm — the ordering a reader triages on, restored.
   *
   *  NO LONGER DERIVED, deliberately. It has nothing left to be derived FROM:
   *  the color band no longer gates it, and tying it to `sevMinLift` would
   *  couple "how short is a dead storm" to "how tall is a depression", which
   *  are two independent judgements that happen to be ordered. */
  sevNoReadingLift: 0.08,

  /** Where the storm tint STARTS and where it reaches full color, as fractions
   *  of HOW FAR A NODE IS UP ITS OWN STORM'S PEAK — not of the 0..1 severity
   *  scale. A node at 30% of its storm's lift is fully that storm's color
   *  whether the storm is a Cat 5 or a depression. Everything below `onset` is
   *  pure resting cage color; the gradient lives only in the band between.
   *
   *  READ `map/heightfield.js litAmount` BEFORE RETUNING THESE. The divisor is
   *  what lets a weak storm be seen at all, and reading these as absolute lifts
   *  again would put every tropical depression back under the floor.
   *
   *  This replaced a single `stormColorGamma` exponent, which was wrong in a way
   *  that only showed on glass: a curve applied across the WHOLE lift range
   *  spread tint over nodes that were barely raised at all, so a Cat 4 sat in a
   *  wide halo of muddy purple-grey (#736077, #516479) and the peak had to
   *  compete with its own smear. Worse, the peak never reached its true hue —
   *  a TS topped out at a murky #31A67B instead of CATEGORY_COLOR.TS.
   *
   *  The band is deliberately narrow and sits at the OUTER edge of the raised
   *  region: the lifted cage is solidly its storm color, and the fade to cyan
   *  happens across roughly one ring of nodes just past the last raised one.
   *  Widen the gap for a softer, broader transition; narrow it toward a hard
   *  edge. `onset` below the ~0.05 visible-lift threshold keeps color from
   *  arriving before height. */
  stormColorOnset: 0.06,
  stormColorFull: 0.30,

  /** Beyond this many sigmas, a storm point's contribution to a node is
   *  smaller than the cage's own base unevenness and cannot be seen. Nodes
   *  further out are skipped on a DOT PRODUCT — three multiplies — instead of
   *  paying for an `acos` that would round to nothing anyway.
   *
   *  WHY IT MATTERS NOW: with one point per storm the influence loop was
   *  642 nodes x ~15 points and the cost was invisible. Following the whole
   *  track multiplies the point count by ~20, and every node was measuring
   *  its angle to every point on the planet, including storms in the other
   *  hemisphere. 3 sigma is exp(-4.5) ~ 1.1% of a point's lift — below
   *  `baseLump`, so nothing that survives this cutoff was ever visible. */
  influenceCutoffSigma: 3,

  /** Grey storm-position dots ON the 3D globe surface at the planet band
   *  (SPEC §9 zoom ladder: "grey position glyphs"). Riding just above the
   *  land so they never z-fight the fill; the cage floats far above at
   *  cageRadius. They fade with the nodes during the dive, handing off to
   *  MapLibre's own grey dots as the map fades in. */
  stormDotRadius: 1.012,

  /* --- DISTANCE FOG, AND THE HAZE INSIDE THE SPHERE ----------------------- *
   *
   * The fog band is set relative to the CAMERA every frame, not to the world,
   * so the far hemisphere recedes by the same amount at any zoom. Fixed planes
   * went black when the camera pulled back. In globe radii, from the camera:
   * fog starts `fogNearBack` in FRONT of the globe's centre and ends
   * `fogFarAhead` BEHIND it, so the band always straddles the sphere.
   *
   * These were literals in map/globe3d.js. They live here now because
   * `fogFadeStart` below is arithmetic on them, and a hand-set copy of a
   * derived number is the exact drift SPEC §12 forbids. */
  fogNearBack: FOG_NEAR_BACK,
  fogFarAhead: FOG_FAR_AHEAD,

  /* --- HOW FAR BACK THE HAZE STARTS -------------------------------------- *
   *
   * Fog only recolours; map/fog-fade.js adds the missing half and fades ALPHA
   * with depth as well, which is what stops the light theme's far-side lattice
   * reading straight through the planet. That fade must not touch the near
   * shell — in the light theme the coastline is all that separates the
   * continents from the bloom behind them, and a translucent limb would give
   * that away for a problem that lives on the other side of the globe.
   *
   * So the haze starts exactly at the LIMB: the fog factor at the terminator,
   * where depth equals the camera distance. Three's linear fog is a smoothstep
   * across the band, so that is `smoothstep(fogNearBack / span)` and NOT the
   * 0.40 a linear reading gives. Derived from the two numbers above rather
   * than typed, so moving the band moves this with it.
   *
   * For orientation, the three values it produces: near pole 0.008, limb
   * 0.357, far pole 0.849. Everything from the limb back is remapped 0..1
   * across that last stretch. */
  fogFadeStart: (() => {
    const t = FOG_NEAR_BACK / (FOG_NEAR_BACK + FOG_FAR_AHEAD);
    return t * t * (3 - 2 * t);
  })(),

  /* --- FADE CHOREOGRAPHY (crossfade progress p, 0..1) --------------------- *
   * p is derived from the live MapLibre zoom (see zSpace/zHandoff), NOT a
   * timeline — you drive it by zooming. Each pair is [start, end] of a
   * smoothstep.
   *
   * LAND AND COAST GO FIRST, deliberately inverted from the cage and nodes.
   * They used to hold until 0.62 (z3.9) while mapIn completed at 0.30 (z2.9),
   * so for a full zoom level TWO opaque planets were stacked: the 3D globe's
   * far-side grey coastline composited over a finished MapLibre canvas, which
   * read on glass as a shadow lying across storm tracks and cones. It is not a
   * depth bug and cannot be fixed with renderOrder or depthWrite — the two
   * renderers are separate canvases with separate depth buffers and cannot
   * occlude each other, so opacity is the only lever.
   *
   * The rule now: the moment MapLibre can draw coastlines itself, the 3D
   * versions are duplicated information and must be gone. The cage and nodes
   * are the planet-band AESTHETIC, not duplicated data, so they still linger
   * and are the last thing to dissolve.
   *
   * THE CAGE'S LINGER IS NOT A BUG, and pulling it in does not fix shadowing.
   * These were briefly shortened to 0.10-0.40 to chase far-side lattice
   * appearing over storm tracks. That was treating a symptom: the real cause
   * was NORMAL BLENDING on the far-side land and coast, which painted fogged
   * near-black over MapLibre (see matLandBack in globe3d.js). Those surfaces
   * are additive now and cannot darken anything beneath them, so the cage is
   * free to dissolve slowly again — which is what makes the handoff feel like
   * a dive instead of a cut. Restored to 0.14-0.60 / 0.16-0.62.
   *
   * If something in the 3D scene ever appears to shadow MapLibre content
   * again, check its BLENDING before touching these numbers. */
  fade: Object.freeze({
    nodes:    Object.freeze([0.14, 0.60]),
    cage:     Object.freeze([0.16, 0.62]),
    land:     Object.freeze([0.10, 0.30]),
    mapIn:    Object.freeze([0.00, 0.30]),
    spaceOut: Object.freeze([0.00, 0.34]),
  }),
});

/* ---------------------------------------------------------------------------
 * MESH TRACK — the cage ridge that follows a storm's whole path (SPEC §9)
 *
 * The cage lifts over storms. By default it lifts over ONE position each: the
 * current fix. Set to `track`, it lifts over the storm's past positions and
 * its forecast positions too, each at that position's own intensity — the
 * globe grows a ridge along the whole path instead of a single peak.
 *
 * HEIGHT IS INTENSITY. NOTHING ELSE. A bead stands at the wind speed measured
 * (or forecast) at that position, so the tallest point on a storm's ridge is
 * its strongest point — past, present or future — wherever that falls.
 *
 * IT USED TO TAPER WITH AGE AND LEAD TIME AND THAT WAS WRONG (removed
 * 2026-07-25, on glass). The argument for it was that a forecast rendered as
 * tall as a measurement is a prediction drawn as fact (§5). Two things kill it:
 *
 *   1. IT BROKE §9's CENTRAL INVARIANT. Color is each position's true category
 *      and was never tapered, so a Cat 4 three days old rendered SHORT and red
 *      beside a taller orange Cat 2. "Elevation and color are one signal from
 *      one number" — the taper made height a blend of intensity and recency
 *      while color stayed pure intensity, which is exactly the drift this app
 *      has already fixed once at this seam.
 *   2. NOTHING ELSE IN THE APP DIMS THE FORECAST. Cones, forecast tracks,
 *      forecast wind bands and forecast dots all draw at full strength.
 *      "This is a forecast" is carried by shape and line grammar (§7), never
 *      by rendering it fainter. The cage was the only surface arguing
 *      otherwise.
 *
 * WHERE THE STORM IS NOW is not height's question to answer. The live fix
 * carries the spiral glyph and it is the ONLY point that does (§9), so the
 * present position stays unmistakable without borrowing a channel that
 * belongs to severity.
 */

/* ---------------------------------------------------------------------------
 * STORM LIGHT ON THE BACKDROP (map/limb-glow.js).
 *
 * Every live storm throws soft colored light onto the space gradient behind
 * the globe, so spinning the planet sweeps color across the background. The
 * mechanism, the layer order it depends on, and why both themes need
 * different blend maths are all written up in map/limb-glow.js's header.
 *
 * These are the dials. The two that actually change the look are `intensity`
 * and `radiusScale`; the rest exist so nothing in that file is an unexplained
 * number.
 * ------------------------------------------------------------------------- */
export const GLOW = Object.freeze({
  /** Buffer size as a fraction of the CSS viewport. A field of soft radial
   *  falloffs has no high-frequency detail to lose, so it is drawn small and
   *  scaled up. This is the whole performance story: a fifth-scale buffer is a
   *  twenty-fifth of the pixels, which is what makes a dozen overlapping fills
   *  affordable on a phone where a dozen full-size sprites would not be.
   *
   *  ==> THE BROWSER'S UPSCALE IS NOT THE SMOOTHING. IT WAS THE WEAVE. <==
   *  This file used to claim bilinear magnification was free extra smoothing.
   *  It is the opposite. An 8-bit canvas can only hold `intensity * 255` — 41
   *  distinct alpha values at the shipped strength — so the falloff quantises
   *  into contour bands INSIDE the small buffer, and bilinear magnification
   *  then stretches every band boundary into a straight facet along the texel
   *  grid. The result is a fine crosshatch, which is exactly what Aaron
   *  reported on glass, 2026-08-21: "there's a weird grid/weave pattern in the
   *  reflection, it's not smooth. It is not my monitor." He was right.
   *
   *  Raising this only makes the weave finer, never absent — the band count is
   *  set by alpha depth, not by resolution. The cure is the CSS blur on `#glow`
   *  (`--glow-blur` in index.html), which dissolves the contours AFTER the
   *  upscale, where they are made. With the blur carrying the smoothing this
   *  number is free to go DOWN and pay for it. */
  pixelScale: 0.2,

  /** Floor on either buffer dimension. Below roughly this the falloff starts
   *  quantising into visible rings on a narrow window. */
  minBufferPx: 96,

  /** How many lights the sky can carry at once.
   *
   *  Raised from 8 on 2026-08-18, when a light stopped being "one per storm"
   *  and became "one per run of one color along a storm's ridge" (see
   *  `buildLights` in map/limb-glow.js). A storm that has crossed three
   *  categories in its window now spends three slots, so the old budget would
   *  have silenced whole storms on a busy day. A typical Atlantic + Pacific
   *  afternoon lands around a dozen.
   *
   *  Still a real ceiling and not a formality: these are radial-gradient fills
   *  and they are the entire cost of this layer. It is affordable only because
   *  the buffer is a sixteenth of the screen (`pixelScale`). Past the cap the
   *  budget is spent biggest-run-first, but every storm keeps its own biggest
   *  run before any storm keeps its second. */
  maxLights: 16,

  /** Blob radius as a multiple of the globe's measured on-screen radius, at
   *  full severity. Above ~1.4 the lights stop reading as coming FROM the
   *  globe and start looking like weather on the camera lens. */
  radiusScale: 1.15,

  /** Radius of the SMALLEST run — a single bead — as a fraction of the above.
   *  Not zero: a category a storm only touched for one fix should throw a
   *  small light, not no light, or the ridge shows a color the sky denies. */
  radiusFloor: 0.55,

  /** How many beads of one color a run needs before its light is at full size.
   *  This is the whole of "unless there is just more of it": below it a run
   *  scales with its length, at or above it every long run looks the same, so
   *  a week at Cat 1 cannot swamp everything else simply by being long. */
  runFull: 10,

  /** Minimum distance from grey (0..255) a color needs to throw a light at
   *  all. `stormSwatch` paints a storm nobody is publishing a wind for in the
   *  theme's neutral, and a neutral light is a claim with no content: under
   *  the light theme's `color` blending it tints nothing anyway, and under
   *  dark's additive blending it would render as a plain white wash on a
   *  system the source has gone quiet about. §5 — say nothing rather than
   *  something unsupported. Every §6 category color clears this comfortably;
   *  the lowest is Cat 1 yellow at 178. */
  minChroma: 24,

  /** ==> MASTER STRENGTH, BEFORE THE THEME'S `fx.glow` MULTIPLIER. NOTHING
   *  ELSE SCALES IT. <==
   *
   *  Severity used to, and that was a bug on glass (2026-08-18): elevation on
   *  the cage is already severity, said in the loudest channel the globe has,
   *  and multiplying the light by it too left a depression's glow too faint to
   *  find beside a hurricane's. Every color now shines at one strength and the
   *  only thing that can make one read louder is covering more sky — which is
   *  `runFull` below, off how much ridge wears that color.
   *
   *  0.85 -> 0.42 -> 0.16, and the second cut is the one that matters. The
   *  original 0.85 was a CEILING that a typical storm's severity pulled down to
   *  about 0.5, on ONE light per storm. Flat strength across a dozen
   *  OVERLAPPING lights is a completely different sum: in light mode they stack
   *  toward opaque, and the whole screen went to a saturated wash. Aaron on
   *  glass, 2026-08-18: "it should just be a faint, non-distracting glow on the
   *  background."
   *
   *  ==> IT IS A CEILING PER STORM, NOT PER RUN, AND THAT DISTINCTION WAS A
   *  BUG ON GLASS. <== One light per color run means a storm that climbed
   *  TD -> TS -> Cat 1 -> 2 -> 3 -> 4 spends SIX slots, and the six land close
   *  together because categories change fastest near a storm's peak. Under
   *  dark's additive blend those six stacked to 0.96 alpha — a near-white hot
   *  spot — while a storm that stayed a depression drew one run at 0.16. So
   *  the light really was proportional to the cage's height, by way of how
   *  many categories the ridge crossed, even though no term here multiplies by
   *  severity. Aaron on glass, 2026-08-21: "the light intensity is
   *  proportional to the height of the mesh and I don't want it to be."
   *
   *  Each storm is now composited through its own scratch buffer, so its runs
   *  blend with each other instead of summing and the storm's brightest point
   *  is exactly this number however many colors it wears (map/limb-glow.js).
   *  Storms still stack with EACH OTHER additively in dark — two separate
   *  lights on a wall really are brighter than one, and that is a true count
   *  of live systems rather than a restatement of one storm's severity.
   *
   *  ==> THIS IS BACKDROP MOOD, NOT A READOUT. <== Nothing is read off it —
   *  severity is the cage's height and the glyph's color, and both are still at
   *  full strength. The light is atmosphere behind them, so the bar it has to
   *  clear is "present", not "legible". If it is competing with the globe for
   *  attention it is wrong however pretty it is. First dial to reach for. */
  intensity: 0.16,

  /** ==> THE BACKDROP IS A CURVED SHELL, THIS FAR OUT IN GLOBE RADII, AND THIS
   *  IS THE ONE NUMBER THAT DECIDES THE WHOLE LOOK. <==
   *
   *  A storm is a lamp on the globe's skin aiming straight outward, so the
   *  point its beam strikes a CONCENTRIC shell is just its own direction
   *  scaled up — no intersection to solve, one multiply.
   *
   *  A FLAT wall was tried first and is wrong for a reason worth keeping: at
   *  the limb the beam runs parallel to a flat plane and either misses it or
   *  lands a hundred radii off-screen. The limb is exactly where this effect
   *  lives, so the surface has to curve around with the globe.
   *
   *  Small numbers hug the rim as a tight halo — and BELOW about 1.3 this
   *  collapses into a rim highlight ON the globe, which is the Fresnel effect
   *  this was built to avoid. Large numbers throw the light wide and low, and
   *  past roughly 2.0 the brightest part lands off the side of a phone. */
  wallRadius: 1.7,

  /** The globe hides light that lands behind it. Clearance fades from nothing
   *  at `rimInner` to full at `rimOuter`, both as fractions of the globe's
   *  on-screen radius — so a light SWELLS as its storm rotates past the limb
   *  and dies as it goes deeper behind, rather than popping at the edge.
   *
   *  This is half of what confines the effect to a band. The other half is the
   *  aim: pointing away from the camera is zero at the limb and grows as a
   *  storm rotates behind, while clearance is full outside the disc and falls
   *  as the landing point slides inward. Their product peaks just past the
   *  limb, and that peak sweeping around the edge IS the effect. */
  rimInner: 0.85,
  rimOuter: 1.05,

  /** ==> THE FALLOFF IS FLAT-TOPPED, AND THAT IS WHAT STOPS IT READING AS A
   *  LAMP. <==
   *
   *  A bright point that fades outward is the visual signature of a SOURCE.
   *  That is what the eye is built to find, and it found it: the profile used
   *  to peak hard at the centre (a mid stop at 0.32 holding 62% of the alpha),
   *  so every light had a findable hot spot sitting directly outward from its
   *  storm's ridge. Aaron on glass, 2026-08-21: "it looks like there is a
   *  floating light source above the raised mesh... I only want to see the
   *  light reflected onto the background. I don't want to see a source."
   *
   *  Reflected light on a wall has no centre to find. So the alpha now holds
   *  essentially flat across the inner `plateauStop` of the radius and only
   *  then falls, over a long tail. There is no peak, so there is nothing to
   *  read as a bulb — what is left is a colored region of backdrop, which is
   *  the whole ask.
   *
   *  `coreStop`/`coreAlpha` are the shaping stop on the TAIL. Without one the
   *  fall from the plateau is a straight ramp and reads as a disc with a soft
   *  edge; with it the shoulder rolls off. The alpha still reaches exactly
   *  zero at the rim in both themes, which is the identity for `lighter` and
   *  for `color` alike, so the blob has no edge to catch the eye either way. */
  plateauStop: 0.30,
  plateauAlpha: 0.94,
  coreStop: 0.62,
  coreAlpha: 0.40,

  /** ==> LIGHT ON A CURVED WALL IS AN ARC, NOT A DISC. <==
   *
   *  A round pool is what a flat wall hit square on gives you. This wall
   *  curves away, and the further past the limb a storm has rotated the more
   *  GRAZING its beam — so the patch stretches along the curve and thins
   *  across it. Both scale with the aim term, so a storm at the limb throws a
   *  round pool and grows into a smear as it rotates behind, animating through
   *  the sweep off a number already being computed.
   *
   *  `smear` is the tangential stretch at full aim: 1.4 makes the major axis
   *  2.4x the minor at the deepest visible angle. The major axis runs ALONG
   *  the rim — stretching radially instead would read as a beam pointed at the
   *  viewer, which this geometry says cannot be happening.
   *
   *  `squash` is the radial thinning, and it is not decoration. Stretching
   *  alone inflates the lit area, and area is brightness once the falloffs
   *  overlap; thinning across the curve keeps a smeared light roughly as
   *  strong as a round one rather than blooming as it elongates. Raising
   *  `smear` without raising this is what makes deep storms too bright. */
  smear: 1.4,
  squash: 0.35,

  /** ==> WHAT A STORM POINTED STRAIGHT AT YOU IS WORTH, AGAINST ONE POINTED
   *  STRAIGHT AWAY. <==
   *
   *  There used to be no number here — a storm on the near side of the planet
   *  was culled outright and threw no light at all. That meant a Cat 4 sitting
   *  in plain view on the front of the globe lit nothing while a weaker storm
   *  at the edge glowed, which is what came back off glass 2026-08-18.
   *
   *  Below 1 on purpose. The shell curves all the way around, so a near-side
   *  lamp really does throw its beam past the planet onto backdrop you can
   *  see — but it lands further out, spread wider and hit more squarely, and a
   *  grazing beam near the limb is genuinely the brighter event. The sweep
   *  round the edge stays the hero; this is the quieter half of the same
   *  effect. At 1 the two become indistinguishable and the globe just sits in
   *  a permanent even halo. */
  frontGain: 0.42,

  /** ==> WHAT SURVIVES WHEN THE LIGHT LANDS FULLY BEHIND THE PLANET. <==
   *
   *  Also new, and also replacing a cull: light whose landing point slid
   *  inside the globe's disc used to be dropped, so a glow did not fade as its
   *  storm rotated behind the globe, it fell off a cliff.
   *
   *  The planet covers the MIDDLE of a light that lands behind it. It does not
   *  delete it: the blob is over a globe radius across, so its falloff still
   *  spills past the silhouette all the way round, and the dark theme's ocean
   *  is translucent, so the covered part shines through as well. Not 1 —
   *  a light behind the planet IS more hidden than one in open sky, and losing
   *  that difference flattens the sweep into a permanent ring. */
  rimFloor: 0.5,

  /** Camera-space depth guard, in globe radii. A point closer to the eye than
   *  this is refused rather than projected: past the eye plane the perspective
   *  divide flips sign and would place the storm on the OPPOSITE side of the
   *  screen at full brightness. Unreachable at the space floor, reachable once
   *  `matchDistance` has pulled the camera in. */
  nearGuard: 0.05,

  /** Dive fade band on the crossfade's p (0..1), same shape as DIVE.fade.
   *
   *  DELIBERATELY EARLIER THAN THE CAGE'S. The light is a planet-band mood
   *  piece — it belongs to the view where the whole globe is on screen and
   *  there is backdrop around it to catch anything. By the time MapLibre has
   *  faded up there is no visible backdrop left for light to land on, so a
   *  glow still going at that point is just a colored wash over the map. */
  fade: Object.freeze([0.08, 0.46]),
});

/* ---------------------------------------------------------------------------
 * THE GLASS RIM AT THE HORIZON (map/limb-rim.js, SPEC-MAP.md §9.17).
 *
 * Once MapLibre owns the picture, the globe's edge has nothing marking it.
 * MapLibre draws NOTHING outside the sphere — its atmosphere pass is switched
 * off (§9.6) and on the globe projection its whole `sky` block is inert — so
 * the pixel just outside the limb is the CSS backdrop and the pixel just
 * inside it is the sea. In the light theme those are the same colour by
 * design (`space` is set to `ocean` exactly, see config/tokens.js), so the
 * planet dissolves into the page. On a wide monitor that edge is still on
 * screen well after the 3D globe has gone.
 *
 * This is a soft ring painted ON the limb: an edge all the way round, plus a
 * brighter arc on one side so it reads as light catching curved glass rather
 * than as an outline someone drew.
 *
 * WIDTHS ARE IN CSS PIXELS, NOT IN GLOBE RADII, and that is both a look call
 * and the performance story. A rim is a lit EDGE; edges do not get fatter
 * because you walked closer. Fixed widths also keep the painted area to a
 * band 2*pi*r*w wide instead of something that grows with the square of the
 * zoom.
 * ------------------------------------------------------------------------- */
export const RIM = Object.freeze({
  /* ==> THE RING LIVES INSIDE THE LIMB. IT USED TO STRADDLE IT, AND THAT WAS
   * THE FIRST VERSION'S WHOLE PROBLEM. <==
   *
   * It shipped 10 px inside and 44 px outside, so four fifths of the ink sat
   * beyond the planet. Aaron's verdict on glass, 2026-08-21: "it doesn't look
   * like glass and it's sitting outside the horizon." The measurement was not
   * the fault — the peak was on the true edge to within a tenth of a pixel —
   * the PROFILE was.
   *
   * the Deep globe on the `worlds` branch had already written this down
   * and it is worth quoting, because it is the same mistake: "every earlier
   * version drew a hoop. They were all separate shells, and a shell is
   * brightest at its OWN edge... Lighting the ball's own front face instead
   * puts the bright edge exactly at the silhouette." A halo around a planet is
   * an ATMOSPHERE. Light on the planet's own surface is GLASS. This app is
   * asking for the second one, and the second one has nothing outside the
   * silhouette at all.
   *
   * That also makes the honest geometric read the cheap one: a real limb
   * highlight IS a Fresnel term on the sphere's front face, which by
   * construction cannot reach past the edge. */

  /** How far inward the highlight reaches, as a fraction of the limb radius.
   *  A FRACTION, not a pixel count: the falloff is a property of how steeply
   *  the surface is turning away, so it scales with the ball. The clamps below
   *  are what keep the painted band — and therefore the cost — bounded at the
   *  extremes. */
  reachFrac: 0.09,
  reachMinPx: 22,
  reachMaxPx: 130,

  /** How far the highlight bleeds OUTSIDE the limb, CSS px. Nearly nothing,
   *  and not zero: the planet's edge is genuinely hard, but a razor cut on a
   *  curve reads as a jagged polygon rather than as an edge. This is the width
   *  of the softening and nothing else. **If it ever needs to be more than a
   *  few pixels, the answer is a different effect, not a bigger number.** */
  bleedPx: 3,

  /** Peak alpha, AT the limb, before the theme's own `fx.rim` multiplier and
   *  before either fade. */
  intensity: 0.55,

  /** The inward falloff, as two points on the curve. Both are fractions of the
   *  inward reach — 0 is the inner end of the band, 1 is the limb itself.
   *
   *  Well below a straight line on purpose. A linear ramp inward reads as a
   *  painted band with a soft inner edge; a real limb highlight is
   *  concentrated hard against the silhouette and gone a moment later, which
   *  is what these two stops shape. */
  tailStop: 0.55,
  tailAlpha: 0.10,
  shoulderStop: 0.86,
  shoulderAlpha: 0.45,

  /** ==> WHERE THE LIGHT IS, AND IT IS NOT A NEW OPINION. <==
   *
   *  These are the coordinates of the space backdrop's own light source:
   *  `#spacebg` in index.html is `radial-gradient(120% 120% at 42% 30%, ...)`,
   *  so the app already says the light comes from up and slightly left of
   *  centre. The glare direction is DERIVED from this pair rather than typed
   *  as an angle, so the ring and the backdrop can never disagree about where
   *  the light is. If the gradient in index.html moves, move these with it.
   *
   *  Fractions of the viewport, matching the CSS. */
  lightAt: Object.freeze([0.42, 0.30]),

  /** The lit arc, as a MIX FRACTION rather than an ink quantity — 1 is fully
   *  `atmosphereDeep` at the lit point, 0 leaves the ring its own colour.
   *
   *  ==> IT CANNOT ADD INK, BY CONSTRUCTION. <== The arc is composited
   *  `source-atop`, so its alpha only decides how far the ring's colour is
   *  pulled toward the arc's; the ring's radial falloff is untouched. That is
   *  not a nicety — painted with plain alpha this pass has no falloff of its
   *  own (it is a LINEAR gradient, flat across the band) and lays a slab with a
   *  square cut at the inner diameter. Aaron, on glass, 2026-08-21: "you still
   *  aren't fading in the inner edge, the inside diameter." See map/limb-rim.js.
   *
   *  How much the arc changes the ring, and how quickly it falls off around
   *  the circle.
   *
   *  A LINEAR GRADIENT ACROSS THE RING IS NOT AN APPROXIMATION OF AN ANGULAR
   *  ONE — it is the same function. On a circle of radius r the screen-space
   *  normal at angle t is (cos t, sin t), so `dot(normal, light)` is
   *  cos(t - tLight), and that is exactly what a linear gradient running along
   *  the light direction evaluates to at the point (cx + r cos t, cy + r sin t).
   *  The 2D canvas has no angular gradient and does not need one. */
  glare: 1.0,
  /** Alpha of the glare pass at the ring's mid-line (90 degrees round from the
   *  lit point). Not 0: real glass carries a little light all the way round,
   *  and a hard terminator on the ring is the thing that reads as a drawn
   *  half-moon. */
  glareMid: 0.18,

  /** ==> WHEN THE RING STOPS BEING WORTH DRAWING. <==
   *
   *  With the globe centred, the limb circle is entirely off screen once its
   *  radius passes the viewport's half-diagonal. Fractions of that: fully lit
   *  below the first, gone at the second. The second is slightly over 1 so the
   *  last sliver leaves the corners before the layer switches off rather than
   *  blinking out while still visible.
   *
   *  ==> THESE ZOOMS ARE MEASURED IN A REAL BROWSER, NOT DERIVED, AND THE
   *  DERIVED ONES WERE WRONG BY ABOUT 4%. <== The obvious closed form — globe
   *  radius worldSize/2pi, MapLibre's default field of view, solve for the
   *  tangent — comes out low at every zoom. WHY it is low has NOT been run
   *  down, and the guess that went in here first (that MapLibre's clipping
   *  plane is permissive) was checked and is wrong: swept against the live
   *  transform, the projected radius peaks at the exact arc where the
   *  occlusion flag flips, and `limbRadiusPx` returns that same figure to a
   *  tenth of a pixel. So one of the two inputs to the formula is not what it
   *  is assumed to be. That question is open and it does not need answering,
   *  because nothing in the app uses the formula — this is a note so the next
   *  session does not re-derive it and trust the answer.
   *
   *  Bisected against the live layer, full-window viewports: the rim switches
   *  off at z5.65 on 3440x1440, z4.67 on 1920x1080, z4.31 on 1512x945, and
   *  z3.02 on a 390x844 phone — where it only appears at all from about z2.5,
   *  since below that the 3D globe still owns the picture. This layer is a
   *  WIDE-SCREEN feature that costs a phone almost nothing, which is what
   *  makes it affordable. */
  offScreen: Object.freeze([0.90, 1.04]),

  /** Below this on-screen radius, in CSS px, there is no ring to draw — the
   *  band would be wider than the globe. Only reachable on a very small
   *  viewport at the space floor, where the 3D globe owns the picture anyway. */
  minRadiusPx: 40,

  /** How far off the view centre the limb probe is taken, degrees of arc.
   *  `limbRadiusPx` bisects along a great circle from the centre through a
   *  second point and needs one that is neither the centre nor its antipode;
   *  the ANSWER does not depend on which direction is chosen, because with no
   *  tilt the limb is a circle. Ten degrees is comfortably clear of both
   *  degenerate ends at every zoom. */
  probeDeg: 10,
});

export const MESH_TRACK = Object.freeze({
  /** How far back the ridge reaches, in hours.
   *
   *  ==> THE SETTING SAYS "FULL TRACK" AND NOW IT IS ONE. <==
   *  This was 72 — three days — on the argument that a week of track wraps a
   *  third of the planet and reads as a smear. The argument was never tested;
   *  what it produced was a ridge visibly SHORTER at both ends than the track
   *  line drawn on the map beside it, under a setting labelled "Full track"
   *  and a sentence promising "each storm's whole path". Two surfaces
   *  disagreeing about the same storm reads as a rendering fault, not a
   *  choice. Aaron's call, 2026-08-13: show the whole thing.
   *
   *  336 h is fourteen days, comfortably past the longest Atlantic or Pacific
   *  cyclone on record, so in practice this reaches the first fix NHC
   *  publishes. It is a bound rather than `Infinity` only so that a feed that
   *  ever hands back a bad timestamp cannot drag a bead into the last century.
   *  If a storm ever outlives it, the ridge shortens at the far end and
   *  everything else is unaffected — degrade, never blank. */
  pastHours: 336,

  /** How far ahead the ridge reaches, in hours. 120 is NHC's own forecast
   *  horizon and JTWC's, so this is the whole published forecast and not a
   *  slice of it. Was 72, which silently dropped days four and five of every
   *  five-day forecast — including the taus where the storm is often at its
   *  strongest. */
  forecastHours: 120,

  /** Hard cap on ridge points per storm after windowing.
   *
   *  Sized for the OPEN window above, not the old three-day one. NHC past
   *  fixes are 6-hourly, so a two-week storm is ~56 of them, plus nine
   *  forecast taus out to 120 h — call it 65 at the extreme, against a typical
   *  storm's 20 to 30. 96 clears the extreme with room, so this stays what it
   *  was built to be: a guard against a source that starts publishing hourly,
   *  not a routine trim. Hitting it thins by dropping every other point rather
   *  than truncating, so a capped ridge still spans the whole window.
   *
   *  IT IS ALSO THE COST CEILING. Every point is tested against every cage
   *  node on a recompute (map/heightfield.js `influenceAt`), so this number
   *  times the storm count is the work a poll does. At 96 and fifteen storms
   *  that is 642 x 1,440 dot products — three multiplies each, most rejected
   *  on the first compare. Raise it knowing what it buys. */
  maxPointsPerStorm: 96,
});

/* THE SCOPE FILTER IS GONE, retired 2026-07-25.
 *
 * It was three buttons — All / My basin / Near me — sitting above a list that
 * has never held more than nine rows. A filter earns its space by removing
 * work; scrolling past two storms is not work, and the control cost a row of
 * chrome at the top of the one surface that is also the app's whole
 * accessibility layer. Home still SORTS the list (nearest first) and still
 * puts a distance on every row, which is the part that was actually doing
 * something. `SCOPE`, `SCOPE_RADIUS_NM`, `filterByScope`, and
 * `availableScopes` all went with it rather than being left as dead exports.
 */

/* ---------------------------------------------------------------------------
 * CLOSEST APPROACH (SPEC §8)
 *
 * A great-circle minimum over a 5-day track is easy to compute and easy to
 * report as nonsense, because the shortest path between two far-apart points
 * does not run the way a map makes it look.
 *
 * MEASURED, NOT ASSUMED. NOUL-26 from a Baton Rouge home (-91.0, 30.35) reads
 * 7,315 nm now and 7,085 nm at its forecast minimum — closer every hour,
 * because the great circle from Louisiana to the West Pacific crosses Alaska.
 * The geometry is right. The sentence "closest approach in 2 days" built from
 * it, over a typhoon bound for Taiwan, is not.
 *
 * A CYCLONE IS EPHEMERAL, NOT ORBITAL. It lives days and dies, and it never
 * comes round the far side. So an approach is only a real approach when the
 * storm is near enough for the track to mean anything, far enough ahead to be
 * a forecast rather than the present moment, and closing by enough to be more
 * than track wobble. These three numbers are those three tests.
 * ------------------------------------------------------------------------- */

export const APPROACH = Object.freeze({
  /** Great-circle distance, NAUTICAL MILES, beyond which a storm is "never
   *  near home" no matter what its track does.
   *
   *  ITS JOB SHRANK, DELIBERATELY. It used to decide whether an approach was
   *  reported at all, which made it a story-switch: two East Pacific storms
   *  both bound for Hawaii, 1,408 nm and 2,368 nm out, read as two completely
   *  different situations because one fell either side of the line. Now it
   *  only picks which true sentence to use about a storm that IS closing, and
   *  a storm drifting across it changes a few words rather than the meaning.
   *  1,500 nm is roughly a basin's width. */
  relevanceNm: 1500,

  /** How much nearer the storm must actually get, NAUTICAL MILES, before its
   *  track counts as bringing it closer at all. Also the deadband for the
   *  list-row trend.
   *
   *  THIS IS NOW THE MAIN TEST, because it is what the words on screen claim:
   *  "never closer than current position" is a statement about the track, not
   *  about distance. Under this margin the storm is at its nearest now and the
   *  rest is arithmetic noise — a storm passing broadside crosses its minimum
   *  almost flat, and without a deadband the label flips between polls. Well
   *  under NHC's ~100 nm three-day track error, so it never suppresses a real
   *  approach. */
  minGainNm: 25,

  /** How far ahead the LIST ROW projects a storm along its published heading
   *  and speed, HOURS. The list has no forecast track — geometry is fetched
   *  only on selection — so the row trend is dead reckoning from `headingDeg`
   *  and `speedKt`. At a typical 12 kt that is ~144 nm of travel, comfortably
   *  past the deadband above while staying inside the window where a storm
   *  holds its heading. */
  trendProbeHours: 12,
});

/* ---------------------------------------------------------------------------
 * WHICH WAY THE STORM IS POINTING (SPEC-UI §16.4)
 *
 * The arrow on the list row, the detail panel and the home dashboard is a
 * COMPASS heading — where the storm is travelling — and not the old ↗/↘ pair,
 * which meant "closing" and "receding" and pointed nowhere real.
 *
 * TWO SOURCES, IN ORDER, AND NEVER A THIRD. The agency's own published motion
 * first (NHC publishes `movementDir`; JTWC fills it in for the GDACS storms it
 * warns on). Failing that, the bearing from the storm's current position to
 * the first forecast point far enough away to define one. Failing BOTH, no
 * arrow at all — an invented direction on a safety-adjacent screen is the §5
 * fabrication, and a missing mark reads as "not stated" while a wrong one
 * reads as fact.
 * ------------------------------------------------------------------------- */

export const MOTION = Object.freeze({
  /** How far the first forecast point must be from the current position,
   *  NAUTICAL MILES, before the line between them is allowed to define a
   *  heading.
   *
   *  ==> WITHOUT THIS THE ARROW SPINS. <== A forecast point almost on top of
   *  the current fix is two roundings of the same latitude, and the bearing
   *  between them is noise — it swings through ninety degrees between polls on
   *  a storm that has not turned at all. 30 nm is about two and a half hours of
   *  travel for a typical 12 kt cyclone, comfortably above the ~0.1° position
   *  rounding both feeds publish, and well under a first forecast hour.
   *  Points nearer than this are skipped, not rejected — the walk carries on
   *  down the track until one is far enough. */
  minTrackNm: 30,

  /** How far down the forecast track the walk will go looking for that point
   *  before giving up. A guard, not a tuning dial: if the first four published
   *  hours are all inside `minTrackNm` the storm is barely moving, and a
   *  heading derived from hour five would be a claim about tomorrow dressed as
   *  a claim about now. */
  maxProbePoints: 4,
});

/* ---------------------------------------------------------------------------
 * THE FORECAST-ERROR BAND (SPEC-UI §8, the home dashboard)
 *
 * "Closest pass 36 miles south" is a true sentence that can be quietly
 * misleading, and Bertha is the case that proves it: measured against a New
 * Orleans home, her Advisory 10 track passes 31.3 nm away 25 hours out — and
 * NHC's own two-thirds error circle at 25 hours is 39.8 nm. Two thirds of past
 * official forecasts would therefore have put that storm ON the house. A
 * closest-approach figure shipped without its band is the §5 failure in
 * miniature: an accurate number under a false impression.
 *
 * THESE ARE NHC'S NUMBERS, NOT OURS, AND THEY ARE COPIED NOT COMPUTED. They
 * are the radii of the circles the official cone is drawn from, published at
 * https://www.nhc.noaa.gov/aboutcone.shtml. Each is sized so two thirds of the
 * previous five years' official forecast errors fall inside it. Deriving a
 * band from anything else — a model spread, a percentage of distance, our own
 * arithmetic on past tracks — would be inventing an error bar and putting
 * NHC's authority on it.
 *
 * REPUBLISHED EVERY YEAR, AROUND THE START OF THE SEASON, and the year is in
 * the name so a stale table is visible rather than silent. When NHC posts the
 * next set: add a new constant, do not edit this one in place, and let the
 * lookup pick by year.
 *
 * TWO TABLES BECAUSE THERE ARE TWO. The Atlantic and the eastern/central
 * Pacific have measurably different skill — 200 nm against 138 nm at five
 * days — and using one basin's error bar on the other's storm is a fabricated
 * figure wearing a real source's name.
 *
 * NOTHING FOR THE REST OF THE WORLD, DELIBERATELY. JTWC and GDACS publish no
 * equivalent table, so a west Pacific or Indian Ocean storm gets NO band
 * rather than the Atlantic's. §5: a missing band reads as "not stated", a
 * borrowed one reads as fact.
 * ------------------------------------------------------------------------- */

/** Forecast hour → two-thirds error circle radius, NAUTICAL MILES.
 *  Ascending by hour; the lookup interpolates between rows and clamps at
 *  both ends. 2026 season, from error statistics over 2021–2025. */
/* ==> ONE TABLE PER SEASON, BECAUSE A STORM BELONGS TO A SEASON. <==
 * NHC republishes these radii every spring off the previous five years, so a
 * 2021 storm and a 2026 storm are measured against genuinely different
 * numbers. The year in the name was always there to make a stale table
 * VISIBLE; carrying two of them and choosing by the storm's own season makes
 * it RIGHT, which matters the moment anything is measured against an archived
 * hurricane. Ida is that moment.
 *
 * 2021's Atlantic table is not a rescaling of 2026's — 36 h went 55 -> 49 nm
 * and 96 h went 148 -> 134 nm, so reading Ida with 2026's numbers understates
 * NHC's own hedge by roughly a tenth at every hour that matters.
 *
 * Source: NHC's forecast verification report for the PREVIOUS season, which
 * is where each year's cone radii are published (Table 14 of
 * Verification_2020.pdf for 2021). The 2026 table is aboutcone.shtml. Both
 * are archived verbatim under samples/ida-al092021/. */
export const CONE_CIRCLE_NM_2021 = Object.freeze({
  /* NOTE THE 3-HOUR ROW. 2021 published one and 2026 does not, so the taper
   * below the first row starts from a real published circle rather than from
   * the 12-hour one. lib/cone-error.js reads table[0] rather than assuming
   * twelve, which is why this needs no special case. */
  atlantic: Object.freeze([
    [3, 16], [12, 27], [24, 40], [36, 55],
    [48, 69], [60, 86], [72, 102], [96, 148], [120, 200],
  ]),
  pacific: Object.freeze([
    [3, 16], [12, 25], [24, 37], [36, 51],
    [48, 64], [60, 77], [72, 89], [96, 114], [120, 138],
  ]),
});

export const CONE_CIRCLE_NM_2026 = Object.freeze({
  atlantic: Object.freeze([
    [12, 25], [24, 39], [36, 49], [48, 62],
    [60, 77], [72, 95], [96, 134], [120, 200],
  ]),
  pacific: Object.freeze([
    [12, 25], [24, 37], [36, 48], [48, 56],
    [60, 66], [72, 78], [96, 106], [120, 138],
  ]),
});

/** Season -> table. Add a year here and nothing else changes.
 *
 *  A SEASON WE DO NOT HOLD FALLS BACK TO THE NEWEST ONE, and that is
 *  deliberate rather than lazy: the live app only ever shows storms from the
 *  current season, so the newest table is the right answer for every storm a
 *  user will see, and returning null instead would delete the band from the
 *  screen the spring NHC is late republishing. The fallback is REPORTED —
 *  `coneSeasonUsed()` says which season actually answered — so an archived
 *  storm measured against the wrong year is a question anyone can ask rather
 *  than a thing nobody can see. */
export const CONE_CIRCLE_BY_SEASON = Object.freeze({
  2021: CONE_CIRCLE_NM_2021,
  2026: CONE_CIRCLE_NM_2026,
});

/** The newest table in the file. tools/test-home.mjs fails once the season is
 *  under way and this has not caught up — the check SPEC-HOME-PLAN said was
 *  missing. */
export const CONE_CIRCLE_SEASON_LATEST = 2026;

/** Which table a basin reads, or null for "NHC publishes none for this
 *  ocean". Keys are lib/basin.js ids — the same vocabulary the whole app
 *  uses, so a new basin cannot quietly fall into the wrong error bar. */
export const CONE_CIRCLE_BASIN = Object.freeze({
  atlantic: 'atlantic',
  eastPacific: 'pacific',
  centralPacific: 'pacific',
  westPacific: null,
  northIndian: null,
  southwestIndian: null,
  australian: null,
  southPacific: null,
});

/* ---------------------------------------------------------------------------
 * THE HOME DASHBOARD (SPEC-UI §8)
 *
 * Every behavioural number the dashboard leans on, defined before the logic
 * that reads it (§12). None of these is a data value — the data comes from
 * NHC. These are the app's own editorial thresholds, and each one is a place
 * where a different choice changes what the screen SAYS.
 * ------------------------------------------------------------------------- */
export const HOME_DASH = Object.freeze({
  /** The ring the countdown reports crossing, NAUTICAL MILES.
   *
   *  100 STATUTE MILES, EXPRESSED IN THE UNIT THE APP STORES. A round number
   *  in the unit the reader thinks in, converted once here rather than at
   *  every comparison — the convert-at-render rule runs the other way for a
   *  THRESHOLD, because comparing in nm and displaying in miles is what keeps
   *  the crossing time and the label from disagreeing by a rounding step.
   *
   *  It is an editorial choice, not a meteorological one. There is no wind
   *  threshold at 100 miles; it is simply the distance at which most people
   *  stop reading a storm as somebody else's problem. The winds-at-home
   *  windows (Phase B) are the real answer and will sit beside this, not
   *  replace it — "when does it get near" and "when do I feel it" are
   *  different questions. */
  nearRingNm: 86.9,

  /** ==> WHEN "COMING" BECOMES "ALMOST HERE". <== The lead time at or under
   *  which the chip stops saying the storm is bearing down and starts saying
   *  it is hours away, measured to the FIRST wind reaching the house rather
   *  than to the closest pass — because the wind is what arrives, and it
   *  arrives hours before the centre.
   *
   *  SIX, AND IT IS EDITORIAL. Nothing meteorological happens at six hours.
   *  It is roughly the last moment outdoor preparation is still sensible in
   *  daylight, and NHC's own warnings are framed at 36 h and 48 h, so a rung
   *  between "warned" and "here" had to be chosen rather than inherited. */
  imminentHours: 6,

  /** How much stronger the forecast peak must be than the wind at closest
   *  pass, KNOTS, before the dashboard says "still strengthening when it
   *  arrives" or "weakening as it approaches".
   *
   *  Inside this margin it says neither. NHC's own published intensity error
   *  is around 15 kt at every forecast day (it says so in the advisory text),
   *  so a 3 kt difference between two points on the same curve is not a
   *  trend anybody should act on — and a label that flips between advisories
   *  is worse than no label. */
  peakDeltaKt: 5,

  /** How far past the closest pass the dashboard keeps counting, HOURS.
   *
   *  After the storm is by, "closest pass 4 hours ago" is still the useful
   *  sentence — the wind and water arrive late and leave later. Past this it
   *  stops being the headline and the storm has to re-qualify on distance
   *  like any other. */
  afterCpaHours: 12,

  /** The classification steps the timeline reports, as CATEGORY INDICES
   *  (`lib/category.js`: 0 = TD, 1 = TS, 2 = Cat 1, 4 = Cat 3).
   *
   *  ==> THREE, NOT EVERY STEP, AND THE REASON IS THE READER NOT THE CODE. <==
   *  Emitting a row per category would give a real Cat 5 ten of them — up
   *  through five and back down — on a rail that already carries the wind
   *  arrivals, the pass and the all-clear. These three are the ones with
   *  public meaning: the phrases "tropical storm", "hurricane" and "major
   *  hurricane" are what evacuation orders and news bulletins are written in,
   *  and a reader knows what each costs them without being told.
   *
   *  NOTHING IS LOST BY STOPPING HERE, because the peak row carries the actual
   *  maximum and its own category — a storm that tops out at Cat 4 says so
   *  there, in the sentence that is about how strong it gets. */
  classMilestones: Object.freeze([1, 2, 4]),

  /** How far out the chart bothers to plot, as a MULTIPLE of the near ring.
   *
   *  BEYOND THIS THE DETAIL THAT MATTERS IS CRUSHED: a five-day track running
   *  to 400 nm squashes a 30 nm closest pass into two pixels of the frame. The
   *  countdown rail carries the full horizon; the chart carries the approach.
   *
   *  ==> IT LIVED IN `ui/chart-home.js` AS A LOCAL `WINDOW_RINGS`. <== §49.8
   *  said the new past-window number goes "beside WINDOW_RINGS" in `config/`,
   *  which is where the spec assumed it already was and where SPEC §12 says
   *  every behavioural number belongs. It is here now, with the two below it,
   *  because the three of them together decide the shape of one picture and
   *  reading them in two files is how they drift. */
  chartWindowRings: 3,

  /** How far BACK the chart plots, HOURS, when nothing else forces it wider.
   *
   *  The chart used to start at the present because there was no data behind
   *  it (§49.8). Now that the observed track reaches it, "how far back" is a
   *  real editorial choice: too little and a storm that went by an hour ago
   *  still looks like it appeared from nowhere; too much and the forecast half
   *  — the half a reader is deciding on — is squeezed into the right third of
   *  the frame.
   *
   *  ==> TWELVE, MEASURED ON GLASS, DOWN FROM TWENTY-FOUR. <== A day of
   *  history read as too much: it is two synoptic steps more than the eye
   *  needs to see where the storm came from, and every hour of it is taken out
   *  of the wind bars and the approach on the right. Twelve is two published
   *  fixes of run-up, which is enough to show a direction.
   *
   *  It is a FLOOR, not a ceiling: a pass older than this widens the window
   *  rather than falling off the left edge. */
  chartPastHours: 12,

  /** How much frame to leave to the LEFT of a closest pass that has already
   *  happened, HOURS.
   *
   *  A pass sitting exactly on the frame edge reads as the chart having been
   *  cut off mid-event rather than as the moment the whole screen is about.
   *  Six hours is one synoptic step — one published fix of run-up — so the
   *  approach into the pass is always visible, not just the pass itself. */
  chartPastPassMarginHours: 6,

  /** How close a class milestone has to be to the forecast peak, HOURS,
   *  before the peak row is folded into it rather than printed beside it.
   *
   *  A storm whose strongest forecast hour IS the hour it becomes a hurricane
   *  produced two rows at one minute saying nearly the same thing. The
   *  milestone's own detail already carries the wind, so the merge loses no
   *  figure — it only stops the rail from saying it twice. */
  peakMergeHours: 1,
});

/* ---------------------------------------------------------------------------
 * HOME MARKER (SPEC §9 — "The home marker (as-built)"; §8 is the home FEATURE
 * set, this is how it draws)
 *
 * Home floats ABOVE the node lattice, tethered to its exact surface point.
 * Three visibility states, and the state machine is the hard part:
 *
 *   ON_GLOBE  — on the near hemisphere AND inside the viewport.
 *               Marker at altitude + tether. No pointer.
 *   OVER_LIMB — on the FAR hemisphere (behind the planet). Pointer rides the
 *               limb, bobbing, at the great-circle crossing toward home.
 *   OFF_SCREEN— near hemisphere but outside the viewport (zoomed in). Pointer
 *               clamped to the viewport edge instead of the limb.
 *
 * The altitude curve is the reason this feels like floating instead of a
 * sticker. A FIXED altitude looks right from far out and drifts off the house
 * up close (parallax grows with proximity). So altitude SHRINKS with zoom:
 * high at the planet band, nearly touching down by the time you can see a
 * street. Expressed in EARTH RADII so it scales with the globe automatically —
 * "moves with the radius of the earth," per Aaron.
 *
 * Every value here is a GUESS until measured on glass. That is the whole
 * reason they live in one block.
 * ------------------------------------------------------------------------- */

export const HOME = Object.freeze({
  /** Altitude above the surface, in EARTH RADII, at the far end of the zoom
   *  ladder (whole globe in frame).
   *
   *  RAISED 0.06 → 0.16 on glass: at the planet band the 3D clear globe sits
   *  at DIVE.spaceDistance with a SMALL on-screen radius, so 0.06·R came out
   *  a few pixels and the marker was buried in the node lattice — invisible at
   *  exactly the zoom where it most needs to say "your home is over here." The
   *  altitude has to clear the lattice in SCREEN terms, and out there the
   *  screen radius is small. */
  altFar: 0.16,

  /** Altitude in earth radii once zoomed in past the ladder's near end. Not
   *  zero: a marker sitting flat ON the surface stops floating and gets lost
   *  in the lattice. Small enough that parallax can't push it off the house. */
  altNear: 0.004,

  /** The zoom band the altitude curve interpolates across. Deliberately the
   *  SAME band as the storm-dot crossfade so the two reads change together
   *  rather than at two unrelated moments. */
  altZoomFar: ZOOM.planet,
  altZoomNear: ZOOM.regional,

  /** Tether: the line from the marker down to its exact surface point. This is
   *  what makes the altitude legible — without it, "floating" is ambiguous
   *  with "offset by accident." Width in screen px, constant. */
  tetherWidthPx: 1.5,

  /** Tether fades toward the surface end rather than butting into the lattice
   *  with a hard stop. Opacity at the marker end and at the ground end. */
  tetherOpacityTop: 0.85,
  tetherOpacityBase: 0.15,

  /** DIRECTLY-OVERHEAD DEADZONE — measured in SCREEN space, not angle.
   *
   *  When the camera sits directly over home the surface normal points at the
   *  lens, its screen projection is zero, the tether direction is undefined,
   *  and sub-pixel noise spins it. Measured: 26.6° of swing per 0.1° of camera
   *  movement at 0.2° off centre. That is "wobbling all around like crazy."
   *
   *  THE FIRST FIX USED AN ANGULAR THRESHOLD AND THAT WAS WRONG. Foreshorten
   *  is sin(angle from the view axis), so a 0.05 cutoff means 2.9° of arc —
   *  but past z5 the ENTIRE VISIBLE MAP is only a degree or two wide, so every
   *  on-screen point fell inside the deadzone and the tether never drew at
   *  all. That is the regression Aaron saw as "we lost the tether."
   *
   *  These are a FRACTION OF THE GLOBE'S ON-SCREEN RADIUS instead: how far the
   *  anchor sits from the projected globe centre, in pixels, over the globe's
   *  pixel radius. Scale-free — it behaves identically at z0 and z8, because
   *  both terms grow together. The wobble only ever happens when the anchor is
   *  genuinely within a few pixels of the disc centre, which this measures
   *  directly. */
  overheadDeadzone: 0.012,
  overheadFadeBand: 0.05,

  /** MINIMUM VISIBLE TETHER LENGTH, in screen px.
   *
   *  The foreshortened normal is geometrically correct and PRODUCT-WRONG on
   *  its own. Once zoomed past the basin band, home sits within a degree or
   *  two of the view centre in almost every frame, so the true projected
   *  altitude collapses below a pixel and the tether vanishes — which is
   *  exactly the regression Aaron caught: "we lost the tether, home looks like
   *  it's sitting directly on the globe."
   *
   *  The tether is a UI AFFORDANCE, not a physics readout. Its job is to say
   *  "this mark floats above THAT point," and it has to keep saying that at
   *  street zoom. So the drawn length is max(trueProjected, this), and the
   *  overhead deadzone below only kills it in the genuinely degenerate case
   *  where there is no direction to draw at all. */
  tetherMinPx: 26,

  /** Full tether length at the far end, in screen px — the ceiling the
   *  foreshortened value is allowed to reach at the planet band. Keeps the
   *  marker clear of the node lattice without launching it into space. */
  tetherMaxPx: 64,

  /** Marker glyph size in SCREEN px — constant, like the storm glyph. A home
   *  marker is a position, not an area. Hit area is SIZE.touchTarget. */
  markerPx: 22,

  /** The surface point gets its own small anchor dot, so the tether visibly
   *  lands ON something. */
  anchorPx: 5,

  /** Anchor dot opacity when the surface point is visible. Deliberately under
   *  1: the dot is a reference mark, and at full strength it competes with the
   *  house for attention when both are on screen.
   *
   *  It drops to 0 the moment the surface point goes behind the limb. The dot
   *  asserts "home is exactly here," and once the point is occluded that is no
   *  longer true — the tether foot is clamped to the silhouette, which is a
   *  direction, not a location. */
  anchorOpacity: 0.55,

  /* --- the off-screen pointer ------------------------------------------- */

  /** Pointer assembly size in screen px — the house is scaled from this and
   *  the arrow is smaller again (see pointerParts). Slightly larger than the
   *  marker: it carries more meaning (identity AND direction) and often sits
   *  near a screen edge competing with chrome. */
  pointerPx: 28,

  /** Gap between the house's centre and the arrow's centre, along the axis
   *  pointing at home. Both marks sit on that one imaginary line: house, then
   *  arrow, then (off screen) home. Big enough that they read as two marks in
   *  a row rather than one overlapping blob. */
  pointerAxisGapPx: 21,

  /** Clearance the pointer keeps from on-screen chrome (control cluster, storm
   *  pill, status strip, open panels). A direction indicator that slides under
   *  a button is both unreadable and untappable, so it walks AROUND obstacles
   *  rather than rendering beneath them.
   *
   *  RAISED 12 → 20 on glass: at 12 px the pointer cleared the buttons
   *  technically but sat visually welded to them. This is the gap between the
   *  pointer's HIT BOX edge and the obstacle, and the glyph inside that box is
   *  smaller than the box, so the apparent gap is larger than the number —
   *  which is why it needs to be generous to read as deliberate spacing rather
   *  than a near-miss. */
  pointerChromeClearancePx: 20,

  /** Padding used when deciding whether home is HIDDEN BEHIND chrome — a
   *  separate question from where the pointer may sit, and a separate number.
   *
   *  Home sliding under the storm drawer is invisible to the user, so the
   *  pointer must appear even though home is still inside the viewport
   *  rectangle. Testing bounds alone (the first pass) left the marker
   *  officially "on screen" while it sat behind an opaque panel.
   *
   *  Smaller than the pointer clearance on purpose: this asks "can the user
   *  actually see it," so a marker a few px from a panel edge is still visible
   *  and should NOT flip to the pointer. Overshooting here would make the
   *  marker vanish while it is plainly on screen, which is worse than the bug
   *  it fixes. */
  occlusionPaddingPx: 4,

  /** Inset from the limb, in screen px, so the pointer sits just OUTSIDE the
   *  silhouette rather than half-buried in the planet's edge. */
  pointerLimbInsetPx: 14,

  /** Minimum distance from any viewport edge, in screen px. SPEC §10: nothing
   *  important within a thumb-width of an edge where the OS eats the gesture.
   *  Derived from the touch target, not hand-set. */
  pointerEdgeMarginPx: 44,

  /** The bob. Perpendicular to the limb — the pointer nudges OUTWARD along the
   *  axis it points and settles back. A vertical bob on a curved rim reads
   *  wrong at the sides. Amplitude in screen px; transform only. */
  bobAmplitudePx: 5,
  bobPeriodMs: 2600,

  /** Under prefers-reduced-motion the bob is DAMPENED, not removed. A few px
   *  of local travel on a 44 px control is not the large-area parallax that
   *  setting guards against, and the movement is what makes the pointer
   *  findable against a busy globe. */
  bobReducedScale: 0.4,

});

/* ---------------------------------------------------------------------------
 * GEOCODING (SPEC §8)
 *
 * Mapbox, proxied through /api/geocode. The token is a Pages environment
 * variable and NEVER reaches the client — a key in a static bundle is a public
 * key, and a stolen geocoding key bills until someone notices.
 *
 * Autocomplete fires per keystroke, so it is debounced and floored at a
 * minimum length. Both are cost controls as much as UX ones.
 * ------------------------------------------------------------------------- */

export const GEOCODE = Object.freeze({
  /** Wait this long after the last keystroke before asking. 250 ms is below
   *  the threshold where typing feels laggy and still collapses a fast typer's
   *  10-character burst into one request instead of ten. */
  debounceMs: 250,

  /** Don't ask at all below this. Two characters match half the planet and
   *  bill for the privilege. */
  minChars: 3,

  /** Suggestions shown. More than this and the list becomes a scroll surface
   *  competing with the globe on a phone. */
  maxResults: 5,

  /** A geocode result is a GUESS. Confidence below this shows the
   *  "drag to adjust" hint prominently rather than as a quiet affordance —
   *  a wrong home silently poisons every distance downstream (SPEC §8). */
  lowConfidence: 0.7,

  /** Zoom the camera flies to when a result is picked. Derived from the LOCAL
   *  band, never from `ZOOM.max` — the ceiling moved to 11 in 2026-07-31 for
   *  the Deep world's seamounts and address confirmation had no reason to
   *  follow it. Confirmation happens at the top of the local band, not at
   *  street zoom. This is the real constraint on address confirmation:
   *  you are checking the right neighborhood and coastline, not the right
   *  driveway. Dragging the pin is what gets you the last few hundred metres. */
  confirmZoom: ZOOM.local + 1,

  /* --- naming the point ----------------------------------------------------
   * A dropped or dragged pin has no address, and the app used to print raw
   * coordinates for it forever. These three numbers govern turning that point
   * back into words (data/geocode.js reverseGeocode, map/water-at.js).
   * ---------------------------------------------------------------------- */

  /** How long the pin must sit still before we ask what it is sitting on.
   *
   * ==> MUCH LONGER THAN `debounceMs`, AND FOR THE OPPOSITE REASON. <== The
   * typing debounce is short because a laggy search box feels broken; nobody
   * is waiting on this one, because the pin is already where they want it and
   * only the caption is outstanding. What this number actually buys is money:
   * a drag across a coastline crosses dozens of nameable places, and 600 ms
   * is comfortably longer than the pauses inside a single continuous drag, so
   * one deliberate move costs one lookup instead of fifteen. */
  reverseDebounceMs: 600,

  /** How long to wait for basemap tiles before answering "unknown" to the
   *  land-or-water question.
   *
   *  It is a CEILING ON WAITING, not a target — the check normally answers on
   *  the first frame, because the tiles under a pin the user is looking at are
   *  by definition already drawn. It only elapses on a cold flyTo over a slow
   *  connection, which is exactly the case where guessing would be worst.
   *  Three seconds is past the point where a caption is worth waiting for. */
  waterProbeMs: 3000,
});

/* ---------------------------------------------------------------------------
 * RAINFALL (SPEC §48)
 *
 * Two surfaces, two questions, and the numbers below only govern the HOME one.
 * The storm drawer shows NHC's own rainfall paragraph and extracts no figure
 * from it at all, so it has nothing to tune — §48.9 is deliberately a section
 * with no arithmetic in it.
 * ------------------------------------------------------------------------- */
export const RAIN = Object.freeze({
  /** How far ahead the home total looks.
   *
   *  ==> IT IS A CEILING, NOT A PROMISE. <== The series usually stops first —
   *  Hilo's ran to about four days while this window is five — so the sentence
   *  names the end of the LAST BLOCK IT ACTUALLY HAS, never this number
   *  (§48.11: the 120-hour window and the 72-hour window are the same total,
   *  and the label has to say Thursday rather than claim five days). */
  windowHours: 120,

  /** How far BACK the Flooding section's past-rainfall sentence looks. §56.14.
   *
   *  ==> IT IS A PLACEHOLDER AARON MOVES ON GLASS, AND THIS COMMENT IS NOT
   *  GOING TO PRETEND OTHERWISE. <== §56.14 says in as many words that 48 is
   *  the number in the proposed wording and not a measurement. Too short and
   *  the figure misses the front that soaked the ground before the storm
   *  arrived; too long and it stops being about this weather and becomes a
   *  climate statistic. Nothing in the sandbox can find the right value — it
   *  needs rain actually falling at a house somebody is looking at.
   *
   *  ==> IT IS COUNTED BACK FROM `now`, NEVER FROM THE START OF THE SERIES.
   *  <== The measured reason, and the whole design of `pastBlocks`: Open-Meteo
   *  prepends `past_days` whole UTC days and then continues into a forecast
   *  half that ALSO begins at 00:00 UTC today — so at 01:48Z roughly two hours
   *  of the "forecast" have already happened. Anchoring on where the prepended
   *  block ends would silently drop those hours from the past total and
   *  double-count nothing, which reads as a plausible smaller number. */
  pastHours: 48,

  /** Mirrors `pastHours` in the only unit Open-Meteo's API takes: whole days.
   *
   *  ==> IT IS DELIBERATELY ONE DAY MORE THAN `pastHours` ROUNDS TO. <== The
   *  series is prepended in whole UTC days, so `past_days=2` at 01:48Z reaches
   *  back only 49h 48m — barely past the window — while at 23:00Z it reaches
   *  71h. Asking for the tighter number would leave the window short for most
   *  of the UTC day and the sentence would quietly shrink. Measured on the
   *  archive runner's own capture: 72 hours became 120, exactly 48 prepended,
   *  in the SAME `hourly.precipitation` array. The extra day costs about 543
   *  bytes and buys a window that is always complete. */
  pastDays: 3,

  /** Under this, the section says so in words instead of printing a figure.
   *
   *  2.5 mm is a tenth of an inch, which is the bottom rung NWS itself uses on
   *  its point forecasts. Galveston measured 0.254 mm across thirty blocks and
   *  Key West 1.778; both are the same fact — no meaningful rain — and both
   *  render as `0.01 in` and `0.07 in` if this number does not exist, which
   *  reads as a malfunction rather than as a forecast (§48.8). */
  negligibleMm: 2.5,

  /** A single block only earns its own sentence when it carries at least this
   *  much of the total. Hilo's heaviest six hours are 30% of four days, and
   *  "most of it in six hours" is what distinguishes a flood from a wet week.
   *  Below a quarter there is no heaviest block worth naming — the rain is
   *  spread, and saying otherwise would invent an event. */
  peakShare: 0.25,

  /** How long a fetched answer is trusted on the device.
   *
   *  The GRID updates a few times a day, so this is not about the number
   *  moving. It is about ALERTS, which travel in the same payload: a flash
   *  flood warning is routinely shorter-lived than an hour (Hilo's expired 52
   *  minutes after it was issued, §48.6), so holding this answer for longer
   *  than that would mean the section can be a lie about now. Expiry is ALSO
   *  filtered at render time, which is the belt to this braces. */
  clientTtlMs: 15 * 60 * 1000,

  /** Decimal places the home coordinates are rounded to BEFORE they go on the
   *  wire (§48.7).
   *
   *  ==> THIS IS THE PRIVACY POSTURE, AND IT COSTS NOTHING. <== An NWS grid
   *  cell is about 2.5 km across; two decimals is about 1.1 km, comfortably
   *  inside one, so the coarser number resolves to the same cell and the same
   *  forecast. What it buys is that the request names a neighbourhood rather
   *  than a house, and that a cache key can be hit twice. Three decimals is
   *  what `/api/reverse` sends (SPEC-DATA §4) and it needs the extra digit;
   *  this does not. */
  wireDecimals: 2,

  /** Only these reach the screen. §48.6: hurricane and tropical storm
   *  warnings already have a home in the `In effect` section and must not be
   *  said twice, and High Surf and the local statement belong to neither
   *  section. Matched against the alert's `event` text, case-insensitively. */
  alertEventMatch: 'flood',

  /** How near a flood alert's SHAPE has to come to a storm's track, NAUTICAL
   *  MILES, for that alert to be listed under that storm. §56.3.
   *
   *  ==> THIS NUMBER HAS NOT BEEN MEASURED AND THIS COMMENT IS NOT GOING TO
   *  PRETEND OTHERWISE. <== §56.13 is explicit that nothing in the sandbox can
   *  find the right value: it depends on how far a rain shield reaches from a
   *  centre over land, and this project has never had a US landfall on glass.
   *  300 is a STARTING VALUE, chosen by Aaron on 2026-08-22, for him to move
   *  once one happens. Anything written here that reads as a derivation would
   *  be the fluent wrong number CLAUDE.md is about.
   *
   *  ==> IT IS THE ONLY RING LEFT, AND THAT IS THE HONEST THING TO SAY ABOUT
   *  THE CHOICE. <== §56.9 folded the home gate onto this same test on
   *  2026-08-22, and deleted the two constants that used to answer nearby
   *  questions in nearby places: `RAIN.houseFallbackNm` (300 nm, the wind-field
   *  fallback under the storm drawer's house block) and a borrowed
   *  `APPROACH.relevanceNm` (1,500 nm, which decided whether flood warnings
   *  appeared under a storm). Three distances all meaning some version of
   *  "near this storm" is three numbers that drift; this is now the one.
   *
   *  ==> IT IS FLAT, AND DELIBERATELY NOT SCALED OFF THE WIND FIELD. <==
   *  §56.3. The tempting move is to reuse the storm's own 34 kt radii the way
   *  `data/home-corridor.js` does for wind at the house. Do not. Flooding is
   *  driven by the rain shield, not the wind field, and a weakening storm
   *  inland has an enormous rain footprint and almost no wind field — which is
   *  precisely the case that floods people. Scaling by wind radii would shrink
   *  the search area exactly where the hazard is worst. */
  floodCorridorNm: 300,

  /** How far apart the points on a THINNED outline may sit, in nautical miles,
   *  during the corridor match's first pass (§56.18).
   *
   *  ==> IT IS AN ERROR BUDGET, NOT A SIMPLIFICATION. <== A thinned outline can
   *  only ever report a shape as FURTHER from the track than it really is —
   *  the nearest point may have been one of the ones dropped. That error is
   *  bounded by this number, and it runs in the one direction §56.3 allows:
   *  toward keeping an alert that is just outside, never toward dropping one
   *  that is just inside. `lib/flood.js` closes the gap by measuring the FULL
   *  outline whenever a shape lands within this distance of the corridor edge,
   *  so the include/exclude decision is exact at every radius and only the
   *  reported distance moves.
   *
   *  ==> ONE NAUTICAL MILE, AND THE MEASUREMENTS ARE IN §56.18. <== NWS zone
   *  boundaries carry points 65 METRES apart — a Hawaii coastal zone is 1,970
   *  of them — against a corridor 300 nautical miles wide. At one mile that
   *  zone thins to 112 points and the worst distance error across 1,400
   *  boundary decisions was 0.34 nm, which is below anything a row prints.
   *  Tighter costs time for accuracy no reader can see; looser starts moving
   *  a printed figure. */
  floodCoarseTolNm: 1,

  /** Decimal places kept on a zone boundary's coordinates as it crosses the
   *  wire (§56.4).
   *
   *  ==> FOUR PLACES IS ELEVEN METRES AND NWS PUBLISHES SIX. <== Measured on
   *  the 23 captured boundaries: as served they are 362 KB of compact
   *  coordinates; rounded to four places, 301 KB — 17% for a shift no reader
   *  can see and no test here can measure. The corridor these shapes are
   *  tested against is 300 NAUTICAL MILES wide.
   *
   *  ==> IT IS A ROUNDING AND NOT A SIMPLIFICATION, AND THE DIFFERENCE
   *  MATTERS. <== Every vertex NWS drew still travels. Nothing is dropped, no
   *  ring changes shape, and the boundary is still theirs — which is the whole
   *  reason §56.4 permits fetching it at all. `lib/simplify.js` is a separate
   *  question for the map, and it belongs on the client where the zoom is
   *  known. */
  zoneWireDecimals: 4,

  /** How many zones one call to `/api/nws/zone` may ask for.
   *
   *  ==> A CAP, NOT A BUDGET, AND IT PROTECTS SOMEBODY ELSE'S SERVER. <== Each
   *  id is one upstream request on a cold miss. Uncapped, a caller can turn one
   *  request to us into hundreds at api.weather.gov. Forty is the same ceiling
   *  `tools/archive-fetch.mjs` puts on the hourly capture, chosen there so a
   *  national flood day cannot become a hundred requests at one agency, and one
   *  number for both is one number to move. The three watches in force on
   *  2026-08-23 named 23 zones between them. */
  zonesPerRequest: 40,
});

/* ---------------------------------------------------------------------------
 * FLOOD ON THE MAP — how the alert chips behave (SPEC §56.5, Slice B)
 *
 * ==> BEHAVIOURAL THRESHOLDS LIVE HERE AND PIXEL GEOMETRY LIVES IN tokens.js,
 * THE SAME SPLIT `GENESIS` / `GENESIS_GEO` MAKES. <== When two markers are
 * close enough to be one thing is a rule about behaviour; how big the chip is
 * drawn is a rule about what it looks like.
 *
 * ==> THE POLYGON ZOOM GATE IS NOT HERE, AND THAT IS DELIBERATE. <== It shipped
 * in Slice A as `ZOOM.floodFadeIn` / `ZOOM.floodFull`, and Slice A has not been
 * judged on glass yet. Moving those two numbers into this block would mean
 * touching the thing under test in the same push that adds the chips — which is
 * exactly what makes a slice unbisectable, and unbisectable is what cost this
 * phase two sessions (§56.15).
 *
 * ==> NOT ONE VALUE BELOW HAS BEEN SEEN. <== §56.13: nothing about this feature
 * can be judged until a US storm is near a flooding region. Each is derived
 * from an OFFLINE measurement — pixels on a screen, counts in a capture — which
 * is a real basis and is not the same thing as having looked at it.
 * ------------------------------------------------------------------------- */

export const FLOOD = Object.freeze({
  /** How near two chips have to be, IN PIXELS, before MapLibre merges them.
   *
   *  ==> THIS IS THE NUMBER THAT REPLACES COLLISION, AND §56.2 IS WHY THERE
   *  HAD TO BE ONE. <== Measured in chromium on a 390x700 phone with
   *  `icon-allow-overlap: false`: MapLibre's own collision drew 7 icons for 25
   *  alerts at z3, and — the finding that decided this — 11 for 14 sitting
   *  right on top of the pile at z7. It DOES NOT resolve by zooming in. Three
   *  warnings with no marker and nothing on screen saying so is §5's silence
   *  with a map over it.
   *
   *  Clustering answers it because nothing is ever dropped: two alerts that
   *  cannot both be drawn become one chip reading "2". 44 is the touch target
   *  (§10) — chips closer together than a fingertip cannot be tapped apart, so
   *  merging them is not a loss of information, it is an accurate statement
   *  about what this screen can resolve. */
  clusterRadiusPx: 44,

  /** Past this zoom nothing clusters — every alert is its own chip.
   *
   *  §56.2's polygons are 0.060 to 0.440 degrees wide. At z9 the smallest is
   *  over 40 px, so two distinct alerts are visibly two places and a merged
   *  chip would be hiding a distinction the reader can already see. This is
   *  also two zoom levels past `ZOOM.floodFull`, so by here the chip is
   *  decoration over a solid shape rather than the only marker. */
  clusterMaxZoom: 9,

  /** How many interior points may be held before the cache is emptied whole.
   *
   *  ==> THE CACHE IS WHAT MAKES THE CHIPS AFFORDABLE, AND THIS IS THE ONLY
   *  THING STOPPING IT GROWING FOR A WHOLE SESSION. <== One entry is an id
   *  string and two numbers. The measured national capture is 36 alerts; a busy
   *  national flood day is low hundreds, and the alert list turns over every
   *  `RAIN.floodClient` (3 minutes), so a long session accumulates ids for
   *  alerts that expired hours ago and will never be asked for again.
   *
   *  Well above any real day on purpose: hitting this ceiling costs one full
   *  recompute on the next push, which is the cost this cache exists to avoid,
   *  so it should fire approximately never. See `trimPointCache` in
   *  `lib/flood-features.js` for why it clears wholesale instead of evicting. */
  pointCacheMax: 600,

  /** How far either side of a tap the chip layer is queried, IN PIXELS (§56.6).
   *
   *  ==> DELIBERATELY NOT §10's 44, AND THE 44 IS ALREADY SPENT ELSEWHERE. <==
   *  `clusterRadiusPx` above is 44 precisely because chips closer together than
   *  a fingertip cannot be tapped apart, so the SOURCE has already merged them:
   *  by the time two chips are both on screen they are two distinct places a
   *  reader can see and aim at. Querying a 44 px box here would put both inside
   *  it and let the winner be whichever MapLibre happened to list first — an
   *  arbitrary answer to a deliberate tap, which is worse than a miss because
   *  it opens the wrong panel silently.
   *
   *  A bare point would be the other error: the chip is 24 px, and a tap on its
   *  very edge is a real gesture that a zero-width query misses by a pixel.
   *  8 covers the edge without reaching the neighbour. `map/layers/genesis.js`
   *  reasons its way to the same number from the opposite direction — its
   *  patches are hundreds of miles across and it pads to catch the rim. */
  chipHitPadPx: 8,

  /** Where the camera lands when the detail panel's `Show on the globe` is
   *  pressed (§56.6).
   *
   *  ==> TIGHTER THAN `GENESIS.flyToZoom` AND WIDER THAN `GLOBE.flyToZoom`,
   *  BECAUSE A FLOOD ALERT IS BETWEEN THE TWO THINGS THOSE FRAME. <== A storm
   *  is a point and 5 frames it. A development region is 8–22° across and 3.2
   *  frames it with its coastline. §56.2 measured these polygons at 0.060 to
   *  0.440 degrees — a county, not a region and not a point. 7 puts a
   *  county-scale shape across most of the screen with enough coast and enough
   *  place names around it to answer "is this near me", which is the only
   *  question somebody presses this button to ask.
   *
   *  Two levels past `ZOOM.floodFull`, so the polygon is at full opacity when
   *  the camera arrives rather than still ramping in. */
  showOnMapZoom: 7,
});

/* ---------------------------------------------------------------------------
 * ENDED STORMS — the graceful death (SPEC §5)
 *
 * ==> NOT A TIMER. READ THIS BEFORE ADDING ONE. <==
 *
 * A storm ends one of two ways, and NEITHER of them is "it has been a while".
 *
 *   DECLARED   the agency published its final bulletin and said so in words.
 *              NHC's last public advisory carries "...THIS IS THE FINAL NHC
 *              ADVISORY..." in its headline and "This is the last public
 *              advisory issued by the National Hurricane Center on this
 *              system." under NEXT ADVISORY. JTWC's carries "THIS IS THE FINAL
 *              WARNING ON THIS SYSTEM BY THE JOINT TYPHOON WRNCEN PEARL HARBOR
 *              HI." Both CONFIRMED verbatim off live products 2026-07-28
 *              (Post-Tropical Imelda AL092025 #24; Typhoon 26W Mangkhut NR
 *              039). This is a fact the source states, so the app can state it
 *              too, immediately, with no waiting and no inference.
 *
 *   ABSENT     nobody said anything, the storm is simply gone from a list that
 *              is otherwise answering normally — its own source's, or JTWC's
 *              active roster. Counted in CLEAN CONFIRMATIONS, never in elapsed
 *              time — see below.
 *
 * WHY COUNTED AND NOT TIMED. A clock cannot tell a dead storm from a dead
 * network: leave one running and a tunnel, a captive-portal wifi, a relay
 * deploy or one truncated upstream list all read as a storm ending. A
 * CONFIRMATION is a poll that came back clean and did not contain the storm —
 * it is evidence, where elapsed time is only the absence of evidence. A failed
 * poll produces no confirmation at all rather than a negative one, so an hour
 * of dead connectivity moves this counter by zero. Any reappearance resets it
 * to zero.
 *
 * THE ONE FAILURE MODE THIS IS VULNERABLE TO, AND ITS GUARD. A TRUNCATED list
 * is a clean fetch that is missing storms — it looks exactly like the end of
 * the world for whatever fell off the bottom. That is not hypothetical: on
 * 2026-07-26 a wildfire season crowded a live typhoon off GDACS's 100-feature
 * cap (functions/api/gdacs/events.js). So a poll only gets to vote if the list
 * it came back with is CREDIBLE — non-empty, and not less than half of what
 * the previous poll held. A suspicious list is treated like a failure: no
 * votes, in either direction.
 *
 * ==> AND GDACS DOES NOT RETIRE STORMS, WHICH BREAKS BOTH ROUTES AT ONCE. <==
 * It left `iscurrent: "true"` on Bertha for ~58 hours and kept NOUL-26 listed
 * for days after her last analysis. Such a storm is never ABSENT, because it
 * never leaves the list. It is never DECLARED either: the only bulletin that
 * exists for those basins is JTWC's, and JTWC drops a storm from its active
 * list shortly after the final warning, so missing that window — one afternoon
 * with the app closed — used to make the storm immortal.
 *
 * SO JTWC'S ROSTER IS A SECOND AUTHORITY, counted exactly like the first.
 * Falling off JTWC's active list is the same shape of evidence as falling out
 * of a source's list: a feed that answers cleanly and no longer carries the
 * storm. Same confirmation count, same truncation guard, same words. Two guards
 * keep it honest — only a storm JTWC has ACTUALLY LISTED can be killed by
 * falling off the list (GDACS covers systems JTWC never warns on), and an
 * unavailable or partial index attaches no verdict at all, so a JTWC outage
 * moves the tally by zero in either direction. data/lifecycle.js step 4.
 *
 * THE GRACE PERIOD IS THE ONLY DURATION HERE, and it is a DISPLAY duration —
 * how long a dead storm stays on the globe explaining itself before it leaves.
 * There is no data signal for that; there is nothing to measure.
 *
 * ==> IT IS MEASURED FROM THE MOMENT THE APP CONFIRMED THE ENDING. <== This
 * paragraph said the opposite — "from the storm's last published fix" — for
 * three days after the code stopped doing that on 2026-08-08, which is exactly
 * the kind of stale sentence that costs the next session an afternoon. The
 * anchor is `ended.confirmedAt`; `endedExpired` in lib/lifecycle.js carries the
 * whole argument, and the short version is that anchoring on the last fix does
 * not shorten the grey window, it deletes it for every ending that is not read
 * the moment it happens.
 *
 * ==> AND `confirmedAt` IS WRITTEN EXACTLY ONCE. <== That is not a detail, it
 * is the thing that makes an anchor on it safe at all: `promote` refuses to
 * re-end a storm already in the registry. Without that refusal the `lapsed`
 * route restamps the anchor on every poll — because the storm is still in its
 * source's list, which is the whole reason that route exists — and no window
 * measured from it can ever elapse. DOLPHIN-26 sat in Finished for two days on
 * that bug (Aaron, on glass, 2026-08-12).
 *
 * This replaces GHOST_TTL, which was 12 h and was never read by anything.
 * ------------------------------------------------------------------------- */

/* Named here rather than inline because `stopListingAfter` below is their SUM
 * and the three must never be edited into disagreement. */
const LAPSED_AFTER = 48 * HOUR;
const HOLD_FOR_LAPSED = 12 * HOUR;

export const ENDED = Object.freeze({
  /** Silence alone, past this age, ends a storm — the third `reason`,
   *  `lapsed`, alongside `declared` and `absent`.
   *
   *  ==> WHY A THIRD ROUTE EXISTS AT ALL. <== The other two both require
   *  somebody to act. `declared` needs a final bulletin, and for GDACS basins
   *  the only bulletin in existence is JTWC's. `absent` needs the storm to fall
   *  out of a list — and GDACS does not retire storms: it held `iscurrent:
   *  "true"` on Bertha for ~58 h after NHC had fully retired her, and on
   *  KUJIRA-26 it is still true two days after the last analysis. A storm in
   *  that condition can never be confirmed absent because it never goes absent,
   *  and never confirmed declared because nobody writes bulletins for it. Both
   *  death routes are structurally unreachable and the storm is immortal.
   *
   *  48 h — twice SILENCE.after, and the doubling is the argument. 24 h is
   *  already spoken for: it is the badge, the point at which the app stops
   *  drawing the forecast and says so. Reusing it here would collapse the two
   *  states into one instant, and a storm would go from live to gone with no
   *  interval in which the app has said "we have stopped hearing about this" —
   *  which is the entire purpose of the silent state. GDACS was mid-landfall on
   *  Noul when it froze; that hedge has to have a life.
   *
   *  Two full days is four missed cycles at GDACS's slowest 12 h cadence, and
   *  it catches the Bertha class of zombie within a day of it going wrong.
   *  72 h was considered and dropped for having no evidence behind it. */
  lapsedAfter: LAPSED_AFTER,

  /** How long an ended storm keeps its dot, its past track and its note before
   *  it is dropped for good. A DISPLAY duration, not a detection one — nothing
   *  about the storm changes when this expires, it just stops being drawn.
   *
   *  ==> MEASURED FROM WHEN THE APP CONFIRMED THE ENDING, not from the storm's
   *  last published fix. REVERSED 2026-08-08. <== That is `ended.confirmedAt`,
   *  and lib/lifecycle.js `endedExpired` is where it is read, with the full
   *  reasoning. In short: anchored on `observedAt` this window was already
   *  spent before it opened for every ending that is not read promptly — the
   *  JTWC roster route, `lapsed`, and any absence confirmed overnight — so
   *  those storms vanished on the same poll that ended them instead of showing
   *  a grey day. The unbounded-fresh-window problem that anchoring was
   *  protecting against is now answered by `lapsedAfter` instead.
   *
   *  24 h at Aaron's call, down from 36 on 2026-07-29. Long enough that opening
   *  the app the next morning still shows what happened to the storm you went to
   *  bed watching; short enough that the globe does not carry a season of grey
   *  dots. Nothing about the number is derived — there is no data signal for how
   *  long a dead storm is worth looking at, and pretending to measure one would
   *  be worse than choosing. */
  holdFor: 24 * HOUR,

  /** The same window for a `lapsed` ending, which is SHORTER, and the
   *  difference is how much of this news the reader has already had.
   *
   *  ==> A LAPSED STORM HAS ALREADY BEEN SAYING SOMETHING FOR TWO DAYS. <==
   *  `declared` and `absent` both arrive as news: the storm was live on the
   *  previous poll and is finished on this one, so the grey day is the first
   *  and only chance to see what happened to it. `lapsed` is the opposite —
   *  the storm went silent at 24 h (`SILENCE.after`) and wore the "not
   *  updating" badge for a further 24 before this route fires at 48. A full
   *  extra day of grey after that is a third day of the same fact, and it is
   *  what put DOLPHIN-26 in the Finished group on Tuesday afternoon carrying
   *  "ended Sun 7:00 AM" (Aaron, on glass, 2026-08-11).
   *
   *  12 h, so a storm that lapses in the morning is gone by bedtime and one
   *  that lapses overnight is still there at breakfast. Deliberately not zero:
   *  the storm must never vanish on the same poll that ends it, which is the
   *  disappearing-storm failure the whole hold exists to prevent. */
  holdForLapsed: HOLD_FOR_LAPSED,

  /** Past this age, a storm is dropped from its source's list AT PARSE and
   *  never enters the app at all.
   *
   *  ==> WITHOUT THIS THE STORM BOUNCES, AND THE BOUNCE IS WORSE THAN THE
   *  ZOMBIE IT REPLACES. <== Every other death route ends with the storm gone
   *  from a feed, so once its grey window expires there is nothing left to put
   *  it back. `lapsed` is the opposite by construction: GDACS does not retire
   *  storms, so the moment the registry drops the record, the very same storm
   *  is sitting in the very same list looking alive, and it goes straight back
   *  into the LIVE section wearing a "not updating" badge — a storm the app
   *  had just finished saying it had stopped tracking. The next poll lapses it
   *  again, twelve hours later it expires again, and it flips between Finished
   *  and live forever. Measured, on DOLPHIN-26's real timings, before this
   *  existed.
   *
   *  So the app has to stop believing the list, not just stop believing the
   *  record. `lapsedAfter + holdForLapsed` and NOT a number of its own: the
   *  moment the last grey pixel leaves the screen is the moment the feed's
   *  claim stops counting, and any daylight between those two IS the bounce.
   *
   *  IT IS NOT AN ALL-CLEAR AND IT DOES NOT HIDE A LIVE STORM. Sixty hours
   *  with no published analysis is four to ten missed cycles at GDACS's own
   *  cadence; the reader has already had the "not updating" badge since hour
   *  24 and the "quiet since" row since hour 48. And it is self-healing in the
   *  one direction that matters — a single fresh fix puts the storm back on
   *  the next poll with no state to unwind, because there is no state. */
  stopListingAfter: LAPSED_AFTER + HOLD_FOR_LAPSED,

  /** Clean, credible polls with the storm absent before absence is believed.
   *  Three, because one is a truncation and two is a bad afternoon. At the
   *  30-minute poll this lands around 90 minutes for someone watching, but the
   *  COUNT is the rule and the clock is a side effect — a phone that polls
   *  twice all day takes all day, and that is correct. */
  absentConfirmations: 3,

  /** A poll whose list is smaller than this fraction of the previous one is
   *  not credible enough to vote (see the truncation guard above). 0.5 is
   *  deliberately loose: two of three storms dissipating in one cycle is
   *  real and should still count, while a cap-truncated list that drops most
   *  of the world should not. */
  minCredibleFraction: 0.5,

  /** Ended storms kept in the registry at once, newest first. A cap so a long
   *  season cannot grow localStorage without bound; well above the number
   *  that can be inside a 24 h window. */
  maxRegistry: 12,

  /** How old a LAST-KNOWN-LIVE record may be and still be believed on load.
   *
   *  ==> WITHOUT THIS, A PHONE THAT WAS CLOSED FOR A WEEK ENDS OLD STORMS
   *  TODAY. <== The persisted store holds two maps. `ended` is swept on the
   *  way in against `holdFor`, and always was. `seen` — the working set of
   *  storms believed still alive — was not swept at all, so a stale record
   *  loaded intact, failed to appear in the next few polls, and was confirmed
   *  absent and stamped with TODAY's date. The app then drew a storm that died
   *  a week ago as one that had just ended, which is the §5 lie about time
   *  rather than about availability. Found 2026-08-10, via Hurricane Ida
   *  arriving on the live globe from a `?replay=ida` session.
   *
   *  48 h, the same number as `lapsedAfter`, and for the same reason: past
   *  that point silence alone already ends a storm, so a record older than it
   *  could not have survived had the app been open. Dropping rather than
   *  ending is the honest verdict — the storm's display window is long spent,
   *  and "we have no idea" is not the same claim as "it ended just now".
   *
   *  Costs nothing when wrong: a storm that is still real is put straight back
   *  by the very next poll, with fresh data. */
  seenMaxAge: 48 * HOUR,

  /** Past-track points persisted per ended storm. The track is what makes an
   *  ended storm worth looking at, and it has to survive a reload because the
   *  in-memory geometry cache does not.
   *
   *  ==> THIS USED TO SAY NOTHING COULD EVER REBUILD IT. THAT WAS TRUE OF
   *  `declared` AND `absent` AND NEVER OF `lapsed`. <== A lapsed storm is one
   *  its source is STILL LISTING and has merely stopped analysing, so its
   *  geometry is still published and still fetchable — see
   *  `trackBackfillAttempts` and data/ended-track.js. The old sentence is what
   *  made a device that arrived late look unfixable.
   *
   *  Capped because a five-day storm at 6-hourly fixes is ~20 points and
   *  anything claiming hundreds is a parser bug, not a long storm. */
  maxTrackPoints: 64,

  /** How many times ONE device will go and fetch a lapsed storm's missing
   *  past track before giving up for the session.
   *
   *  ==> WHY A BACKFILL EXISTS AT ALL. <== The track is captured from whatever
   *  geometry this device happened to hold when the storm was promoted. A
   *  device that first meets a storm ALREADY past `lapsedAfter` ends it on its
   *  very first poll — before the geometry warm can possibly have landed — and
   *  files a record with an EMPTY track. Measured 2026-08-12 in a real browser
   *  with clean storage: one poll, one storm silent 49 h, `pastTrack: none`,
   *  zero points persisted. Aaron saw it as a finished storm with no dotted
   *  trail on a machine that had never had the app open while it was alive,
   *  while his phone — which had — drew it correctly. The trail was never a
   *  property of the storm; it was a souvenir of who was watching.
   *
   *  THREE ATTEMPTS, NOT ONE AND NOT FOREVER. One is a single bad moment on a
   *  train. Unlimited is a device that pulls 400 kB every thirty minutes for a
   *  storm GDACS retired hours ago and will 404 on every time. Three spans an
   *  hour and a half of polling, then the storm keeps its blank trail for the
   *  rest of its 24 h window rather than costing anything more.
   *
   *  Session-scoped on purpose: the counter is not persisted, so a reload is a
   *  clean slate. A storm whose backfill failed because the phone was in a
   *  tunnel gets another honest go next time the app opens, and a storm whose
   *  event is genuinely gone costs three requests per session at most. */
  trackBackfillAttempts: 3,
});

/* ---------------------------------------------------------------------------
 * DATA ENDPOINTS
 *
 * ===> AS OF §17 PASS B, THE BROWSER FETCHES NO UPSTREAM DIRECTLY. <===
 * Every URL below is reached by a Pages Function; nothing here is passed to
 * `fetch()` from the app. They are recorded because a URL nobody wrote down
 * costs a round trip to rediscover, and because the Functions that DO fetch
 * them cannot import this file (§3, separate runtime) and mirror these values
 * by hand.
 *
 * THE OLD SPLIT WAS "CORS-BLOCKED VS CORS-OK", AND IT WAS THE WRONG QUESTION.
 * CORS-open endpoints were fetched straight from the browser for the app's
 * whole life on the grounds that they worked — which they did, at one user.
 * A shared link during a landfall makes the same code thousands of
 * uncacheable requests per poll from thousands of client IPs, aimed at
 * public-good services, under nobody's control. **CORS-open is a permission,
 * not a capacity plan.** The reason to relay a feed is whichever arrives
 * first: the browser can't reach it, or we can't responsibly point a crowd at
 * it. The CORS ground truth below is still true and still verified
 * in-browser 2026-07-22 — it is just no longer what decides.
 * ------------------------------------------------------------------------- */

export const ENDPOINT = Object.freeze({
  /** CORS-BLOCKED. Relayed because the browser cannot reach them at all. */
  nhcStormList: 'https://www.nhc.noaa.gov/CurrentStorms.json',
  nhcAdeck: 'https://ftp.nhc.noaa.gov/atcf/aid_public/',

  /** CORS-OK, relayed anyway since §17 Pass B — for load, not for access.
   *  Reached via `/api/nhc/mapserver` and `/api/gdacs/events`. */
  nhcMapServer:
    'https://mapservices.weather.noaa.gov/tropical/rest/services/tropical/NHC_tropical_weather/MapServer',
  /** CYCLONES ONLY, and the `alertlevel` triple is not a filter — it is how
   *  you ask this endpoint for the unabridged list (100 rows instead of 20).
   *  `EVENTS4APP` was used until 2026-07-26, when a wildfire season crowded a
   *  live typhoon off its 100-feature cap. The full reasoning, and why the
   *  archive this list carries has to be filtered at ingest, lives in
   *  `functions/api/gdacs/events.js`. */
  gdacsEventList:
    'https://www.gdacs.org/gdacsapi/api/Events/geteventlist/SEARCH' +
    '?eventlist=TC&alertlevel=Green;Orange;Red',

  /** CAP alerts from national weather agencies worldwide, via Esri's CAP
   *  Connector over the WMO Alert Hub (§50). CORS-OK, relayed for load and to
   *  keep one long query string in one place.
   *
   *  ==> THE FULL QUERY LIVES IN THE RELAY, NOT HERE. <== It carries a `where`
   *  clause, a field list and a `returnGeometry=false` that are load-bearing
   *  for §50.2 — asking for the shapes turned 8 KB into 281 KB, measured — and
   *  splitting a query between a constant and a route is how half of it gets
   *  changed. This records the service so the URL is written down. */
  capAlerts:
    'https://services9.arcgis.com/RHVPKKiFTONKtxq3/ArcGIS/rest/services/CAP_Alerts_Feed/FeatureServer/0/query',

  /** GDACS per-event geometry. CONFIRMED LIVE 2026-07-24 — and note this is
   *  the FALLBACK form only: every event in the list feed publishes its own
   *  `url.geometry`, which data/gdacs-geometry.js prefers. Recorded here so
   *  the shape is written down somewhere (the 2026-07-23 probe measured this
   *  endpoint's timing but never recorded its URL, which cost a round trip). */
  gdacsGeometry: 'https://www.gdacs.org/gdacsapi/api/polygons/getgeometry',

  /** ==> THE ONLY SOURCE IN THIS APP THAT IS ABOUT A PLACE RATHER THAN A
   *  STORM. <== §48.3. `/points/{lat},{lon}` resolves a coordinate to a
   *  forecast office and grid cell and hands back the URL of the raw numeric
   *  grid; that grid's `quantitativePrecipitation` is the rainfall series.
   *  TWO HOPS, which is why the relay does both of them (§48.7) — a phone
   *  paying two round trips to read 1.2 KB is the thing that route exists to
   *  stop.
   *
   *  COVERAGE IS THE UNITED STATES AND ITS TERRITORIES, and that includes
   *  Hawaii, Puerto Rico and Guam — measured, not assumed (§48.3). Outside it
   *  the answer is a 404 with `problems/InvalidPoint`, which is an ANSWER
   *  about the place and not a failure of ours.
   *
   *  NWS REQUIRES A `User-Agent` NAMING A CONTACT and answers 403 without
   *  one. The relay sets it; nothing here does. */
  nwsPoints: 'https://api.weather.gov/points',

  /** What is in force at a point, as structured GeoJSON (§48.6). Same host,
   *  same relay, same User-Agent rule. Its way of saying "outside coverage" is
   *  a 400 with `problems/InvalidParameter` — a DIFFERENT status for the SAME
   *  fact the points route reports as 404, which is why §48.5 matches on the
   *  `problems/` URI rather than on the status code. */
  nwsAlerts: 'https://api.weather.gov/alerts/active',

  /** ==> RAINFALL WHERE NWS DOES NOT REACH, WHICH IS MOST OF THE WORLD.
   *  <== §48.14. Keyless, global, and CORS-OPEN — measured 2026-08-19 from
   *  our own production origin, `access-control-allow-origin: *`. So the
   *  browser COULD call this itself; it does not, and §48.15 records the three
   *  reasons (a shared cache against an unmeasurable quota, the house
   *  coordinate staying behind our origin, and one CSP instead of two).
   *
   *  ==> THE QUOTA IS REAL AND INVISIBLE. <== The free tier states a daily
   *  ceiling on a documentation page and the response carries NO
   *  `x-ratelimit-*` header of any kind — checked on both archived probes.
   *  There is nothing to measure at runtime, which is the whole argument for
   *  putting a cache in front of it.
   *
   *  ==> AND THE LICENCE IS A CONSTRAINT ON SHIPPING, NOT ON READING. <==
   *  CC BY 4.0 requires visible attribution — `ui/rain-home.js` renders it —
   *  and the free tier is non-commercial, which this app is. */
  openMeteoForecast: 'https://api.open-meteo.com/v1/forecast',

  /** One GDACS event's full record, including the `impacts` block that carries
   *  the storm-surge locations export (§51.1). Note this is NOT the surge
   *  index: `cyclonesurge` on the same record lists per-model, per-bulletin
   *  cards whose `getdetails` payloads arrive with `geometry: null` and no
   *  places in them at all. The product with the towns in it hangs off
   *  `impacts`, which is why the relay makes this hop first. */
  gdacsEventData: 'https://www.gdacs.org/gdacsapi/api/events/geteventdata',

  /** JTWC's Significant Tropical Weather Advisory — plain text, no auth (§45).
   *  The only genesis product found outside NHC that carries a probability.
   *  RSMC Nadi, Meteo-France La Reunion and IMD publish narrative bulletins
   *  with no structured formation odds at all, so there is nothing better to
   *  reach for and this is not a placeholder for something better. */
  jtwcAbpw: 'https://www.metoc.navy.mil/jtwc/products/abpwweb.txt',

  /** Relay base. One Cloudflare Pages Function, forward-and-cache only.
   *  The app merges NHC and GDACS CLIENT-SIDE — the relay stays dumb.
   *
   *  ==> A GETTER, AND ONLY FOR THE REPLAY. <== `/replay/boot.js` points this
   *  at an archive relay before the app starts, and MOVES it every time the
   *  replay clock moves, which is why it cannot be a value read once at module
   *  load. Nothing else may write it: the seam exists so a replay can drive the
   *  real data path — the real timeouts, the real parse, the real merge —
   *  rather than have a second one written beside it that drifts.
   *
   *  In the shipping app the global is never set and this is `/api`, exactly
   *  as it was when it was a constant. */
  get relay() {
    return globalThis.__LANDFALL_RELAY_BASE__ || '/api';
  },
});

/** NHC MapServer facts that are not layer ids.
 *
 *  THE LAYER IDS ARE NOT HERE ANY MORE. They live in `SUMMARY_LAYER`
 *  (data/nhc-mapserver.js) as nine fixed numbers, because the app reads
 *  `NHC_tropical_weather_summary` — one flat set of products keyed by
 *  `binnumber` — instead of the per-storm block service it used to address by
 *  arithmetic. The block math, the 26-layer stride, the AT/EP/CP block starts,
 *  the cached service metadata and the layer-NAME patterns that resolved
 *  inside a block are all gone. Read that file's header before bringing any
 *  of it back; it was deleted for a measured reason, not for tidiness. */
export const MAPSERVER = Object.freeze({
  /** ArcGIS uses 9999 as a missing-value sentinel on geometry properties
   *  (CONFIRMED live 2026-07-23 on mslp/tcdir/tcspd beyond tau=0). It is
   *  finite, survives isFinite, and renders as "Pressure 9999 mb" unless
   *  scrubbed to null in the geometry parser. */
  nullSentinel: 9999,

  /** Peak Storm Surge is its OWN MapServer with NO stormid field — filter
   *  spatially by an envelope around the storm's position. Every tunable for
   *  it lives in `SURGE` below; these two are the service's identity. */
  surgeService: 'NHC_PeakStormSurge',
  surgePolygonLayer: 2,
});

/* ---------------------------------------------------------------------------
 * PEAK STORM SURGE (SPEC-DATA.md §4.8)
 *
 * ==> WHAT IS VERIFIED AND WHAT IS NOT. READ THIS BEFORE TRUSTING A NUMBER
 *     BELOW. <==
 *
 * VERIFIED, against bytes: the archived product. Every field name and every
 * color here was read out of `samples/milton-al142024/surge/` — Hurricane
 * Milton's 22 published advisories, blue through purple, 460 surge features.
 *
 * ALSO VERIFIED, against the LIVE service directory, 2026-08-19, with no storm
 * active: the polygon layer really does carry `name`, `folderpath`, `snippet`
 * and `popupinfo`; `symbolid` really is an integer there too; and the renderer
 * really does publish these five color words with these five labels. The
 * FEATURES only exist during a surge watch, but the DIRECTORY answers all year
 * — see SPEC-DATA.md §4.8, which used to claim otherwise.
 *
 * STILL NOT VERIFIED: WHICH of those fields carries the color word.
 * `liveColorFields` is an ordered list of candidates, not a fact — the
 * renderer names its own field, that name lives only in the JSON view, and
 * SPEC-OPS.md §18.2 records why a session cannot reach it. `data/surge.js`
 * reports which one actually answered the first time a real storm arrives.
 *
 * ==> AND §4.8 WAS WRONG ABOUT THE ONE FIELD EVERYTHING KEYS ON. <== It said
 * `symbolid` carries the color class. The service declares `symbolid` as
 * esriFieldTypeInteger. The HA project's card searched that integer for the
 * substring "blue", never matched, and silently fell through to coloring
 * bands by ARRIVAL ORDER — no error, plausible output, wrong severity. Do not
 * reintroduce a color lookup that reads `symbolid`.
 * ------------------------------------------------------------------------- */

export const SURGE = Object.freeze({
  /** Degrees either side of the storm's position for the spatial filter. The
   *  service has no `stormid`, so this envelope IS the per-storm filter, and
   *  it is why surge caches on POSITION rather than on storm identity. */
  envelopeDeg: 12.0,

  /** Asked of ArcGIS as `maxAllowableOffset`, so the bytes are generalized
   *  before they are ever sent. THE FIXTURE IS BUILT AT THIS SAME NUMBER
   *  (.github/scripts/milton-surge-shape.mjs) — a fixture simplified less than
   *  production is prettier than production and judges the renderer wrongly.
   *  ==> 0.005 WAS TOO COARSE AND IT SHOWED ON GLASS. <== At that tolerance
   *  the St. Johns River rendered as a fat angular worm through Jacksonville:
   *  on a narrow winding channel it is not the AREA that shows, it is the
   *  shape, and 3.67% of area error hides a lot of shape. Measured on
   *  advisory 017, per tolerance — points, mean area error, worst:
   *
   *      0.005   1,441   1.06%   3.67%   <- shipped once, rejected by Aaron
   *      0.002   3,637   0.72%   2.76%
   *      0.001   6,729   0.33%   2.20%   <- here
   *      0.0005 11,305   0.19%   1.20%
   *
   *  The whole fixture goes 1.2 MB to ~5 MB, which is nothing on a phone, and
   *  because this is also what the relay ASKS ArcGIS for, production gets the
   *  same geometry rather than the fixture being the prettier one. */
  offsetDeg: 0.001,

  /** The five color classes, rising. Matches `SURGE_RAMP` in config/tokens.js
   *  and the `color` value the product publishes verbatim. A color outside
   *  this list is a schema change, not something to guess a severity for. */
  colors: Object.freeze(['blue', 'yellow', 'orange', 'red', 'purple']),

  /** Where the color word might live on the LIVE service, most likely first.
   *  `popupinfo` and `snippet` are Esri's standard landing spots for a KML
   *  <description> and <Snippet>, and this service is visibly a KML import —
   *  it also carries `folderpath`, `altmode`, `clamped` and `extruded`, which
   *  is that converter's fingerprint. The archived KML puts the color in
   *  <description>, so `popupinfo` is the bet.
   *
   *  ==> ALL FOUR ARE CONFIRMED TO EXIST ON THE LIVE POLYGON LAYER (read
   *  2026-08-19), WHICH IS NOT THE SAME AS KNOWING WHICH ONE ANSWERS. <== It
   *  is still a bet; it is now a bet on real fields rather than on remembered
   *  ones. */
  liveColorFields: Object.freeze(['popupinfo', 'snippet', 'name', 'folderpath']),

  /** Corridor half-width, in km, for painting a coastal reach onto the real
   *  coastline (map/coast-band.js) instead of drawing NHC's breakpoint chord.
   *
   *  ==> DELIBERATELY NARROWER THAN `COAST_BAND.halfWidthKm` (50), AND THE
   *  REASON DOES NOT TRANSFER FROM WATCH/WARNING. <== That band is wide on
   *  purpose — a warning covers an AREA and every bay inside it is warned, so
   *  over-inclusion is the desired behaviour. Surge reaches are ADJACENT AND
   *  DIFFERENTLY VALUED: "Tampa Bay 10-15 ft" sits next to a 3-5 ft neighbour,
   *  and a 50 km corridor would paint the deeper forecast tens of km onto
   *  coast NHC gave a much smaller number. That errs safe and is still a coast
   *  told the wrong depth.
   *
   *  ==> 20 km WAS TOO WIDE, AND THE REASON IS THE BASEMAP, NOT THE FORECAST.
   *  <== On this schema the coast IS the land polygon's edge, so a corridor
   *  does not select "the shoreline" — it selects every canal, dock and inlet
   *  inside it. At 20 km around Jacksonville that is the whole St. Johns
   *  waterway network, and the reach stopped reading as a coast at all.
   *
   *  8 km still catches the fronting barrier islands and the mouth of a bay,
   *  which is what a reach is issued for, without reaching inland waterways
   *  that share no water with the open coast. Still reasoning, not a
   *  measurement — judge it where two differently-colored reaches meet, and
   *  at Jacksonville, which is the worst case in the fixture. */
  bandHalfWidthKm: 8,

  /** NHC joins place and depth in one string — "Tampa Bay...8-12 ft". Only
   *  the place is taken from it; the range comes from its own field, which
   *  cannot be ambiguous. */
  nameSeparator: '...',
});

/* ---------------------------------------------------------------------------
 * GDACS SURGE — the non-American half of storm surge (SPEC-DATA.md §51)
 *
 * ==> THIS IS A DIFFERENT PRODUCT FROM `SURGE` ABOVE AND MUST NOT SHARE ITS
 *     NUMBERS. <== Read off the archive 2026-08-19, three live storms:
 *
 *   NHC Peak Storm Surge    an AREA of coast, a colour bucket, feet, US only
 *   GDACS/JRC getlocations  a NAMED TOWN, a metric height, a time of arrival,
 *                           and a time of peak — everywhere on Earth
 *
 * ==> THE RAMPS MAY NEVER BE SHARED, AND THE REASON IS A LIE THAT WOULD BE
 *     TOLD IN A COLOUR. <== `SURGE_RAMP`'s bottom rung is "up to 3 ft" — about
 * 0.91 m. Every modelled height in the entire archive is below it: Lala's
 * worst populated place is 0.17 m, Saudel's is 0.48 m. Painted on NHC's ramp,
 * every GDACS storm on Earth renders the same blue for ever, and a reader
 * would correctly conclude from the globe that surge only happens in America.
 * §6's fixed-colour contract says a red band means one thing everywhere; the
 * way to keep that promise here is a ramp of our own, not a borrowed one.
 *
 * ==> AND THE DATUMS HAVE NOT BEEN CONFIRMED TO MATCH. <== NHC publishes
 * inundation ABOVE GROUND LEVEL. What the JRC model reports its height above
 * is not stated in any byte this project has read. Until somebody confirms it,
 * putting the two numbers on one scale asserts an equivalence nobody checked.
 * ------------------------------------------------------------------------- */

export const GDACS_SURGE = Object.freeze({
  /** How near a modelled town has to be before the home dashboard will speak
   *  for the house.
   *
   *  ==> A RADIUS IS MANDATORY AND LALA IS WHY. <== That storm's 47 modelled
   *  places are all Hawaii, spread over roughly 400 km of separate islands:
   *  Hookena on the Kona coast, Hilo on the windward side, and points on Maui
   *  and Oahu. "Nearest" with no ceiling would hand a Honolulu house the Big
   *  Island's number and state it as that house's forecast. 50 km is about an
   *  hour's drive and comfortably inside one island's coast, which is the
   *  scale a JRC grid cell of 0.5 to 6 arc-minutes actually resolves. */
  homeRadiusKm: 50,

  /** How far along the coast, in km, a single town's modelled height reaches.
   *  Passed to `areaSelect` as the corridor half-width (map/coast-band.js).
   *  SPEC-DATA.md §51.7.
   *
   *  ==> IT IS NAMED FOR REACH RATHER THAN FOR WIDTH BECAUSE REACH IS WHAT IT
   *  IS SET BY. <== It was 5 km, chosen to keep a town's claim to the shoreline
   *  that town sits on. That was defensible and it produced a picture nobody
   *  could read: GDACS towns are CLUMPED, not evenly spread, so 47 towns became
   *  a scatter of short disconnected flecks rather than a coast.
   *
   *  ==> THE NUMBER IS SET BY WHERE THE GAPS ACTUALLY ARE. <== Computed, not
   *  estimated, from `samples/surge-locations/getlocations-lala-1001303.json`
   *  — 47 towns across Hawaii — using `kmBetween()`. The gaps a chain has to
   *  cross, in order:
   *
   *      3.8 km    median distance to a nearest neighbour
   *     24.2 km    THE WIDEST GAP INSIDE A RUN OF COAST (Mahaiula–Kahaluu)
   *     33.5 km    Milolii–Waiahukini, south Kona to Kau — no towns between
   *     57.7 km    Royal Gardens–Hilea, across the south of the island
   *    123.7 km    THE NARROWEST CHANNEL BETWEEN TWO ISLANDS
   *                (Kukuihaele on Hawaii → Hawaiian Village on Maui)
   *
   *  13 km reaches 26 km, which crosses 24.2 with margin and cannot approach
   *  33.5, let alone 123.7. Lala goes from 47 fragments to five continuous
   *  stripes. **The margin is on the town centres alone** — `pointRingDeg`
   *  adds about another kilometre and is deliberately not counted, so this
   *  number does not depend on the size of a shape that is a formality.
   *
   *  ==> 12 km WAS SPECIFIED AND IS 0.2 km SHORT. <== The fix was reasoned on
   *  24.2 being the widest gap between neighbouring towns, so 12 km would chain
   *  an island. Two things were wrong: 12 + 12 is 24.0, which misses 24.21 by
   *  210 m, and a widest-NEAREST-NEIGHBOUR distance is not the widest gap a
   *  CHAIN crosses. Single-link chaining at 24 km leaves six pieces; at 26 km,
   *  five. Whoever revisits this measures the chain, not the neighbours.
   *
   *  ==> WHAT THIS DOES **NOT** DO, AND MUST NOT. <== It does not join the
   *  islands and it does not close the 33.5 and 57.7 km stretches where GDACS
   *  modelled nothing. Empty coast stays empty — that is §5, not a rough edge.
   *  ==> THE NEXT THING OUT IS 123.7 km. <== Anyone widening this past ~16 km
   *  starts crossing stretches the model never ran on, and past ~60 km paints
   *  open ocean between two islands as warned coast.
   *
   *  ==> STILL WELL UNDER THE WATCH/WARNING BAND. <== `COAST_BAND.halfWidthKm`
   *  is 50 on a product with the same shape of input. Neighbours sit 3.8 km
   *  apart, so in practice a stretch carries the DEEPEST nearby town's number
   *  rather than a distant one's — `_sev` on the sort key enforces that and it
   *  errs safe.
   *
   *  ==> MEASURED ON ONE STORM IN ONE ARCHIPELAGO. <== Re-check it the first
   *  time this runs on a continental coast, where towns are denser and the
   *  "channel" between two runs may be a river mouth rather than 123 km of
   *  open sea. */
  townReachKm: 13,

  /** The square drawn around a town before `areaSelect` dilates it. Small on
   *  purpose: the shape is a formality — a point has no area and `areaBand`
   *  needs rings — and `townReachKm` is what actually sets the reach. */
  pointRingDeg: 0.01,

  /** Below this a modelled height is stated in words, never as a figure.
   *
   *  0.1 m is the bottom of what the export publishes at all — it rounds to
   *  two decimals and Lala's smallest row is exactly 0.10. Printing "0.0 m"
   *  or "0 inches" reads as a broken section rather than as a forecast, which
   *  is the identical judgement `RAIN.negligibleMm` records. */
  negligibleM: 0.1,

  /** GDACS's sentinel for "the model did not produce a height". Hernán's
   *  surge card carries exactly this, alongside a locations export holding
   *  its header feature and no towns at all. A NEGATIVE water height is not a
   *  small one — it is an absence wearing a number, and summing or colouring
   *  it would put a confident figure under a house. */
  noHeightSentinel: -1,

  /** How long the client trusts a fetched answer.
   *
   *  Longer than `RAIN.clientTtlMs` (15 min) and the reason is what is IN the
   *  payload. Rainfall's short hold is set by flood warnings that expire
   *  inside the hour; nothing here expires. A JRC run is redone per bulletin,
   *  which is six-hourly at best — measured, Lala's ECMWF index reached
   *  bulletin 15 while its GFS index reached 29 at the same instant. An hour
   *  cannot miss a run by much and saves a phone three round trips. */
  clientTtlMs: 60 * 60 * 1000,

  /** Towns kept per storm.
   *
   *  Lala returned 47 and the export is 27 KB. That is fine on the wire and
   *  wrong on a screen — a dashboard section cannot list 47 towns, and the
   *  coast layer would paint 47 overlapping corridors along one island chain.
   *  The relay keeps the deepest, because the deepest is the answer to every
   *  question anybody asks of this product. */
  maxPlaces: 60,

  /** The height buckets, rising, in METRES. Paired with `GDACS_SURGE_RAMP` in
   *  config/tokens.js, which holds the colours and the labels.
   *
   *  ==> THESE ARE NOT A TRANSLATION OF NHC'S FEET. <== They are set to the
   *  range this product actually publishes so that its own variation is
   *  visible. A scale whose every observation lands in one bucket is not a
   *  scale. Revisit when a storm is measured above two metres — the top rung
   *  is open-ended precisely so that arriving is not a schema change. */
  thresholdsM: Object.freeze([0.25, 0.5, 1.0, 2.0]),
});

/* ---------------------------------------------------------------------------
 * CAP — the national-agency alert list (SPEC §50, §56.8)
 *
 * ==> ONE TERM, AND IT DECIDES WHICH SECTION A ROW LANDS IN. <== §56.8.
 * `functions/api/cap/alerts.js` asks its upstream for five products by name
 * and one of them is `Storm Surge`. Every other kind of water in this app now
 * lives in the Flooding section, so a foreign Storm Surge Warning sitting in
 * `Watches and warnings` would split water across two sections according to
 * which feed happened to carry it — the exact arbitrariness §56.7's merge
 * deleted.
 * ------------------------------------------------------------------------- */

export const CAP = Object.freeze({
  /** The substring that sends a CAP row to Flooding instead of to Watches and
   *  warnings. Matched against the alert's `event` text, case-insensitively,
   *  exactly as `RAIN.alertEventMatch` is.
   *
   *  ==> IT MIRRORS A LITERAL IN THE ROUTE, AND THAT IS DELIBERATE RATHER
   *  THAN DUPLICATION. <== Pages Functions run in their own workerd runtime
   *  and cannot import this file (§3), so `alerts.js` carries its own
   *  `event LIKE '%Storm Surge%'`. This is the client half of the same
   *  agreement: a row can only reach the client carrying these words if the
   *  route asked for them, so the two move together or the split silently
   *  stops splitting.
   *
   *  ==> AND IT IS ENGLISH ON PURPOSE, ON A FIELD THAT IS NOT. <== `event` is
   *  the issuing agency's own words in its own language — "Fin de Influencia
   *  de Onda Tropical" is a real observed value. So this cannot be a complete
   *  test of "is this row about surge" and is not written as one. It is a test
   *  of "did this row arrive through the surge term", which is answerable,
   *  because that term is the only door a surge-only product has into this
   *  list at all. An agency publishing surge in Spanish under a cyclone name
   *  reaches Watches and warnings, which is where it was before this rule and
   *  is not made worse by it. */
  surgeEventMatch: 'storm surge',
});

/* ---------------------------------------------------------------------------
 * GENESIS — the areas being watched (SPEC §45)
 *
 * Every tunable this feature has, defined before any of its logic was written.
 *
 * THE PROBLEM THIS SOLVES, IN ONE MEASUREMENT. Both fetches minutes apart:
 * `CurrentStorms.json` returned `{ "activeStorms": [] }` while the outlook
 * query returned five watched areas, one of them at 80% over seven days. Zero
 * storms and an 80% chance of one forming, at the same instant. An all-clear
 * that is technically true of STORMS while NHC is publishing five areas is
 * exactly the honest-looking wrong answer §5 exists to prevent.
 *
 * TWO SOURCES THAT DO NOT SPEAK THE SAME LANGUAGE, AND ARE NOT MADE TO.
 * NHC gives a percentage over two and seven days. JTWC gives a word over 24
 * hours. Mapping HIGH onto some invented percentage would be inventing data.
 * They render as what each source said, each labelled with its own source and
 * its own horizon.
 * ------------------------------------------------------------------------- */

export const GENESIS = Object.freeze({
  /* --- NHC, the two- and seven-day outlook ------------------------------- */

  /* ==> THE OUTLOOK COMES FROM NHC'S KMZ, AND THERE IS NO LAYER NUMBER HERE
   * ANY MORE. <== It used to be `outlookLayer: 3` on the same MapServer the
   * cone comes from. That constant is gone rather than kept beside a comment
   * saying it is unused: the two basin URLs live in `KMZ_URL` in
   * `functions/api/nhc/genesis.js`, which is the only file that fetches them,
   * and a behavioural constant nothing reads is a fact waiting to be believed.
   *
   * IT IS THE SAME FORECASTER RUN, published on a different path and published
   * better. `tools/gtwo-compare.mjs` ran both against all 72 hourly snapshots
   * on the archive branch: every area, every vertex and every probability
   * agree, worst disagreement 4.5e-10 degrees, issue stamps matching to the
   * minute every hour.
   *
   * ONE POLYGON STILL CARRIES BOTH HORIZONS, so two-day and seven-day come
   * from one shape, exactly as before. What is new is that the document also
   * carries NHC's own name for each area, the forecaster's paragraph, and a
   * disturbance number joining an area to its current-position point.
   *
   * ==> AND A QUIET BASIN NOW SAYS SO IN WORDS. <== The whole held apparatus
   * in that route exists because an empty FeatureCollection is UNSTAMPED:
   * "NHC is watching nothing" and "NHC's layer is broken" were the same bytes.
   * The KMZ carries a dated sentence, so they are not. The apparatus still
   * stands and now fires on a narrower trigger — no areas AND no explanation —
   * which is a shape nobody has yet seen NHC publish.
   */

  /* ==> THE LAYER-2 ANCHOR PROBLEM IS SOLVED BY THE SOURCE, NOT BY US. <==
   *
   * The original plan was to hang each percentage on NHC's own label anchor
   * rather than on a centroid we computed — their point, their number. Real
   * bytes killed it (archive branch, 2026-08-09 04:24Z): five polygons on
   * layer 3 against three points on layer 2, because layer 2 is the CURRENT
   * LOCATION OF A DISTURBANCE and an area drawn for a wave that has not
   * organised yet has no current location to publish. Two of the five had no
   * point, and one of those was the second-likeliest area on the board.
   *
   * Worse, they could not be matched. Anchor objectid 1 carried "20% / Low" —
   * polygon objectid 2's attributes — while sitting at 28.5°W inside polygon
   * objectid 1's footprint. Attribute matching and nearest-centroid matching
   * disagreed on the very first feature, so either would have silently printed
   * one area's probability on another area's shape: a §5 failure that looks
   * perfect on screen.
   *
   * THE KMZ PUBLISHES THE JOIN. Every placemark — polygon and point alike —
   * carries a `Disturbance` number, so the pairing is stated by NHC rather
   * than inferred by us, and the failure above cannot happen. `_gtwo-kml.js`
   * reads it; `tools/test-gtwo-kml.mjs` pins the case where the point belongs
   * to the SECOND area rather than the first.
   *
   * The label is still drawn at our own centroid. That is now a choice about
   * placement rather than a workaround for a missing join, and it holds
   * because a centroid comes off the same feature the probability came off and
   * therefore cannot belong to the wrong area.
   */

  /** A ceiling on absurdity, and it guards a different thing than it was
   *  written for. ArcGIS had a `maxRecordCount` of 2000 and would silently
   *  return a subset at exactly that number; a KMZ has no paging and cannot
   *  truncate that way, so the specific mechanism is gone. What remains true
   *  is that a busy season peaks in the single digits, so an outlook claiming
   *  thousands of watched areas is a source that has changed shape —
   *  `data/genesis.js` says so rather than drawing it. */
  maxRecords: 2000,

  /* --- the risk vocabulary ----------------------------------------------- */

  /** The three words both sources use, canonicalised to upper case. NHC spells
   *  them "Low" | "Medium" | "High" in `risk2day`/`risk7day`; JTWC spells them
   *  LOW | MEDIUM | HIGH in prose. Same three rungs, so one vocabulary. */
  RISK: Object.freeze({ LOW: 'LOW', MEDIUM: 'MEDIUM', HIGH: 'HIGH' }),

  /** Fallback when a source publishes a risk word we do not recognise. LOW,
   *  not null and not "unknown": the area still draws, still sorts, and still
   *  says what the source actually said in its own text — it just takes the
   *  quietest treatment rather than disappearing. Dropping a watched area
   *  because of an unfamiliar adjective is the §5 failure pointed inward. */
  riskFallback: 'LOW',

  /** ==> ORDERING ONLY. THESE NUMBERS NEVER REACH THE SCREEN. <==
   *
   *  One list holds NHC percentages and JTWC words, and something has to
   *  decide which row is first. Ranking two scales against each other is a
   *  judgement call, so it is written down here rather than left to whoever
   *  implements the comparator. HIGH sorts as if it were 70%, MEDIUM 40%,
   *  LOW 10%.
   *
   *  If one of these ever appears in rendered text, that is a bug of the exact
   *  class §5 forbids — it would be presenting an invented probability as
   *  though JTWC had published it. `tools/test-genesis.mjs` asserts that no
   *  row's text contains them. */
  orderWeight: Object.freeze({ LOW: 10, MEDIUM: 40, HIGH: 70 }),

  /* --- horizons ---------------------------------------------------------- */

  /** Each source's horizon, in its own terms, for the row's meta line. Written
   *  once so no two surfaces can word the same horizon differently. */
  HORIZON: Object.freeze({
    twoDay:   'in 2 days',
    sevenDay: 'in 7 days',
    jtwc:     'in 24 hours',
  }),

  /** The heading over the forecaster's paragraph in the area panel. It names
   *  the SOURCE rather than the subject: the area's own name is already the
   *  panel's title, and the paragraph's job is being NHC's voice rather than
   *  ours. Written here so the day a second agency publishes prose, there is
   *  one place that decides how it is introduced. */
  DISCUSSION_HEAD: 'What NHC says',

  /* --- what goes on the globe -------------------------------------------- */

  /** ==> THE POLYGON IS THE SEVEN-DAY AREA, SO THE GLOBE SHOWS THE SEVEN-DAY
   *  NUMBER. <== The two-day probability has no geometry of its own — it is
   *  another field on the same seven-day shape. Putting the two-day figure on
   *  a shape drawn for the seven-day is a possible lie, and showing both gives
   *  "0% / 40%" floating over an ocean, which is unreadable at a glance and
   *  still half wrong. Aaron's call, 2026-08-09.
   *
   *  The two-day number is NOT discarded: it gets its own labelled line in the
   *  drawer row, where there is room to say which horizon it belongs to. */
  globeHorizon: 'sevenDay',

  /** ==> THE RADIUS OF A JTWC AREA'S CIRCLE, IN DEGREES. THIS SHAPE IS OURS.
   *  <== (lib/genesis.js `circleAround`.)
   *
   *  JTWC states a position and no extent, so before this a watched system in
   *  the Western Pacific drew nothing at close zoom — tap the row, fly there,
   *  land on empty ocean. Aaron asked for a shape on 2026-08-09 having heard
   *  the argument against inventing one.
   *
   *  6.04 IS MEASURED, NOT CHOSEN. It is the mean EQUIVALENT RADIUS of NHC's
   *  five live outlook polygons — sqrt(area/pi) on their own published
   *  `st_area(shape)` — which ran 5.78, 5.79, 5.80, 5.92 and 6.93. So a JTWC
   *  circle is the size a watched area actually is, and it sits among the real
   *  ones without being conspicuously rounder or bigger. If this ever needs
   *  re-deriving, the sample is in `samples/genesis/`.
   *
   *  IT DOES NOT VARY WITH RISK. Size means extent everywhere else on this
   *  globe. The area panel states in words that the shape is indicative, which
   *  is the other half of keeping it honest. */
  jtwcRadiusDeg: 6.04,

  /** Camera zoom when a watched area is selected.
   *
   *  WIDER THAN `GLOBE.flyToZoom`, WHICH FRAMES A STORM. A storm is a point.
   *  A development region measured 8-22° across on the live outlook
   *  (2026-08-09), so arriving at storm zoom would put the camera INSIDE the
   *  patch — a soft hatch filling the screen reads as a rendering fault, not
   *  as a region. This frames the whole shape with some coastline for
   *  context, which is the only way the answer "where is this" means
   *  anything. */
  flyToZoom: 3.2,

  /** Below this zoom the percentage is not drawn — the patch alone carries the
   *  layer. At planet distance a scatter of numbers over the oceans is noise,
   *  and the areas are large enough to read as shapes without them. */
  labelMinZoom: 2.2,

  /** A genesis area NEVER gets a cage at the planet band. The 3D clear globe's
   *  cages mean "a storm is here"; a cage around a maybe would say the one
   *  thing this layer must never say. Read by map/layers/genesis.js as an
   *  explicit statement rather than left as an omission somebody later
   *  "fixes". */
  planetBandCage: false,

  /* --- staleness --------------------------------------------------------- */

  /** `idp_filedate` is the publication stamp and is what the layer ages by —
   *  NOT the phone's clock, per §17.7's rule about third clocks.
   *
   *  The outlook republishes on roughly a 6-hour cadence, so 1.5x that is the
   *  same 1.5x-cadence rule the storm freshness bands use. Past this the row
   *  wears its age the way a stale storm row does. */
  staleAfter: 9 * HOUR,

  /* --- JTWC's abpwweb.txt ------------------------------------------------ */

  ABPW: Object.freeze({
    /* ==> EVERY PATTERN BELOW WAS REWRITTEN AGAINST THE REAL BULLETIN
     *     (archive branch, 2026-08-09 03:00Z). The first draft was written
     *     from §45.3's prose description and THREE OF ITS FOUR PATTERNS DID
     *     NOT MATCH. Kept as a note because the failure was silent: a parser
     *     that finds nothing returns an empty list, and an empty list here
     *     reads as "nothing is brewing in the Western Pacific". <==
     *
     * The bulletin's shape, from those bytes:
     *
     *   ABPW10 PGTW 090300                     <- WMO header, DDHHMM
     *   1. WESTERN NORTH PACIFIC AREA ...
     *      A. TROPICAL CYCLONE SUMMARY:        <- already-warned storms
     *      B. TROPICAL DISTURBANCE SUMMARY:    <- THE GENESIS CANDIDATES
     *         (1) THE AREA OF CONVECTION (INVEST 98W) ...
     *         (2) ... (REMNANTS 13W) ... IS NOW THE SUBJECT OF A
     *             TROPICAL CYCLONE WARNING.
     *         (3) NO OTHER SUSPECT AREAS.
     *      C. SUBTROPICAL SYSTEM SUMMARY: NONE.
     *   2. SOUTH PACIFIC AREA ...
     *
     * IT HARD-WRAPS MID-SENTENCE, at roughly 70 columns, including through the
     * middle of the probability sentence. Every pattern here is applied to
     * WHITESPACE-COLLAPSED text for that reason — matching the raw bytes works
     * on a good day and fails the moment a line breaks in a new place. */

    /** The WMO header, e.g. `ABPW10 PGTW 090300` or `ABIO10 PGTW 191800` —
     *  DDHHMM in UTC.
     *
     *  ==> ONE PATTERN FOR BOTH AREA BULLETINS, AND THE `PW` VERSION DID NOT
     *  MATCH `ABIO`. <== JTWC publishes exactly two of these (measured off the
     *  RSS index, 2026-08-20 — there is no third), and they are the same
     *  template with the ocean names swapped: same numbered regions, same
     *  A/B/C lettering, same `SUMMARY:` phrasing. Everything below this line
     *  is shared between them; only the header ever needed widening.
     *
     *  THE PRODUCT IS A NON-CAPTURING GROUP ON PURPOSE. The groups this
     *  returns are office, day, hour, minute, and `parseHeaderTime` reads them
     *  by number. Capturing `PW|IO` here would silently shift all four.
     *
     *  ITS TIME IS THE STAMP. The bulletin carries no other, and the fetch
     *  time is the device's clock wearing a disguise (§17.7). A bulletin whose
     *  header will not parse has no honest timestamp and is reported
     *  unavailable rather than stamped with `Date.now()`. */
    headerPattern: /\bAB(?:PW|IO)\d{2}\s+(\w{4})\s+(\d{2})(\d{2})(\d{2})\b/,

    /** Which of the two this is — `PW` or `IO`. Read only for the label a
     *  failure wears, so a session reading a bug report knows which ocean went
     *  quiet without having to fetch the bytes again. */
    productPattern: /\bAB(PW|IO)\d{2}\b/i,

    /** ==> THE TRIPWIRE THAT STOPS AN UNREADABLE BLOCK READING AS AN
     *  ALL-CLEAR. <==
     *
     *  A disturbance block says one of exactly two things: `NONE.` on the same
     *  line, or a list of `(1) (2) (3)` items. `parseAbpw` requires every
     *  block it finds to be one or the other, and calls the bulletin
     *  UNAVAILABLE when a block is neither.
     *
     *  WITHOUT IT, A REWORDING IS INVISIBLE. The item pattern finding nothing
     *  and JTWC saying nothing produce the identical empty list, and that list
     *  renders as "nothing is brewing" over an ocean somebody lives on. That
     *  is §45.3's scar exactly, and it is the whole reason the Indian Ocean
     *  half could be built against a bulletin that has only ever been seen
     *  empty: a pattern that turns out to be wrong reports a GAP rather than
     *  a calm.
     *
     *  `NONE` UNQUALIFIED, AND ANCHORED. `SUMMARY: NONE.` is the only form
     *  JTWC publishes for an empty block; anything with more words in it is a
     *  body we are supposed to have understood. */
    noneAssertion: /^NONE\.?$/i,

    /** The disturbance block — everything between `B. TROPICAL DISTURBANCE
     *  SUMMARY:` and the next lettered heading. THE ONLY PART READ.
     *
     *  Section A is the tropical-cyclone summary, and those systems are
     *  ALREADY IN THE STORM LIST from JTWC's own warnings. Parsing them here
     *  would put Typhoon 12W (DOLPHIN) on screen twice — once as a typhoon and
     *  once as a thing that might become one. */
    disturbanceBlock: /B\.\s*TROPICAL DISTURBANCE SUMMARY:\s*([\s\S]*?)(?=\s[A-C]\.\s|$)/gi,

    /** One numbered item inside that block: `(1) THE AREA OF CONVECTION ...` */
    itemPattern: /\((\d+)\)\s*([\s\S]*?)(?=\(\d+\)|$)/g,

    /** The designator, e.g. `(INVEST 98W)` or `(REMNANTS 13W)`. */
    designatorPattern: /\((INVEST|REMNANTS)\s+(\d{2}[A-Z])\)/i,

    /** ==> AN ITEM THAT HAS BEEN UPGRADED TO A WARNING IS DROPPED. <==
     *  Measured: item (2) read "(REMNANTS 13W) ... IS NOW THE SUBJECT OF A
     *  TROPICAL CYCLONE WARNING", and Tropical Depression 13W (KUJIRA) was in
     *  section A of the same bulletin. Without this the app would have shown
     *  KUJIRA as a storm and 13W as a watched area at the same instant.
     *
     *  The first draft tried to spot this by matching storm NAMES, which is
     *  the wrong end of the sentence entirely — the bulletin states the fact
     *  plainly and that is what to read. */
    upgradedPattern: /SUBJECT OF A TROPICAL CYCLONE WARNING/i,

    /** Current position: `IS NOW LOCATED NEAR 20.5N 152.3E`.
     *  `NOW` IS LOAD-BEARING. The same sentence opens with "PREVIOUSLY LOCATED
     *  NEAR 19.6N 150.5E", and a pattern without it takes the old fix — a
     *  system drawn roughly 100 nm behind where JTWC says it is. */
    positionPattern: /NOW LOCATED NEAR\s+([\d.]+)\s*([NS])\s+([\d.]+)\s*([EW])/i,

    /** The formation-odds sentence, and then the LAST risk word inside it.
     *
     *  Measured wording: "THE POTENTIAL FOR THE DEVELOPMENT OF A SIGNIFICANT
     *  TROPICAL CYCLONE WITHIN THE NEXT 24 HOURS REMAINS MEDIUM." The first
     *  draft expected "... IS MEDIUM" and matched nothing — JTWC also writes
     *  REMAINS, HAS INCREASED TO, and HAS DECREASED TO, so the verb is not
     *  something to enumerate.
     *
     *  LAST WORD, NOT FIRST: the surrounding paragraph is full of "LOW
     *  VERTICAL WIND SHEAR", and JTWC always closes this sentence with the
     *  level. Scoping to the sentence and taking the last match survives both. */
    potentialSentence: /THE POTENTIAL FOR[^.]*\./i,
    riskWord: /\b(LOW|MEDIUM|HIGH)\b/gi,

    /** A bulletin older than this is not shown at all. Reissued several times
     *  a day, so a full day's silence means the product is broken rather than
     *  quiet — and a day-old "HIGH" is a worse answer than an honest gap. */
    maxAge: 24 * HOUR,
  }),

  /* --- the drawer section ------------------------------------------------ */

  /* ==> `collapseWhenStormsPresent` AND `sectionKey` ARE GONE, AND THEIR
   *     ABSENCE IS THE DECISION. <== (Aaron, 2026-08-09.)
   *
   * The section shipped collapsing itself whenever storms were present, with
   * the user's manual choice persisted over that default. Both are deleted:
   * the section is always open and has no control that could close it.
   *
   * The original reasoning was about SPACE — five areas under six storms is a
   * long scroll on a phone. This section is about SAFETY. §45 exists because
   * an app showing storms is not thereby showing everything, so folding the
   * watch list away exactly when storms exist hides the answer at the moment
   * the app looks busiest and most complete. A count behind a chevron is not
   * the same as a list.
   *
   * Removed rather than defaulted open, because an affordance that exists gets
   * used, and one tap would have turned the feature off forever. */
});

/* ---------------------------------------------------------------------------
 * WIND SWATH SWEEP (SPEC §4 — three tiers, one envelope)
 *
 * Tuning for lib/windswath.js, which merges the past/current/forecast
 * quadrant rings into ONE smooth envelope per threshold. Aaron's call, and
 * the direct-draw ring stack was rejected on looks: overlapping translucent
 * fills compound, and beauty is a driving factor of this app. NHC's own
 * merged product (+9) is rasterized (100% axis-aligned edges, measured
 * 2026-07-24), so the clean outline is built here from the same published
 * quadrant numbers NHC built theirs from. The cosine blend cannot overshoot
 * issued radii and linear interpolation between published points is bounded
 * by its endpoints — the envelope never claims wind outside NHC's numbers.
 * ------------------------------------------------------------------------- */

export const WIND_SWEEP = Object.freeze({
  /** Track resample step, nautical miles. 6-hourly fixes sit ~70–150 nm
   *  apart; 10 nm keeps bearing changes gradual across joints (the central
   *  difference smooths the rest) at a vertex cost far below any frame
   *  concern (~450 boundary points per threshold on a 5-day storm). */
  stepNm: 10,

  /** Fan samples across each 180° end cap. 24 ≈ 7.5° per step — visually
   *  circular at every zoom the app allows, cheap. */
  capSamples: 24,

  /** Samples for the degenerate single-point run (a threshold published at
   *  exactly one time). 72 = 5° steps, matching NHC's own per-degree
   *  construction closely enough to sit flush beside it. */
  ringSamples: 72,

  /** A past point this close to the current position (degrees, per axis) is
   *  the same fix — dropped so the tier seam carries no zero-length segment
   *  (§4). Value from the spec. */
  coincideDeg: 0.05,

  /** ==> A FORECAST HOUR THE STORM HAS ALREADY DRIVEN PAST IS NOT A FORECAST,
   *  WHATEVER ITS CLOCK SAYS. <== §7.14. Nautical miles behind the current
   *  position, along the storm's published heading, before a LEADING forecast
   *  entry is dropped from the swath timeline.
   *
   *  The rule above this one drops entries whose valid hour is at or behind the
   *  fix's hour. That is a clock test and it is not enough: on 2026-08-22 Lala
   *  was at 30.3N 172.0W at 09:00Z while advisory 39 — six hours older — still
   *  forecast 30.1N 171.2W for 12:00Z. Noon had not happened yet, so the clock
   *  test kept it, and the timeline ran 43 nm ESE and then turned 210° back to
   *  the northwest. Both corridor walls swung round and crossed.
   *
   *  Shared with `FORECAST_NOW.behindGraceNm` — see `BEHIND_GRACE_NM`. */
  behindGraceNm: BEHIND_GRACE_NM,

  /** How far the two independent solves of a wind ring's own centre may
   *  disagree before the ring is declared not-a-quadrant-rose and its centre
   *  is not used (nautical miles, §7.13).
   *
   *  A rose states its centre twice over: north extent minus max(ne,nw) must
   *  equal south extent plus max(se,sw), and the same from east and west. On
   *  a real ring those two answers agree because they describe one shape.
   *
   *  MEASURED on the archived bytes, every forecast and past ring on Lala
   *  (advisory 36A, 3 thresholds x 22 past times + 21 forecast rings) and Moke
   *  (advisory 6): worst disagreement 0.55 nm, most under 0.3 nm — that
   *  residual is the polygon's arc tessellation, nothing more. The CURRENT
   *  wind field is not a clean rose and misses by 5 to 33 nm on the same
   *  bytes, which is the case this number exists to reject. Two is far above
   *  the noise and far below any real disagreement; there is no measured
   *  value anywhere in between, so this is a fence in an empty field rather
   *  than a threshold anything sits near. */
  centreSolveTolNm: 2,

  /** Hard ceiling on resample steps per run. A pathological track widens
   *  its step rather than exploding the vertex budget — jank is worse than
   *  a slightly coarser outline (§9: feel is the overriding lens). */
  maxSamples: 2000,

  /** Iterated 3-point averaging passes over the resampled centres and
   *  quadrant values BEFORE offsetting. This is THE smoothness dial —
   *  Aaron's call after the first on-glass look (2026-07-24): the linear
   *  blend carried a corner through every 6-hourly fix and the walls
   *  mirrored every track wobble. Gaussian-equivalent sigma ≈
   *  sqrt(passes/2)·stepNm ≈ 22 nm at 10. Bounded: smoothed radii stay
   *  between neighbours (never above any published value); centres drift
   *  only where the track curves, by less than the track's own deviation
   *  in the window. 0 restores the exact piecewise-linear sweep. */
  smoothPasses: 10,

  /** Averaging passes on the final closed ring — rounds wall/cap junctions
   *  and rounds residual despike corners. Runs on the UNIFORMLY RESAMPLED
   *  ring (see lib/windswath.js — on irregular spacing this same pass
   *  SHARPENED angles). Can nudge concave vertices outward by
   *  the sagitta at one step's spacing (a couple nm, worst case); see the
   *  bound note in lib/windswath.js. */
  ringSmoothPasses: 3,

  /** A boundary vertex turning more than this (degrees) ON SHORT SEGMENTS
   *  is a wall fold and is cut. Genuine features turn less or ride
   *  step-length segments — see the despike note in lib/windswath.js. */
  spikeTurnDeg: 100,

  /** "Short" for the fold test, nm. Just over half the resample step:
   *  fold vertices bunch far below step spacing; honest vertices sit at
   *  it. */
  spikeMaxSegNm: 6,

  /** ==> HOW MANY SELF-INTERSECTION LOOPS ONE RING MAY HAVE CUT OUT. <==
   *
   *  The despike above only removes HAIRLINE folds — a sharp turn on short
   *  segments. It cannot see a genuine crossing: offset a curve inward by
   *  more than its own radius of curvature and the wall loops round and
   *  crosses itself, over tens of vertices, at honest step spacing. That is
   *  a real self-intersection, not a spike, and it drew as the fins and
   *  spurs Aaron reported on 2026-08-21.
   *
   *  MEASURED on the archived bytes, before the cut: Lala's 34 kt ring
   *  carried 3 crossings enclosing 90, 41 and 25 vertices; 50 kt carried 3
   *  (52, 25, 5); one 64 kt run carried 1 (26). Every one sat between 27.8N
   *  and 30.4N — the recurve.
   *
   *  Eight is far above the six a real storm produced and far below a
   *  runaway. This is a GUARD, not a tuning dial: hitting it means the cut
   *  is not converging, and the ring is emitted with a warning rather than
   *  the loop pass spinning. Raising it to hide a warning would be treating
   *  the symptom. */
  maxLoopCuts: 8,
});

/* ---------------------------------------------------------------------------
 * BASEMAP TILES (SPEC §11)
 *
 * Protomaps, self-hosted on Cloudflare R2, capped at z8, served through the
 * Pages Function tile proxy at `functions/tiles/[[path]].js`. The proxy reads
 * single tiles out of the 525 MB .pmtiles archive in the bucket and stamps
 * them cache-forever (coastlines don't move), so tiles cache at Cloudflare's
 * edge AND in the browser. The client never talks to the bucket directly and
 * never loads the pmtiles library — it just fetches ordinary tile URLs.
 *
 * The archive's R2 object key lives in the function file, not here — it is a
 * server-side concern, and the function is deliberately self-contained rather
 * than importing client config across the functions/ boundary. The two files
 * cross-reference each other by comment.
 *
 * Still outstanding: `glyphs` in style.js points at OpenFreeMap's font
 * endpoint regardless of this flag, so text layers (storm names, live since
 * Phase 2) fetch from OpenFreeMap even on R2 tiles. Self-hosting fonts in the
 * same bucket is a separate decision — see SPEC §15.
 * ------------------------------------------------------------------------- */

export const TILES = Object.freeze({
  /** OpenFreeMap is the basemap. The R2/Protomaps path — still carried by
   *  style.js and coast-source.js — is OFF: its tile proxy cold-reads
   *  each tile out of a 525 MB archive, so panning to new areas lagged, and
   *  its land-polygon schema fragments the outer coast into separate barrier
   *  islands, which breaks watch/warning coast tracing. OpenMapTiles' ocean-
   *  polygon coast is continuous and traces cleanly. Set true to revive R2. */
  useR2: false,

  /** The tile proxy, absolute on purpose: a local dev server has no Pages
   *  Functions, so relative URLs would 404 in dev. The proxy sends
   *  `Access-Control-Allow-Origin: *`, which is what lets localhost fetch
   *  these cross-origin. */
  tilesUrl: 'https://landfall.getgravitate.app/tiles/{z}/{x}/{y}.mvt',

  /** The archive's zoom ceiling (SPEC §11 — a design decision, not a budget
   *  one). MapLibre needs this on the source to overzoom z8 data past z8
   *  instead of requesting tiles that don't exist. */
  sourceMaxzoom: 8,

  /** SPEC §11 names OpenFreeMap as the legitimate fallback if self-hosting
   *  becomes a burden.
   *
   *  NOTE: OpenFreeMap serves the OpenMapTiles schema; Protomaps serves its
   *  own. They are not interchangeable by layer name — OpenMapTiles has no
   *  land polygon at all. style.js handles this structurally with two
   *  separate layer builders rather than a name lookup. */
  openFreeMapStyle: 'https://tiles.openfreemap.org/planet',
});

/* ---------------------------------------------------------------------------
 * PERSISTENCE
 *
 * Layer choices and section collapse state persist per device.
 * STORM SELECTION DOES NOT — reopening drops you on the globe, not on
 * yesterday's dissipated storm.
 *
 * Home is stored locally on the device only. No accounts, no server-side
 * user data, ever.
 * ------------------------------------------------------------------------- */

export const STORAGE_KEY = Object.freeze({
  layers: 'landfall.layers',
  /* Display preferences that are NOT layer choices. Separate key from
   * `layers` because layer state carries phase-gating rules that display
   * preferences do not, and merging them would put an unshipped-layer guard
   * in front of a setting that has no phase. */
  settings: 'landfall.settings',
  /* NO 'models' KEY, deliberately — retired unbuilt 2026-07-25. Which models
   * draw is a SUB-CHOICE of the model-tracks layer, so it lives inside the
   * `layers` record above rather than in a store of its own. A third
   * preference store is the point at which data/settings-prefs.js says to
   * extract a shared factory (§12), and inventing one for state that already
   * has a rightful owner would spend that refactor on nothing. */
  home: 'landfall.home',
  units: 'landfall.units',
  /* NO 'theme' KEY — retired 2026-07-26 when light mode shipped. The theme is
   * a DISPLAY PREFERENCE and lives in the `settings` record above with the
   * others, which is what gives it the same load-sanitise-persist-emit rules
   * and the same segmented control for free. A key of its own would have been
   * a second store for one string. */
  /* NO 'scope' KEY — the scope filter was retired 2026-07-25 (see the note
   * where SCOPE used to live). A stored value for a control that no longer
   * exists is a key nothing will ever read again. */
  sections: 'landfall.sections',
  lastVisit: 'landfall.lastVisit',
  /* First-run nudge state (home prompt, install hint) — ui/first-run.js. */
  firstRun: 'landfall.firstRun',
  /* Storms that have ENDED, with their last-known record and past track —
   * data/lifecycle.js. THE ONLY PERSISTED STORE THAT HOLDS STORM DATA rather
   * than a preference, and it has to, for a reason no other key shares: an
   * ended storm is out of both feeds, so a reload has nothing to rebuild it
   * from. Every other store on this list can be thrown away and refetched. */
  ended: 'landfall.ended',
  /* How close every storm since 1851 came to this house — data/near-home-index.js.
   * THE ONLY KEY ON THIS LIST THAT HOLDS A COMPUTED ANSWER RATHER THAN A
   * PREFERENCE OR A RECORD, and it is here for one reason: producing it costs
   * a 0.93 MB download and a pass over 84,365 track segments, so doing it once
   * per house beats doing it once per visit.
   *
   * ==> LOSING IT MUST BE SILENT. <== §57.35 FIX 8's one surviving sentence.
   * It is a cache of an answer that can always be recomputed, so a cleared
   * store means "work it out again", never "no storm has ever come near you".
   * Absence is this whole feature's subject and is the one thing it must not
   * accidentally state. */
  nearHome: 'landfall.nearHome',
  /* The anonymous device number — lib/device-id.js. THE ONLY KEY ON THIS LIST
   * THAT IS SENT ANYWHERE, and the only cross-visit identifier this app has
   * ever had. Added 2026-08-05 as a deliberate reversal of the old "no
   * cross-visit identifier" line; read lib/device-id.js before touching it.
   * Clearing site data clears it and the device becomes a new device, which
   * is the intended and only reset. */
  device: 'landfall.device',
});

/* ---------------------------------------------------------------------------
 * FIRST-RUN NUDGES (ui/first-run.js) — §14 Phase 5.
 * One-time hints, never nags: each shows once and its dismissal persists.
 * ------------------------------------------------------------------------- */
export const FIRST_RUN = Object.freeze({
  /** How long after boot the "set your home" hint waits. The entry moment
   *  belongs to the globe — a callout talking over the opening animation
   *  reads as an ad. Long enough for the scene to settle and the user to
   *  have looked at it. */
  homeNudgeDelayMs: 8000,

  /** Pause between home being set and the install hint. Setting home opens
   *  a panel flow; the hint waits for that moment to finish rather than
   *  landing on top of the confirmation. */
  installNudgeDelayMs: 2500,
});

/* ---------------------------------------------------------------------------
 * ON-SCREEN KEYBOARD (SPEC §10)
 *
 * The drawer is a fixed bottom sheet on a phone, and iOS does not shrink the
 * layout viewport when the keyboard appears — so without these the keyboard
 * covers the sheet and you type blind. ui/keyboard.js measures, panels.css
 * responds.
 * ------------------------------------------------------------------------- */

export const KEYBOARD = Object.freeze({
  /** Below this, whatever shrank the visual viewport was NOT a keyboard.
   *  Safari's address bar growing back on scroll costs tens of pixels; the
   *  shortest phone keyboard is well over two hundred. A floor between the two
   *  stops the sheet twitching while somebody is only reading. */
  minInsetPx: 120,

  /** How long the keyboard takes to finish arriving. iOS animates it in about
   *  a quarter second and reports the new viewport size in stages, so anything
   *  that wants to position against the FINAL size has to wait this out.
   *  Deliberately a shade longer than DURATION.base — it is a hardware
   *  animation we do not control and cannot observe the end of. */
  settleMs: 300,
});

/* ---------------------------------------------------------------------------
 * SLIDERS (SPEC §16)
 *
 * A range input commits a value the instant it is pressed, anywhere along its
 * track. Inside a scrolling settings sheet that means a thumb travelling past
 * a slider changes it — the user was scrolling, not adjusting. ui/slider-grab.js
 * refuses any press that did not land on the thumb; these are its two numbers.
 * ------------------------------------------------------------------------- */

export const SLIDER = Object.freeze({
  /** Extra pixels either side of the drawn thumb that still count as grabbing
   *  it. The thumb is 20px with a mouse and 28px with a finger, so this puts
   *  the real grab zone at 40px and 48px respectively — the coarse case clears
   *  the 44px touch rule, and the fine case does not need to because a mouse
   *  points where it is looking. Bigger than this and the "you must grab the
   *  thumb" contract starts blurring back into "anywhere near it works",
   *  which is the behaviour being removed. */
  grabSlopPx: 10,

  /** Fallback thumb diameter if `--slider-thumb` cannot be read off the
   *  element. Should never happen — the token is declared on `:root` in
   *  index.html before any stylesheet loads — but a NaN here would silently
   *  make the grab zone zero pixels wide, i.e. a slider nobody can move. */
  thumbFallbackPx: 20,
});

/* ---------------------------------------------------------------------------
 * TELLING A TAP FROM THE START OF A DRAG (SPEC §10, §13, §57.21d)
 *
 * ==> THESE TWO NUMBERS EXIST BECAUSE A TAP AND THE START OF A DRAG ARE THE
 * SAME EVENT. <== A pointer goes down and comes up again. Whether that was
 * somebody pressing the globe or somebody beginning to spin it is decided by
 * how far it travelled and how long it took, and nothing else. Get it wrong in
 * one direction and a press does nothing; get it wrong in the other and the
 * globe stops being draggable while a sheet is open.
 *
 * ==> MAPLIBRE ALREADY ANSWERS THE MOVEMENT HALF, AND THAT IS MEASURED RATHER
 * THAN ASSUMED. <== `vendor/maplibre-gl-5.6.0.js` holds the mousedown position
 * and refuses to fire `click` at all once the pointer has moved
 * `clickTolerance` pixels or more — its click handler is exactly that one test.
 * So anything hanging off `map.on('click')` gets movement discrimination for
 * free, and writing a SECOND movement threshold on top would be two numbers
 * that have to agree and eventually will not. `movePx` below is handed to the
 * map at construction instead, so the number lives here with every other
 * behavioural constant rather than on MapLibre's undocumented default.
 *
 * ==> WHAT MAPLIBRE DOES NOT GATE ON IS TIME. <== A press held still for a
 * second — a drag the globe declined to follow, or a thumb resting while its
 * owner reads — arrives as an ordinary click. `maxMs` is enforced by us.
 * ------------------------------------------------------------------------- */

export const TAP = Object.freeze({
  /** How far a pointer may travel between down and up and still be a tap.
   *
   *  ==> IT IS MAPLIBRE'S OWN DEFAULT, WRITTEN DOWN. <== 3 px is what
   *  `clickTolerance` is when nobody passes one, so adopting it changes no
   *  behaviour on the day it lands — which is the point: this is a number
   *  moving into the open, not a number being tuned. Raise it if a phone
   *  reports taps being eaten; three pixels is under a tenth of a millimetre
   *  of thumb travel at any sane pixel ratio, and a finger rolling on the
   *  glass covers it easily. */
  movePx: 3,

  /** How long a press may last and still be a tap, milliseconds.
   *
   *  ==> HALF A SECOND, WHICH IS WHERE EVERY PLATFORM PUTS LONG-PRESS. <== iOS
   *  and Android both call roughly this the boundary between a tap and a hold,
   *  so a reader's hand already knows it. Below it a press is deliberate;
   *  above it the intent was something else — usually a drag the globe would
   *  not follow, which must not be answered as if it were a press on what
   *  happens to be underneath.
   *
   *  ==> THE FAILURE THIS PREVENTS IS ASYMMETRIC, WHICH IS WHY IT IS GENEROUS.
   *  <== Refusing a real tap costs a second press. Answering a failed drag
   *  minimises the sheet somebody was trying to pan the globe behind, and they
   *  have to open it again. Half a second is comfortably past any tap and
   *  comfortably short of any rest. */
  maxMs: 500,
});

/* ---------------------------------------------------------------------------
 * UNITS (SPEC §8)
 *
 * Wind stored in KNOTS, everywhere, always. Distance in NAUTICAL MILES.
 * Every threshold in this app — the 34/50/64 kt bands, the Saffir-Simpson
 * breakpoints — is defined in knots. Convert ONLY at the moment of drawing
 * text. Converting internally means rounding drift, and drift near a
 * threshold flips a storm between categories.
 * ------------------------------------------------------------------------- */

export const UNITS = Object.freeze({
  IMPERIAL: 'imperial',
  METRIC: 'metric',
  AUTO: 'auto',
});

/** Saffir-Simpson breakpoints in knots. The only place these numbers exist. */
export const CATEGORY_THRESHOLD_KT = Object.freeze([
  { min: 137, category: 6 }, // Cat 5
  { min: 113, category: 5 }, // Cat 4
  { min: 96,  category: 4 }, // Cat 3
  { min: 83,  category: 3 }, // Cat 2
  { min: 64,  category: 2 }, // Cat 1
  { min: 34,  category: 1 }, // Tropical Storm
  { min: 0,   category: 0 }, // Tropical Depression
]);

/** Nominal top of the scale, knots. Cat 5 is OPEN-ENDED (137 kt and up), so it
 *  has no arithmetic middle of its own; this supplies one. 155 kt sits between
 *  the Cat 5 floor and the strongest storms on record, so a Cat 5's
 *  representative wind lands high without pretending to be a record.
 *
 *  Used ONLY to derive class midpoints (lib/category.js `representativeKt`).
 *  It is NOT a threshold, NOT a cap on real measured wind, and nothing
 *  classifies against it — a storm reporting 180 kt is still read as 180 kt
 *  everywhere the actual number is known. */
export const CATEGORY_TOP_KT = 155;


/* ---------------------------------------------------------------------------
 * JTWC WIND — real knots for the basins GDACS covers (SPEC §4, §6, §9)
 *
 * THE PROBLEM THESE NUMBERS BOUND. GDACS publishes no current wind for any
 * storm. Its present-tense reading is three words, and its strongest word
 * covers everything from a marginal Cat 1 to a 160 kt super typhoon — so every
 * GDACS hurricane drew at the same ~109 kt of cage lift, TALLER THAN A MEASURED
 * NHC CAT 3. JTWC warns on the same basins, publishes one-minute sustained
 * wind exactly as NHC does, and is already fetched in full by
 * /api/jtwc/storms. lib/jtwc-wind.js does the join; these are its limits.
 *
 * EVERY VALUE HERE EXISTS TO STOP A WRONG WIND, not to catch more storms. A
 * GDACS storm with no JTWC wind falls back to today's class midpoint, which is
 * documented, visibly derived, and never displayed as a measurement. A GDACS
 * storm wearing ANOTHER storm's wind is a §5 lie on the one channel the whole
 * severity ramp reads. When these two outcomes compete, the fallback wins.
 * ------------------------------------------------------------------------- */

export const JTWC_WIND = Object.freeze({
  /** How far apart the two agencies' fixes may sit and still be believed as
   *  the same storm, in nautical miles.
   *
   *  DERIVED, not picked. The feeds run on the same six-hourly synoptic clock
   *  but not the same minute, so a genuine pair can be a full cycle apart: six
   *  hours at a fast tropical translation speed of ~20 kt is 120 NM, and JTWC
   *  itself reports position accuracy as poor as 60 NM (`POSITION ACCURATE TO
   *  WITHIN 060 NM`, live on 12W). 200 NM covers both with room and is still
   *  far tighter than the distance between two unrelated cyclones.
   *
   *  IT ALSO DOES A SECOND JOB THAT IS WORTH MORE THAN THE FIRST. When GDACS
   *  freezes on a storm and JTWC keeps warning — Noul, 2026-07-26, the exact
   *  case in the SILENCE note above — the two positions walk apart within a
   *  cycle, this test fails, and the storm keeps its stale GDACS reading
   *  instead of getting a live wind pasted onto a two-day-old position. That
   *  is the honest answer: we do not know that those are the same fix. */
  maxSeparationNm: 200,

  /** Oldest JTWC fix that may be called a storm's CURRENT wind.
   *
   *  Two warning cycles. JTWC warns every 6 h, so one missed cycle is normal
   *  and two is the point at which "this is the wind now" stops being a claim
   *  we can make. Past this the storm keeps its GDACS classification and the
   *  derived midpoint — worse resolution, but honest about its age. */
  maxFixAge: 12 * HOUR,

  /** How close a JTWC forecast hour must be to a GDACS track point before its
   *  wind is used for that point.
   *
   *  Both agencies publish on synoptic hours (00/06/12/18Z), so a real pair
   *  lands exactly or not at all; 3 h is half a step, which accepts the
   *  matching hour and can never reach the neighbouring one. NOT INTERPOLATED
   *  between taus: an interpolated wind is a number no agency published, and
   *  the whole point of this change is to stop feeding the ramp numbers nobody
   *  measured. A point with no matching tau falls back to the class midpoint,
   *  exactly as it does today. */
  forecastMatchTolerance: 3 * HOUR,
});

/* ---------------------------------------------------------------------------
 * COAST BAND (SPEC §7)
 *
 * NHC publishes watch/warnings as BREAKPOINTS — named coastal reference
 * points — and the MapServer joins them with straight lines. Measured live on
 * Bertha, 2026-07-23: 11 vertices over 464 km, median spacing 51 km, max 70.
 * Drawn as delivered, that chords across every bay.
 *
 * The fix is a WIDE-BAND SELECT (map/coast-band.js): buffer the breakpoint
 * line into a corridor and paint every loaded coast segment inside it the
 * warning color. Deliberately wide — a watch/warning is issued for an AREA,
 * and every bay, inlet, and barrier island inside it is under the warning.
 * ------------------------------------------------------------------------- */

export const COAST_BAND = Object.freeze({
  /** THE ONE KNOB: corridor half-width in km, set GENEROUS on purpose.
   *  Prototyped 2026-07-24 against Bertha's live TWR (8 breakpoints,
   *  Matagorda→Vermilion Bay) at 15/25/35/50 km: 15 caught only half of
   *  Galveston Bay; 35 painted the full Galveston–Trinity–Sabine bay system;
   *  50 additionally reached the inner Matagorda Bay shore near the western
   *  breakpoint. Aaron picked 50 off the prototype panels — wider wins
   *  ("cast a wide band"; a warning is issued for an AREA and the bays are
   *  in it). Jumping to a genuinely different, unwarned stretch of coast is
   *  the only failure to avoid, and the flat end caps handle that. */
  halfWidthKm: 50,

  /** ==> HOW FAR OUTSIDE A CAP WARNING AREA STILL COUNTS AS INSIDE IT (§50.11).
   *  <== The corridor above fattens NHC's breakpoint LINES because a line has
   *  no width. This one does the opposite job on a shape that already has one:
   *  a national agency's polygon is a statement about jurisdiction, drawn
   *  against THEIR basemap, and where their outline runs slightly inland ours
   *  puts the real shoreline outside it. A strict inside-test then paints
   *  nothing along exactly the coast the warning is about.
   *
   *  ==> 5 km, AN ORDER OF MAGNITUDE UNDER THE NHC CORRIDOR, AND THAT
   *  ASYMMETRY IS THE POINT. <== 50 km is a deliberate over-reach around a
   *  line that carries no area of its own. Here the area IS published, so the
   *  pad has one job — absorbing disagreement between two coastline datasets
   *  and coarse tracing — and anything wider would start claiming coast the
   *  agency did not warn. Errs outward, which for a warning is the safe
   *  direction (§5), but only just.
   *
   *  UNJUDGED. Nothing has been on glass with a live foreign warning. If the
   *  stripe undershoots at a river mouth or an offshore island, this is the
   *  dial. */
  areaPadKm: 5,

  /** Below this many coast vertices, don't attempt a select at all. A handful
   *  of vertices from one half-loaded tile produces a confident-looking band
   *  in the wrong places, which is worse than the honest chord (§5). The
   *  2026-07-23 probe measured 3720 vertices at z6.4, so a real coast clears
   *  this by an order of magnitude. */
  minCoastVertices: 200,

  /** Tile-boundary filter. A tile-clipped ocean polygon's ring is part real
   *  shoreline and part straight tile edge; painting a tile seam as warned
   *  coastline is a confident wrong line (§5). An edge is dropped when it is
   *  EXACTLY axis-aligned (within tileEdgeEpsDeg — float slack around the
   *  tile boundary's constant coordinate, ~0.1 m) AND at least tileEdgeMinKm
   *  long. Cost of a false drop is an invisible gap in the stripe; cost of a
   *  false keep is a straight seam across the map.
   *
   *  ==> RAISED FROM 0.25 km ON 2026-08-10. THE OLD HEADROOM WAS WRONG. <==
   *  Vector tile coordinates are quantized to 4096 units across a tile, so at
   *  z6 one quantum is ~152 m and the old threshold was 1.67 quanta, not the
   *  ~2 the comment claimed. Two consecutive REAL coastline points landing on
   *  the same quantized meridian therefore produced a 300 m axis-aligned
   *  segment that got dropped as a seam. Those gaps were then frozen into the
   *  cached band and shown at every zoom above the one that made them —
   *  reported on glass as a broken, disjointed stripe.
   *
   *  1.0 km is ~6.5 quanta at z6 and ~3 at z5, and it stays safe in the other
   *  direction because a genuine tile seam crossing a 100 km corridor is
   *  kilometres long, never a few hundred metres. Real coastline that runs
   *  dead straight for over a kilometre on an exact meridian — a Louisiana
   *  canal, a jetty — is still dropped, and always was; that is the residual
   *  cost of this filter and it is an invisible gap, not a wrong line. */
  tileEdgeEpsDeg: 1e-6,
  tileEdgeMinKm: 1.0,

  /** ==> THE BAND IS CACHED PER ZOOM, BECAUSE BAND QUALITY IS PER ZOOM. <==
   *
   *  The cache used to hold ONE best band per storm and replace it only on a
   *  strict improvement, scored by painted features, then painted km. Coast
   *  vertices come from LOADED TILES ONLY, so zooming in shows less coast in
   *  finer detail — fewer features painted, far fewer km — and the sharper
   *  select lost every single time. The band froze at whatever zoom first
   *  covered the most coastline, which is also the coarsest geometry the
   *  basemap has, while the cyan coastline underneath it kept sharpening. At
   *  8 px nobody could see it; at coastline width it reads as a stripe that
   *  cannot keep up with its own coast (Aaron, on glass, 2026-08-10).
   *
   *  Bucketing by integer zoom is the fix, and it is what the basemap itself
   *  does: it draws a different coastline at each zoom rather than one best
   *  one. Each bucket accumulates independently, so zooming in computes a
   *  fresh band at that zoom's detail instead of losing to the wide one, and
   *  zooming back out still finds the wide band waiting.
   *
   *  Entries are capped and evicted least-recently-used. A band on a coast
   *  like the Mississippi delta is thousands of vertices, and buckets
   *  multiply by storms, so this cannot be unbounded on a phone. 24 is a
   *  handful of storms across a handful of zooms — well past what one
   *  session visits — and an eviction costs one re-select, not a wrong line. */
  maxBandEntries: 24,

  /** Vertices kept per warning feature within one bucket. Panning ACCUMULATES
   *  runs (see the cache header on why it merges rather than picks a winner),
   *  so a long session at high zoom along a complex coast has to have a
   *  ceiling. Oldest runs are dropped first: the newest are the ones nearest
   *  where the camera actually is. 40000 is roughly the whole Louisiana coast
   *  at full basemap detail, so hitting it at all means the user has panned
   *  across more coastline than fits on any screen. */
  maxBandVertices: 40000,

  /** Wait after the camera settles before re-selecting, when there is already
   *  a band on screen for this zoom.
   *
   *  ==> IT IS A GUARD AGAINST REDUNDANT WORK, NOT A FIXED DELAY, AND IT USED
   *  TO BE BOTH. <== At 400 ms it was the single largest part of the lag
   *  between a pinch ending and the stripe repainting — nearly half of it, and
   *  all of it spent doing nothing. A pinch on a phone fires several moveends
   *  in a row over roughly a tenth of a second, so 120 ms still collapses them
   *  into one select, which is the entire job this number has.
   *
   *  ==> AND IT IS SKIPPED ENTIRELY WHEN THIS ZOOM HAS NO BAND YET. <== The
   *  wait protects work already on screen. Landing in a zoom bucket that has
   *  never been selected has nothing to protect: the stripe showing is the
   *  previous zoom's, at the previous zoom's detail, and waiting only holds
   *  the wrong geometry on screen for longer. See map/coast-band-cache.js
   *  `bandMissingFor`. */
  reselectDebounceMs: 120,
});

/**
 * GDACS per-event geometry shape.
 *
 * EVERY VALUE HERE WAS READ OFF LIVE DATA on 2026-07-24 via
 * `/api/gdacs/inspect?event=1001294&episode=6` (NOUL-26, Northwest Pacific).
 * Nothing in this block is inherited from the HA project — the inherited
 * version of it was WRONG about the thresholds, which is exactly why the
 * inventory happened first.
 *
 * The payload is one FeatureCollection, 44 features for that storm, sorted
 * by two properties:
 *   `Class`       — "Poly_Green" | "Poly_Orange" | "Poly_Red" | "Poly_Cones"
 *                   | "Line_Line_N" | "Point_Polygon_Point_N" | "Point_Centroid"
 *   `featuretype` — "WindRadii" (the bands) | "PointRadii" (per-timestep dots)
 */
export const GDACS_GEOMETRY = Object.freeze({
  /**
   * THE BAND THRESHOLDS — the finding that killed the inherited claim.
   *
   * SPEC used to say Green/Orange/Red were the 34/50/64 kt NHC thresholds.
   * They are NOT. GDACS works in ROUND METRIC numbers, published in each
   * band's own `polygonlabel`:
   *
   *   Poly_Green   60 km/h  ≈ 32.4 kt   (median area 3.92 sq°)
   *   Poly_Orange  90 km/h  ≈ 48.6 kt   (median area 1.03 sq°)
   *   Poly_Red    120 km/h  ≈ 64.8 kt   (median area 0.16 sq°)
   *
   * Near the NHC thresholds, deliberately not identical. Confirmed twice
   * over: the labels state the speeds, AND the areas nest strictly
   * (Green widest → Red smallest), which is what wind bands must do
   * physically. Two independent agreeing checks is why this is settled.
   *
   * We draw them in the §6 34/50/64 colors because they are the same three
   * severity tiers a reader is being asked to distinguish. We do NOT relabel
   * them as 34/50/64 kt anywhere the user can see — that would put words in
   * the source's mouth. The panel says what GDACS actually published.
   */
  bandClass: Object.freeze({
    Poly_Green: Object.freeze({ kmh: 60, colorKey: 34 }),
    Poly_Orange: Object.freeze({ kmh: 90, colorKey: 50 }),
    Poly_Red: Object.freeze({ kmh: 120, colorKey: 64 }),
  }),

  /** A polygon whose entire bounding box is smaller than this (degrees) is
   *  GDACS saying "this threshold does not reach this forecast point" — it
   *  publishes a zero-area shape rather than omitting the feature.
   *  MEASURED on real data (NOUL-26 green band, raw dump 2026-07-24): the
   *  last two forecast steps were each 330 identical copies of one
   *  coordinate. These must be dropped before any geometry work: a
   *  zero-radius shape collapses the centroid onto itself, zeroes the
   *  radial profile, and tapers the merged corridor to a point — the
   *  pinched ends Aaron reported. Coordinates are published to 4 decimals,
   *  so a real shape is orders of magnitude bigger than this threshold and
   *  anything smaller is sub-pixel at any zoom. */
  degenerateSpanDeg: 0.001,

  /** `featuretype` on the three band classes. The per-timestep centre dots
   *  carry "PointRadii" and are NOT bands — 30 of the 33 polygons in that
   *  payload were dots. Drawing them as bands would be soup. */
  windRadiiType: 'WindRadii',

  /* --- the per-timestep centre dots, READ LIVE 2026-07-24 (NOUL-26, all 12
   * "Point" features dumped together). Every claim below is off those bytes.
   *
   * THE DOTS ARE POLYGONS, NOT POINTS. Each is a 129-vertex circle of radius
   * 0.03° around the storm centre. An earlier read of a single feature said
   * "true GeoJSON Point" — that feature was the CENTROID, which is the one
   * exception in the set. Take the bounding-box centre, which is exact for a
   * symmetric ring and survives GDACS changing the vertex count.
   *
   * `Class` is `Point_Polygon_Point_N`, N running 0..10 in chronological
   * order. We do NOT trust N: the times are parsed and sorted, so a
   * renumbering upstream cannot silently reorder a track. ------------------ */

  /** `featuretype` shared by every centre dot. */
  pointRadiiType: 'PointRadii',

  /** `Class` prefix on the timestep dots. */
  pointClassPrefix: 'Point_Polygon_Point_',

  /** The storm's CURRENT position as its own feature — and the one true
   *  GeoJSON Point in the payload. It is not a timestep and carries no key
   *  or date, so it must never enter the track. */
  centroidClass: 'Point_Centroid',

  /** Two coordinates closer than this (degrees) are the same place, when
   *  joining a track segment's endpoint to a dot's centre. Measured spacing
   *  between consecutive dots is ~0.5–2°, and the join is expected to be
   *  exact, so this is slack for float noise — not a fuzzy match. */
  pointJoinEpsilonDeg: 0.02,

  /** Track intensity code → our category index (0 = TD, 1 = TS).
   *
   *  HU IS DELIBERATELY NULL, and this is the whole reason GDACS forecast
   *  points cannot carry a Saffir-Simpson number: its strongest published
   *  wind band is 120 km/h = 64.8 kt, which IS the Cat 1 floor. A Cat 1 and
   *  a Cat 5 produce an identical band set. "Hurricane" is the finest read
   *  available, so a hurricane dot states HU and takes the generic hue
   *  rather than borrowing Cat 1's color it has not earned (§6). */
  trackIntensityIndex: Object.freeze({ TD: 0, TS: 1, HU: null }),

  /** The forecast cone. GDACS DOES publish one — `Poly_Cones`, a single
   *  207-point polygon labelled "Uncertainty Cones". data/gdacs.js declared
   *  `cone: false` on inherited authority and was wrong. */
  coneClass: 'Poly_Cones',

  /** Track segments: 2-point LineStrings, `Class` "Line_Line_N". Each is
   *  labelled with an intensity code in `polygonlabel` and split past vs
   *  forecast by the `forecast` property. */
  linePrefix: 'Line_',

  /** `forecast` arrives as the STRING "true"/"false", not a boolean. */
  forecastTrue: 'true',

  /** Band label format, e.g. "120 km/h". Parsed rather than trusted blindly:
   *  if GDACS renumbers a band, the parsed value disagrees with the expected
   *  kmh above and we drop it rather than paint the wrong color (§6). */
  bandLabelPattern: /^\s*(\d+(?:\.\d+)?)\s*km\/h\s*$/i,

  /** How far a published label may drift from the expected speed before the
   *  band is treated as unrecognized. Absolute km/h. Small on purpose: this
   *  is a safety mapping, not a fuzzy match. */
  bandLabelToleranceKmh: 5,

  /** GDACS's OWN conversion ratio, which is not the app's. The app renders
   *  with the exact 1.852; GDACS's published figures round-trip through
   *  1.85184 (spec-parameter §34.2). Harmless on a display string, but a
   *  BRACKET DERIVED FROM GDACS'S OWN THRESHOLDS must divide by GDACS's own
   *  ratio or the bounds drift off the numbers the source meant:
   *  60/90/120 km/h → 32/49/65 kt, matching the audit's validated table
   *  (spec-parameter §28.2). */
  kmhPerKtGdacs: 1.85184,

  /** How wide a window, centred on each quadrant's own bearing (45/135/225/
   *  315), `lib/quadrant-radii.js` samples when reading a band's radii back
   *  out of its drawn shape.
   *
   *  MEASURED, AND THE FAILURE IT AVOIDS IS SPECIFIC. A GDACS band is four
   *  constant-radius sectors joined by RADIAL SEAMS at 0/90/180/270, and a
   *  seam's vertices carry every value between the two sectors it joins. Read
   *  the whole quadrant and those seam vertices leak the neighbour's radius
   *  in: on ONE-C-26's green band (archive, 2026-08-18) the northeast
   *  quadrant's true radius is 80 nm and a whole-quadrant maximum returns 90,
   *  which is the NORTHWEST figure crossing the seam at due north.
   *
   *  45° is the middle half of each 90° quadrant — 22.5° of clearance from
   *  each seam. Inside it the sampled radii are flat to under 0.5 nm across
   *  ~90 vertices, which is the source's own number recovered exactly.
   *
   *  MUST NOT EXCEED 90: wider and the four windows overlap, a vertex lands
   *  in two quadrants, and the seams come back. */
  quadrantWindowDeg: 45,

  /** How close to the published centre a band vertex has to sit, in nautical
   *  miles, before `lib/quadrant-radii.js` reads it as GDACS SAYING ZERO on
   *  that flank rather than as an unreadable shape.
   *
   *  ==> A ZERO QUADRANT IS DRAWN, NOT OMITTED, AND IT COST US THE FIRST HOUR
   *  OF EVERY WIND FIELD. <== `degenerateSpanDeg` above catches the case where
   *  a WHOLE band is zero. This is the other half of the same habit: where one
   *  SIDE of a band reaches nothing, GDACS collapses that sector's vertices
   *  onto the storm's own dot and leaves the other three sectors normal. The
   *  quadrant window then finds nothing, the reader fails closed, and the
   *  entire hour's radii for that threshold are discarded.
   *
   *  MEASURED off `origin/archive:latest/geometry/`, 2026-08-20. SAUDEL-26
   *  lost 34 kt at tau 0, 50 kt at tau 12 and 64 kt at tau 24 — the first
   *  published reading of every threshold — and TWO-C-26 lost 34 kt at taus 9
   *  and 21, a hole through the middle of its most important band. On the home
   *  chart a discarded hour is not a gap, it is a STRAIGHT LINE bridged across
   *  to the next published hour, which drew wind arriving on a slope nobody
   *  forecast.
   *
   *  THE TOLERANCE IS NOT A JUDGEMENT CALL. Those vertices sit at 0.0000 nm
   *  from the dot — GDACS writes the dot's own coordinates — and the nearest
   *  REAL vertex on any of those bands is 10 nm out, because the source rounds
   *  its radii to 5 nm steps. Anything between the two works; 1 nm leaves an
   *  order of magnitude of headroom on both sides. */
  centreCollapseNm: 1,
});

/**
 * Geometry simplification budget.
 *
 * MEASURED, NOT GUESSED: one GDACS storm returned 8,868 coordinates across
 * 44 features, largest single ring 365 points (2026-07-24, live). This is a
 * globe on a phone — that is real weight, and several storms drawn ambient
 * multiply it.
 *
 * Douglas–Peucker tolerance in DEGREES. At these zooms a band's outline is
 * a smooth blob a few degrees across, so a tolerance well under the smallest
 * feature we care about removes redundant vertices without changing the
 * shape a reader sees. The floor exists because simplification that can
 * delete a whole ring reads on glass as MISSING COVERAGE — a §5 failure
 * dressed up as a performance win, and the exact mistake the surge notes
 * warn about.
 */
export const SIMPLIFY = Object.freeze({
  /** Tolerance for GDACS wind bands and cone.
   *
   *  ==> lib/cone-smooth.js READS THIS TOO, for EVERY source's cone. <== It
   *  thins a cone to spline knots before curving it, and using this exact
   *  number is what makes the pass idempotent on the GDACS path — the ring
   *  arrives already simplified at this tolerance, so the second run drops
   *  nothing and the whole visible effect is the curve. A separate cone
   *  tolerance would have been two numbers that had to agree. */
  gdacsToleranceDeg: 0.01,
  /** Never reduce a ring below this many points. Below ~8 a closed blob
   *  stops reading as a blob. */
  minRingPoints: 12,
  /** Rings already at or under this size are left alone — the work costs
   *  more than it saves. */
  skipUnderPoints: 24,
  /** Never reduce an OPEN path below this many points (`simplifyPath`). Lower
   *  than the ring floor on purpose: a two-point path is a legitimate straight
   *  segment, whereas a two-point "ring" is nothing at all. 4 leaves a path
   *  something to curve through after the spline. */
  minPathPoints: 4,
});

/**
 * Closed-ring finishing — shared by the NHC sweep and the GDACS band merge
 * (lib/ringpolish.js). Defaults only; each caller passes its own values
 * where its geometry differs.
 */
export const RING_POLISH = Object.freeze({
  /** Default averaging passes. Matches WIND_SWEEP.ringSmoothPasses so the
   *  two mergers finish with the same visual weight. */
  smoothPasses: 3,
  /** Hard ceiling on resampled vertices. Same reasoning as
   *  WIND_SWEEP.maxSamples: a pathological ring gets a coarser outline
   *  rather than a frame-budget blowout. */
  maxSamples: 2000,

  /** Below this many vertices a ring is passed through unpolished. A shape
   *  with fewer points than this has no corner worth rounding, and a
   *  degenerate one must not be reshaped by a solver with nothing to work
   *  with (GDACS publishes zero-area polygons — SPEC §4). */
  minPolishPoints: 16,

  /** Bearings sampled when smoothing a band's radial seams. 360 = one per
   *  degree, which is finer than any seam needs and costs nothing at three
   *  rings per storm. */
  seamSamples: 360,

  /** Angular width of the seam blend, DEGREES of bearing (half-width either
   *  side of a bearing is windowDeg/2).
   *
   *  THIS IS THE DIAL. The seams are step discontinuities at 90/180/270, and
   *  this is how far either side of one the transition is spread. Too small
   *  and the step survives (the first attempt was effectively ~2°, which is
   *  why nothing changed); too large and a genuinely lopsided storm gets
   *  rounded toward a circle, losing the asymmetry that is real information.
   *
   *  RAISED FROM 24 TO 40 (2026-07-26). At 24 the blend half-width was ±12°,
   *  narrower than the vertex spacing the profile was actually being built
   *  from, so the step reached the screen as a visible shoulder — Aaron:
   *  "I can still see hints of the quadrants." Combined with seamBlurPasses
   *  below, the kernel's effective sigma goes from ~4.6° to ~10.9°. What that
   *  costs and keeps, computed from the Gaussian attenuation of each angular
   *  harmonic: the 90°-period component — the real quadrant asymmetry —
   *  retains ~75% of its amplitude, while the 30°-period component that IS
   *  the hard corner drops to ~7%. The lobes survive; the steps do not. */
  seamWindowDeg: 40,

  /** Blur passes over the radial profile. Repeated raised-cosine converges on
   *  a Gaussian, and that matters for a reason a wider single pass cannot fix:
   *  ONE raised-cosine pass over a step gives a ramp that is smooth in value
   *  and slope but jumps in CURVATURE at each end of the ramp. The eye reads a
   *  curvature jump on a closed outline as a corner even when the outline is
   *  technically smooth — which is what survived at a single pass.
   *
   *  Two passes stay inside the same safety bound as one: each pass is a
   *  convex combination (non-negative weights summing to 1), so the result
   *  still cannot overshoot the published radii. Cost is one extra 360×25
   *  convolution per ring — ~9k multiply-adds, three rings per storm. */
  seamBlurPasses: 2,

  /** UNUSED BY THE BAND PATH — kept for the XY resample, which still serves
   *  lib/windswath.js and lib/bandmerge.js. Bands are smoothed in the ANGULAR
   *  domain instead; see lib/ringpolish.js on why XY cannot touch a radial
   *  seam. Resample spacing for a ring, in DEGREES.
   *
   *  Bands run ~0.5–1.5° in radius, so this puts a few hundred vertices
   *  around one — fine enough that 3-point averaging is a gentle low-pass
   *  rather than a shape change, coarse enough to stay cheap. Matches
   *  BAND_MERGE's grid cell (~1.2 nm of latitude) so the two paths finish at
   *  the same visual weight.
   *
   *  This is the dial if the seams still read hard: LOWER it for a finer
   *  ring, or raise smoothPasses for a rounder one. Passes cost more shape
   *  than spacing does. */
  bandSpacingDeg: 0.02,
});

/**
 * Re-anchoring the forecast to now (lib/forecast-now.js).
 *
 * ==> A FORECAST'S FIRST DOT IS NEVER "NOW". <== It is the ANALYSIS hour, and
 * NHC publishes the analysis hours behind the wall clock: advisory 36A's tau-0
 * is 09Z and the file appeared at 12:02Z. The MapServer then lags CurrentStorms
 * on top of that (SPEC §4, 3¾–6¾ h measured). On 2026-08-21 the two were NINE
 * hours apart — the forecast still starting at 26.9N while the storm feed and
 * the published history both had Lala past 28N.
 *
 * The white ring is drawn on the lowest-tau forecast point (map/layers/
 * points-forecast.js `stampFirst`), so the ring sat 117 miles behind the storm
 * and the history ran up to its own newest fix and then DOUBLED BACK to reach
 * it. Reported on glass by Aaron as the past track overshooting the ring.
 */
export const FORECAST_NOW = Object.freeze({
  /** How long after a forecast hour has passed we still treat it as current.
   *
   *  NOT ZERO, and the reason is the boundary rather than tidiness: a point
   *  and the wall clock landing in the same minute would flip the ring on and
   *  off between two polls. One hour is shorter than the shortest gap between
   *  published taus (12 h), so a grace this size can never keep TWO expired
   *  hours alive, and it is longer than any poll interval, so the decision is
   *  stable across a refresh. */
  expiryGraceMs: 1 * HOUR,

  /** ==> THE CLOCK IS NOT THE ONLY WAY A FORECAST HOUR EXPIRES. <== §7.14.
   *  Nautical miles behind the storm's current position, along its published
   *  heading, before a LEADING forecast hour is dropped as overtaken.
   *
   *  `expiryGraceMs` above catches an hour that has already happened. It cannot
   *  catch an hour that has not happened yet and is already wrong: when the
   *  forecast layers are an advisory older than the position — routine, and
   *  measured at 6 hours on Lala and 28 hours on Moke on 2026-08-22 — a storm
   *  running faster than its own forecast said it would is already PAST the
   *  next forecast hour's position while that hour is still in the future.
   *  Lala at 09:00Z stood 43 nm northwest of where advisory 39 put her at noon.
   *
   *  Shared with `WIND_SWEEP.behindGraceNm` — see `BEHIND_GRACE_NM`. Both doors
   *  onto the same fact must open on the same number. */
  behindGraceNm: BEHIND_GRACE_NM,

  /** Degrees of slack when checking that the forecast LINE starts with the
   *  same coordinates as the forecast POINTS that have expired.
   *
   *  The two layers are published separately and their coordinates carry
   *  ~1e-10 of float noise (measured on the archived bytes: the line's first
   *  vertex and tau-0's position agree to ten decimal places, not exactly).
   *  This is a float-equality tolerance and nothing more — it is deliberately
   *  far smaller than the ~0.1° grid NHC rounds positions to, so it can never
   *  match a genuinely DIFFERENT fix. If the line and the points disagree by
   *  more than this they are describing different advisories, and the whole
   *  re-anchor is abandoned rather than half applied. */
  matchEps: 1e-6,
});

/**
 * Track line construction (lib/trackline.js) — the past and forecast tracks
 * stitched into one continuous curved path through the current position.
 *
 * THERE IS NO MAXIMUM JOIN DISTANCE HERE AND THAT IS DELIBERATE (Aaron,
 * 2026-07-26). A guard would mean the app silently reverted to a broken
 * picture on exactly the days a feed was behind. It always connects; the
 * silence badge is what says the record is old.
 */
export const TRACK_LINE = Object.freeze({
  /** Catmull-Rom knot exponent. 0.5 is CENTRIPETAL, and the value is the
   *  whole safety argument: at 0 (uniform) the curve overshoots and can loop
   *  back on itself where the direction change is sharp — which on a storm
   *  track is a recurve, the one moment somebody is actually watching. At 0.5
   *  cusps and self-intersections are mathematically impossible. Do not tune
   *  this looking for a rounder line; raise it toward 1 (chordal) for a
   *  tighter one, never lower it.
 *
 *  ==> THE CONE OF UNCERTAINTY READS THIS TOO <== (lib/ringpolish.js
 *  `splineClosedRing`, via CONE_CURVE). On a CLOSED ring the overshoot at
 *  alpha 0 is not a cosmetic wobble — a curve that loops back on itself is a
 *  self-intersecting polygon, and MapLibre fills one with a hole punched
 *  through the veil. One number, two shapes, and lowering it breaks both. */
  alpha: 0.5,

  /** Target distance between output vertices, DEGREES in the planar frame
   *  (≈ 5 nm). Length-scaled rather than a fixed count per leg: a fixed count
   *  leaves a long leg visibly faceted at close zoom while spending vertices
   *  it does not need on a short one. */
  spacingDeg: 0.08,

  /** Floor and ceiling on samples per leg. The floor keeps a short leg from
   *  collapsing back to its own chord; the ceiling stops one enormous leg —
   *  the connector across a stale feed's gap — from eating the whole vertex
   *  budget before the rest of the track is drawn. */
  minPerLeg: 4,
  maxPerLeg: 24,

  /** Hard ceiling on vertices in one storm's curve. Same reasoning as
   *  RING_POLISH.maxSamples: a pathological track costs a coarser line, never
   *  the frame budget. A 45-fix past track plus a 7-point forecast lands near
   *  600, so this is roughly double the realistic worst case. */
  maxVertices: 1200,

  /** Two coordinates closer than this are the SAME point — used both to chain
   *  GDACS's abutting segments and to collapse the duplicate where the past
   *  track's last fix and the forecast's first are one position. Degrees;
   *  ~0.1 m, which is far below any published fix precision and far above
   *  float noise in a JSON round trip. */
  joinEpsDeg: 1e-6,

  /** How far, in degrees, the last known position may sit from the end of the
   *  past track before the connecting leg is REFUSED rather than drawn
   *  (lib/trackline.js `extendToAnchor`).
   *
   *  A storm with no forecast left still has a position, and the track has to
   *  reach it or it ends in open water beside a grey X. But the leg is a claim
   *  that the storm travelled it, so it needs a bound: a mismatched storm, a
   *  bad parse or a longitude read on the wrong side of the antimeridian would
   *  otherwise draw a confident line across an ocean nothing crossed.
   *
   *  10° is roughly two days of fast movement, which is far beyond any real gap
   *  — the past track normally ends AT the current fix or one 6-hourly step
   *  behind it, about 2° — and comfortably inside the wrong-hemisphere and
   *  wrong-storm errors it is there to catch. Loose on purpose: the cost of
   *  refusing a real leg is a visible gap, and the cost of drawing a false one
   *  is a fabricated track. §5 says which way to be wrong. */
  anchorMaxDeg: 10,

  /** Smallest gap allowed between spline knots, so a near-duplicate that
   *  survives deduping cannot divide by zero. */
  minKnotGap: 1e-9,

  /** Turn angle, DEGREES, past which an assembled path is treating a
   *  reversal as travel. 0 is straight ahead, 180 is a complete about-face.
   *
   *  THE INVARIANT: a storm does not double back onto its own path between
   *  two consecutive fixes. Storms loop, and a real loop turns thirty or
   *  forty degrees per six-hourly fix — a near-180° turn is never weather, it
   *  is an assembly mistake. 150 leaves the sharpest genuine recurve alone
   *  (measured well under 60°) while catching every fold.
   *
   *  It earned its place on glass: Genevieve's past track drew as a lens,
   *  both arms leaving the current-position dot and closing again at the far
   *  end, because the join had picked the OLD end of her track as the recent
   *  one. Nothing errored — the geometry was simply a journey she never made.
   *  Direction of travel now outranks endpoint distance at the seam. */
  maxTurnDeg: 150,

  /** How many times wider than the CLOSEST available join a corner-free join
   *  may be before `maxTurnDeg`'s veto is overruled (lib/trackline.js `orient`).
   *
   *  THE TURN TEST DECIDES WHICH END OF THE PAST TRACK IS THE RECENT ONE, and
   *  it is right to outrank distance — that is Genevieve, above. But it was an
   *  absolute veto with no way to notice that the orientation it preferred was
   *  absurd. On 2026-08-21 both live NHC storms drew their past track along the
   *  whole forecast and their forecast backwards, because NHC's past track was
   *  two advisories fresher than its forecast geometry: the storm had walked
   *  past its own forecast start, the correct join therefore made a near-180
   *  degree hairpin, and a REVERSED forecast passed the turn test on a gap of
   *  ~11 degrees against the correct answer's ~1.3.
   *
   *  2 is deliberately tight, and the two failures it separates are far apart.
   *  A stale forecast puts the seam one 6-hourly step out — a degree or two —
   *  so the right join is always the near one. A wrong-end or reversed join is
   *  the length of a track, tens of degrees. Nothing real lands between 2x and
   *  8x. Raise it only if a real storm is ever seen losing its corner.
   *
   *  A RATIO OF DISTANCES, and `orient` compares SQUARED separations, so it is
   *  squared at the point of use. */
  orientGapRatio: 2,

  /** Floor on cos(latitude) when scaling longitude into the planar frame.
   *  A tropical cyclone never gets near the pole, but an extratropical
   *  remnant tracking past 80°N would otherwise stretch longitude toward
   *  infinity and take the curve with it. */
  minCosLat: 0.05,
});


/**
 * Cone of uncertainty — the FALLBACK outline curve (lib/ringpolish.js
 * `splineClosedRing`), used only when the sweep in lib/cone-sweep.js refuses.
 *
 * ==> THIS IS NOT THE MAIN PATH, AND THE HISTORY IS WORTH ONE PARAGRAPH SO
 * NOBODY PROMOTES IT BACK. <== It shipped first, as the whole answer, on the
 * reasoning that the cone's facets came from our own Douglas-Peucker pass.
 * That was a third of the truth. MEASURED on samples/gdacs/geometry-TC.json:
 * 16 segments longer than ~55 km carry 81.6% of the published outline's
 * perimeter — four of them 5.2° (≈570 km) of straight edge each — and the
 * breaks between them are mostly under 2°. Those long legs are PUBLISHED, not
 * ours, and an interpolating spline through them returns them unchanged: it
 * decides which way to bend from a vertex's neighbours, and along a 570 km leg
 * every neighbour says "straight". The spline rounded the nose cap, which DP
 * really had faceted, and left 81.6% of the outline exactly as it found it.
 *
 * IT IS STILL WORTH KEEPING as the fallback. When the sweep cannot run — no
 * forecast points, a cone that does not match the track, a recurve tight enough
 * to fold — the alternative is the raw DP'd outline with a four-chord nose, and
 * this is strictly better than that.
 *
 * THE SHAPE CONSTANTS ARE TRACK_LINE'S, ON PURPOSE. `alpha`, `minKnotGap` and
 * `minCosLat` are properties of the curve itself, not of what is being curved.
 * Only the BUDGET is stated here, because a closed ring spends it differently
 * from an open path.
 */
/**
 * Cone of uncertainty — THE SWEPT REBUILD (lib/cone-sweep.js). The main path.
 *
 * A cone is a growing circle slid along the forecast track. The sources publish
 * the circle at day 1, 2, 3, 4 and 5 with straight lines pulled taut between
 * consecutive pairs, and those straight lines are the sampling, not the
 * forecast — the same argument TRACK_LINE already makes about 6-hourly fixes
 * and RING_POLISH already makes about quadrant steps. This rebuilds the sweep.
 *
 * ==> CONTAINMENT IS BY CONSTRUCTION. <== Every boundary point of a union of
 * discs is at least R_i away from centre i, so the SHORTEST distance from a
 * forecast point to the published outline IS that point's own radius —
 * measured, never guessed, and never an underestimate. The smoothed track
 * passes exactly through every forecast point, so the swept shape contains
 * every published disc, so it contains the published cone. It is checked
 * anyway (lib/cone-smooth.js) because a source that publishes something other
 * than a union of discs would break the premise silently.
 *
 * THE RESULT IS ONLY EVER BIGGER. A line pulled around two circles cuts inside
 * the ground the circle actually covers on a curving track, so the published
 * outline slightly under-states the cone and this removes that. Growing a
 * hazard shape is the acceptable direction; shrinking one is a §5 bug.
 */
export const CONE_SWEEP = Object.freeze({
  /** Spacing of the stations the cone is measured and drawn at, DEGREES in the
   *  planar frame (≈6.5 km). The track is resampled to this BEFORE anything is
   *  blurred — see the note in lib/cone-sweep.js on why irregular spacing and a
   *  blur do not mix. Fine enough that the drawn edge reads as a curve, coarse
   *  enough that a whole cone is a few hundred vertices. */
  stepDeg: 0.06,

  /** How far along the track the width blur reaches, DEGREES (≈110 km, so a
   *  window of about 220 km).
   *
   *  THE ONE DIAL THAT DECIDES HOW SMOOTH THE CONE LOOKS. The corners in a
   *  published outline are spaced by one forecast interval — 2.5° or so on the
   *  measured sample — so a window around half of that rounds them off without
   *  flattening the cone's real taper. Raise it for a softer edge, and the cost
   *  is paid in fidelity: the blurred width can sit inside the published one by
   *  up to roughly this much where the outline turns hardest, which is exactly
   *  what `undercutSlack` below is scaled against. */
  blurDeg: 2.5,

  /** Most of the track, as a fraction, that one station's blur window may span.
   *  Keeps a short forecast — a weak storm, or a day-2 cone — from being
   *  smoothed into a sausage by a window longer than the cone itself. */
  maxBlurFrac: 0.25,

  /** Floor and ceiling on vertices in one quarter of an end cap. */
  minCapSteps: 8,
  maxCapSteps: 40,

  /** How far, DEGREES, a measuring ray may travel before it counts as having
   *  escaped. Wider than any published cone; it exists so a ray slipping
   *  through a gap in a malformed ring cannot report a width from the far side
   *  of the basin. */
  maxRayDeg: 12,

  /** Fraction of stations that must see the cone at all. Below this the track
   *  and the cone are not describing the same storm, and a shape assembled from
   *  a handful of readings would be a confident lie. */
  minHitFrac: 0.6,

  /** Step, DEGREES, at which the published outline is WALKED when checking how
   *  far inside it the rebuild sits. Not its vertex list — a tangent leg is two
   *  vertices hundreds of km apart, and checking only those skips the middle of
   *  the leg, which is where a wrong profile shows up. */
  checkStepDeg: 0.25,

  /** How much of the blur window an undercut may consume before the rebuild is
   *  refused, and a small floor for polygon-corner artifacts (≈2 km).
   *
   *  Smoothing a width profile can only pull it in by something on the order of
   *  the window it was smoothed over. Anything deeper is not the blur — it is a
   *  cone that does not belong to this track — and falls back. */
  undercutSlack: 0.5,
  undercutFloorDeg: 0.02,

  /** ==> HOW MUCH OF THE PUBLISHED CONE MUST STILL LIE AHEAD OF THE STORM. <==
   *
   *  The undercut guard above skips published vertices sitting BEHIND the first
   *  station, because §7.11 puts that station on the storm's real position and
   *  a lagged advisory's cone starts where the storm WAS. That skip is right
   *  for a tail and wrong for a whole cone: past some point the advisory is old
   *  enough that its shape says almost nothing about where the storm is going,
   *  and redrawing the sliver that remains would present a fragment as the
   *  whole forecast.
   *
   *  Half. Measured on Lala 2026-08-22, the worst real lag seen so far — nine
   *  hours, apex 135 miles back — left well over 90% of the published outline
   *  still ahead of her. A cone with less than half of itself in front of the
   *  storm is a different situation from anything measured, and falls back to
   *  the published outline, which carries its own age stamp (§4). */
  minAheadFrac: 0.5,

  /** Self-intersection loops one rebuilt cone may have cut out before it is
   *  refused instead. Same guard, same reasoning and the same file as
   *  `WIND_SWEEP.maxLoopCuts` — both are offset curves and both fold the same
   *  way (lib/unloop.js). Kept as a separate number rather than shared because
   *  a cone and a wind corridor have different shapes and there is no reason
   *  their budgets must move together. */
  maxLoopCuts: 8,
});


export const CONE_CURVE = Object.freeze({
  /** Target distance between output vertices, DEGREES in the planar frame.
   *  LOOSER THAN TRACK_LINE.spacingDeg (0.08) and deliberately so: a cone is a
   *  filled veil read at basin scale, not a hairline read at close zoom, and
   *  its legs are far longer than a 6-hourly track leg. At 0.15 the measured
   *  cone comes back at 281 vertices — near the 212 it was published with, and
   *  visually identical to 0.10 at 337. Vertices nobody can see are pure cost
   *  on a phone drawing ten ambient cones. */
  spacingDeg: 0.15,

  /** Floor and ceiling on samples per leg. The floor keeps a short leg from
   *  collapsing back onto its own chord and re-faceting the shape it was
   *  meant to round; the ceiling stops the one enormous leg a badly thinned
   *  ring can contain from eating the budget before the rest is drawn. Both
   *  are lower than TRACK_LINE's — a ring has three to five times as many legs
   *  as a track has, and every one of them is asking for the same purse. */
  minPerLeg: 2,
  maxPerLeg: 16,

  /** Hard ceiling on vertices in ONE ring. Same reasoning as
   *  TRACK_LINE.maxVertices and RING_POLISH.maxSamples: a pathological ring
   *  costs a coarser cone, never the frame budget. The measured cone lands at
   *  281, so this is roughly triple the realistic worst case — and a cone
   *  arrives once per storm, where a wind band arrives seven times. */
  maxVertices: 900,
});


/**
 * THE ENVIRONMENT RIBBON (SPEC §47) — the cone filled by what the environment
 * is worth to the storm, in knots, out of SHIPS's own accounting.
 *
 * Every number here is defined in KNOTS and nothing in this file converts.
 * §8's rule holds without exception in this layer: the ramp domain, the band
 * cut points and the takes-a-side test are all knots, and the reader's units
 * are applied at the moment text is drawn.
 */
export const ENV_RIBBON = Object.freeze({
  /** The contrast the colored forecast line must clear against the ocean.
   *
   *  ==> 3 : 1 IS WCAG'S BAR FOR A GRAPHICAL OBJECT, and it is the same bar the
   *  wind bands are held to, so this is a house number rather than a new one.
   *  It replaces a hand-tuned second ramp (`envRampLine`) that met it at three
   *  fixed stops; the line now takes the CONE's ramp and is lifted only at the
   *  points that fall short, so the two surfaces agree wherever agreement costs
   *  nothing. lib/cone-ribbon.js `liftToLegible`.
   *
   *  RAISING IT PULLS THE HOSTILE END OF THE LINE FURTHER FROM THE CONE'S. The
   *  line can only ever be lifted toward the ramp's bright end, so a higher bar
   *  buys legibility with range — which is the trade the old ramp made
   *  everywhere and this one makes only where it must. */
  lineMinContrast: 3,

  /** The ramp's domain, KNOTS. ±15, and it is measured rather than chosen
   *  (§47.4). Across every hour the ribbon can actually paint the environment
   *  number runs p5 −14, median 0, p95 +10, full range −26 to +38; ±15 holds
   *  94.5% of them, clipping 3.5% dark and 2.0% bright. Widening to ±20 would
   *  capture 98.3% at the cost of flattening the middle, where half the season
   *  lives. DO NOT RE-LITIGATE without a new season's numbers. */
  scaleLoKt: -15,
  scaleHiKt: 15,

  /** ==> WHERE THE RAMP'S FOURTH STOP LANDS, KNOTS (§47.4). <== The measured
   *  domain above is unchanged and is not being re-litigated: -15..+15 still
   *  maps to the same three colours on the same knots. This is the outer knot
   *  of the EXTENSION beyond it, and it only ever affects readings the old ramp
   *  had already flattened.
   *
   *  +40 because the season's measured full range is -26 to +38, so this is the
   *  brightest reading a real file produced with a hair of headroom. Anything
   *  past it clamps, which is the same promise the domain always made — just
   *  made 25 kt further out.
   *
   *  ==> IT IS THE BRIGHT END ONLY, AND THE ASYMMETRY IS THE POINT. <== The
   *  hostile end of both palettes IS the ocean (§47.5), so there is nothing
   *  darker to extend into. See DARK.geo.envRamp. */
  scaleOuterKt: 40,

  /** How much of the ramp the MEASURED domain occupies. The rest is split
   *  EVENLY between the two extensions, which is what puts zero knots in the
   *  middle of the scale.
   *
   *  ==> A HALF, BECAUSE `Balanced` HAS TO BE IN THE MIDDLE (Aaron, 2026-08-22).
   *  <== It was 2/3 with one extension at the bright end only, which put zero
   *  a third along and forced the legend's label row to a lopsided
   *  `1fr auto 2fr`. A key whose midpoint label is not at its midpoint
   *  mis-states its own scale, and it does it silently — every colour on the
   *  bar is still a real ramp colour, just in the wrong place.
   *
   *  ==> THIS NUMBER IS TIED TO THE PALETTE HAVING EXACTLY FIVE STOPS AND
   *  NOTHING ENFORCES THAT BUT A TEST. <== `rampAt` spaces stops evenly, so
   *  five sit at 0, 1/4, 1/2, 3/4 and 1. A half is what puts -15 / 0 / +15 /
   *  +40 back on stops 1 / 2 / 3 / 4 — which is the whole reason every reading
   *  keeps its old colour exactly rather than nearly. Change either without
   *  the other and the middle silently shifts.
   *  `tools/test-cone-ribbon.mjs` asserts both palettes are five long and
   *  re-derives eleven knots against the original three-stop ramp. */
  scaleInnerFraction: 1 / 2,

  /** How long one painted slice is, DEGREES in the same planar frame
   *  CONE_SWEEP.stepDeg uses (≈65 km).
   *
   *  ==> IT IS NOT `stepDeg`, AND THE GAP BETWEEN THEM IS THE WHOLE POINT. <==
   *  The cone is measured every 0.06° because its EDGE has to read as a curve;
   *  the fill's color comes from a number published every six forecast hours,
   *  so a slice per station would be roughly eight hundred polygons per storm
   *  carrying maybe sixteen distinct colors. At 0.6° it is a tenth of that,
   *  and no slice is thin enough for its own color step to be visible.
   *
   *  Slices keep every intermediate station along their edges, so a slice is
   *  flush with the cone it sits in even where the cone turns hardest — the
   *  saving is in the polygon count, never in the shape.
   *
   *  ==> IT WAS 0.6° AND THAT BANDED VISIBLY ON GLASS (2026-08-15). <== Each
   *  slice is one flat color, so the step between neighbours is the whole
   *  color change across 65 km of track — big enough that the eye draws a
   *  line on it, and a cone came out in stripes rather than as a ramp. The
   *  underlying number really is published every six hours, so the stripes
   *  were arguably honest; they still read as a rendering fault rather than as
   *  data, and §47.5 specifies a smooth ramp.
   *
   *  0.2° puts roughly sixty to eighty slices on a five-day cone, a third the
   *  step each. The cone EDGE is already ~800 vertices, so this is not the
   *  expensive thing on the screen. If it still stripes, go to 0.1 rather than
   *  reaching for something cleverer — a fill layer cannot carry a gradient,
   *  so more slices is the only real dial. */
  sliceDeg: 0.2,

  /** Fill opacity for the ribbon, judged on the mockup 2026-08-15. Carried by
   *  the LAYER, never per slice: per-slice alpha paints every shared edge
   *  twice and the cone comes out looking like corduroy (§47.5). */
  fillOpacity: 0.5,

  /** How many storms' runs are fetched at once during a warm pass. SHIPS is a
   *  few KB per storm and the relay serves most of them from KV, so this is
   *  about not opening fifteen sockets on a phone rather than about the
   *  upstream. Same number model guidance uses, for the same reason. */
  warmConcurrency: 4,
});

/**
 * The storm health paragraph (lib/env-health.js) — SPEC §47.8.
 *
 * EVERY THRESHOLD HERE IS IN KNOTS, decided BEFORE unit conversion (§47.4), so
 * a metric reader and an imperial reader get the same verdict, the same named
 * terms, and the same clauses — only the printed figures differ.
 */
export const ENV_HEALTH = Object.freeze({
  /** The band cut points, KNOTS, from §47.4's verified five bands: tearing it
   *  down (< −8), working against it (< −3), neutral (< +3), helping (< +8),
   *  feeding it (≥ +8). The bands drive the WORDS — the shape a verdict names
   *  counts as "turning" only when the track crosses one of these. */
  bandCutsKt: Object.freeze([-8, -3, 3, 8]),

  /** A factor "takes a side" at ±3 kt (§47.8), matching the neutral band. */
  sideKt: 3,

  /** Fewer drawable hours than this and there is no shape to name — the
   *  verdict falls back to the single furthest-from-zero hour (§47.8). */
  minShapeHours: 3,

  /** How many factors may be NAMED with a figure, total across both sides.
   *  Derived from the four §47.8 acceptance cases: each names exactly the top
   *  four non-zero terms by magnitude (ties broken by the parser's key order),
   *  never more, with §47.8's own at-most-three-per-side cap on top. */
  namedTermsMax: 4,
  /** ==> RAISED TO MATCH `namedTermsMax` WHEN THE FIGURES LEFT THE PROSE. <==
   *  Three per side was a READING limit: four signed figures on one side of a
   *  sentence is a wall. §47.8 now prints them as a grid under the paragraph,
   *  where four cells on one side cost nothing to scan, so the only cap that
   *  still earns its keep is the total. Lala is the case: all four of her
   *  non-zero terms are hostile, and the old cap clipped one of them into an
   *  unnamed "smaller term" for no reason a reader could see. */
  namedPerSideMax: 4,

  /** The agreement figures, §47.4. A neutral hour with under `quietKt` of
   *  total push and pull is genuinely quiet (47% of neutral hours); one with
   *  `loudKt` or more is a tug of war (21% — one neutral cone in five). */
  quietKt: 5,
  loudKt: 15,

  /** Texture on the verdict sentence for NON-neutral verdicts: |net| divided
   *  by total activity. At or above `agreeHi` nearly everything is pulling the
   *  same way; at or below `agreeLo` (with both sides at least `sideKt`) the
   *  paragraph says not everything agrees. Between the two it says nothing —
   *  a hedge on every storm would read as filler. */
  agreeHi: 0.8,
  agreeLo: 0.7,

  /** A single term is "almost the entire story" when it carries at least this
   *  fraction of the net; below `dominantLo` (or when the top term is inside
   *  the ±3 side test) nothing dominates and the terms are simply listed. */
  dominantHi: 0.9,
  dominantLo: 0.6,

  /** The room-to-grow sentence branches on current wind over the sea's
   *  ceiling, both at the fix (§47.8): under `roomFarRatio` the storm has
   *  plenty of room; over `roomNearRatio` it is close to its ceiling with
   *  little room left; between the two it has some room.
   *
   *  ==> A JUDGEMENT ABOUT WORDS, NOT A MEASUREMENT. <== The first cut was
   *  0.3/0.7 and it produced a sentence that was plainly false on glass: Lala
   *  at 65 kt under a 136 kt ceiling — 48% — was told she was "fairly close to
   *  her ceiling". Half of a ceiling is not close to it. Half is the honest
   *  boundary for "plenty", and 80% is where "not much left" starts being true
   *  rather than merely cautious. */
  roomFarRatio: 0.5,
  roomNearRatio: 0.8,

  /** A patch whose track finishes on the OPPOSITE side of neutral is told as a
   *  reversal — "then turns against it, reaching −8" — but only when the
   *  ending side clears the ±3 side test by this margin. A finish one knot
   *  over a cut point is a boundary graze and is told as a return to neutral.
   *  Measured on the 2026 corpus: real reversals reach 5–10 kt past neutral;
   *  the grazes sit at 3–4. */
  reversalHysteresisKt: 2,

  /** §47.4: when `V (KT) LAND` and `V (KT) NO LAND` diverge by this much at
   *  any drawable hour, land decay is doing real work and the bottom line
   *  names the coast rather than letting the fall read as the environment's. */
  landGapKt: 10,

  /** On a weakening storm whose fall is at least this many times the
   *  environment's own worst hour, the environment is not the whole story and
   *  the bottom line says the storm's own decay shares the work (§47.8's
   *  "weakening because of the environment" vs "for its own reasons"). */
  decayShareRatio: 2,
});


/**
 * GDACS band merge (lib/bandmerge.js) — stacked per-timestep polygons into
 * one smooth outline per threshold.
 *
 * CONFIRMED ON GLASS 2026-07-24: GDACS bands are QUADRANT-SHAPED, not the
 * symmetric circles the spec inherited from the HA project. Aaron's phone
 * screenshot shows four-lobed shapes with notches where quadrants meet, one
 * stack per forecast timestep, fills compounding at every overlap. Same
 * visual failure the NHC swath was built to fix — different input, so a
 * different merge, but the same finishing pass.
 */
export const BAND_MERGE = Object.freeze({
  /** Occupancy grid resolution, DEGREES per cell.
   *
   *  This is the accuracy/cost dial and the one number to tune if the merged
   *  outline looks lumpy or the merge feels slow. 0.02° ≈ 1.2 nm of latitude
   *  — an order of magnitude finer than the ~100 nm bands being merged, so
   *  the traced boundary is faithful, while a typical storm's span (~10°)
   *  costs a 500×500 grid: 250k cells, trivial for one pass.
   *
   *  The error direction is OUTWARD by up to one cell (a cell fills if any
   *  polygon covers its centre), stated in lib/bandmerge.js as the accepted
   *  trade. This merge traces PUBLISHED POLYGONS; it has no radii to sweep a
   *  corridor from the way lib/windswath.js does on the NHC side. §49.16 does
   *  recover per-timestep quadrant figures from those same polygons, but for
   *  the home corridor's arithmetic — nothing feeds them back into a sweep,
   *  and this cell size is the accuracy dial that remains. */
  cellDeg: 0.02,

  /** Resample spacing for the traced contour, in CELLS. The raw marching-
   *  squares trace is one point per boundary cell, which is far denser than
   *  needed and stair-stepped by construction; resampling at 3 cells feeds
   *  the averaging pass a clean uniform ring. */
  resampleCells: 3,

  /** Averaging passes on the merged outline. Higher than the NHC ring's 3
   *  on purpose: this ring starts as a grid trace, so it carries a
   *  half-cell staircase the sweep's walls never had, and needs more
   *  low-pass to read as smooth. */
  smoothPasses: 6,

  /** Bridge gaps between consecutive band shapes into one corridor.
   *
   *  ON by default and it is the whole reason the merged swath reads as a
   *  swath. GDACS fixes are ~12 h apart, so a band narrower than the
   *  distance travelled merges into beads on a wire (seen on glass
   *  2026-07-24). The storm swept the ground between fixes; the beads were
   *  the artifact. NHC's sweep does the equivalent interpolation between its
   *  own 6-hourly fixes, so this is the same reading applied to a source
   *  that publishes shapes instead of radii.
   *
   *  Set false to see the raw per-timestep footprints — a debugging view,
   *  not a product one. */
  bridgeGaps: true,

  /** Bearings sampled when reducing a published polygon to a radial
   *  profile for blending. 72 = 5° steps, matching WIND_SWEEP.ringSamples
   *  so both mergers resolve a shape at the same angular fidelity. Bands
   *  are smooth quadrant blobs, not spiky, so 5° captures them fully. */
  profileSamples: 72,

  /** Spacing between interpolated bridge shapes, as a FRACTION of the
   *  narrowest radius involved. Two shapes of radius r overlap whenever
   *  their centres are under 2r apart, so 0.5r leaves a wide safety
   *  margin against micro-gaps while adapting to the band's own size —
   *  a wide 60 km/h band takes a few big steps, a tight 120 km/h core
   *  takes more, smaller ones. Self-tuning where a fixed cell count was
   *  not: 4 cells cost 257 ms per storm on realistic input. */
  bridgeStepFraction: 0.5,

  /** Floor on that step, in cells, so a degenerate near-zero radius
   *  cannot drive the step to zero and stamp until the cap. */
  bridgeMinStepCells: 3,

  /** Hard ceiling on interpolated shapes per gap. A pathological jump
   *  between fixes gets a coarser bridge rather than a stall. */
  maxBridgeSteps: 200,

  /** Contours shorter than this many cells are noise — a stray filled cell
   *  from a sliver of polygon — not a band. Dropped. */
  minContourCells: 12,

  /** A merged ring below this many points is not a legible shape; dropped
   *  rather than drawn as a triangle. */
  minRingPoints: 12,

  /** Hard ceiling on grid cells. Past this the merge BAILS and the caller
   *  keeps the unmerged stack — uglier but bounded. Guards against a
   *  pathological span or an outlier vertex allocating a huge grid on a
   *  phone. 4M cells ≈ 4 MB, the most worth spending on one storm. */
  maxCells: 4_000_000,
});

/* ---------------------------------------------------------------------------
 * MODEL GUIDANCE TRACKS (§14 Phase 6 step 5) — the "spaghetti" layer.
 *
 * Several forecast models are run for every storm and they DISAGREE. NHC's
 * official cone is a judgement made after weighing them; this layer shows the
 * raw spread behind that judgement. A tight cluster means confidence, a wide
 * fan means nobody knows — and that distinction is invisible from the cone
 * alone, which draws the same confident shape either way.
 *
 * SOURCE: the ATCF a-deck, one gzipped file per storm, fetched through the
 * relay (`ENDPOINT.nhcAdeck` is CORS-blocked — §4). NHC-ONLY, permanently:
 * GDACS aggregates official advisories and publishes no model guidance at
 * all, so that is §14's standing exception rather than an open task.
 *
 * THE SHORTLIST IS INHERITED AND PROVEN, verified against a live deck
 * (`aep012026`, 2026-07) on the HA project. Re-deriving it here would have
 * cost a day to land in the same place. Two name traps it records: GFS is
 * `AVNO`, NOT `GFSO`; UKMET is `UKX`, NOT `EGRR`.
 *
 * TWO MODELS ARE EXCLUDED ON PURPOSE, and both exclusions are load-bearing:
 *  - `EMXI` (ECMWF) is access-restricted in public decks — its rows arrive
 *    BLANK. Wiring it would ship a model that silently draws nothing, which
 *    is §5's failure wearing a checkbox.
 *  - `OFCL` IS the official forecast track, already drawn as the solid line.
 *    A dashed overlay on top of it is invisible and redundant in the legend.
 * ------------------------------------------------------------------------- */

/**
 * Selector groups. These still set the ORDER models appear in — consensus
 * first, then the globals, then the hurricane-specific models — and they still
 * separate the rows visually.
 *
 * THE HEADINGS ARE GONE (2026-07-25). §7 asked for grouping "never one flat
 * column of checkboxes", and the grouping delivers that on its own: five rows
 * in three clusters reads as three kinds of thing without three uppercase
 * labels stacked over it. Each row already carries its own second line saying
 * what the model is, so the heading was a third level of type over a control
 * that fits on half a phone screen. `MODEL_GROUP_LABEL` retired with them —
 * a label constant nothing renders is a constant that quietly goes stale.
 */
export const MODEL_GROUP = Object.freeze({
  CONSENSUS: 'consensus',
  GLOBAL: 'global',
  HURRICANE: 'hurricane',
  /** One centre's ensemble, averaged. Non-NHC basins publish nothing else. */
  ENSEMBLE: 'ensemble',
});

/**
 * Which SOURCE a model's deck comes from, and therefore which storms it can
 * ever apply to.
 *
 * NOT a cosmetic grouping — it decides which relay is asked and which rows the
 * picker shows. The two families share NO model codes at all: a West Pacific
 * deck was read on 2026-07-26 and carried none of TVCN/HCCA/AVNO/UKX/HFSA.
 */
export const MODEL_FAMILY = Object.freeze({
  /** NOAA's public a-decks. Atlantic, East and Central Pacific. */
  NHC: 'nhc',
  /** UCAR's TCGP. West Pacific, North Indian, Southern Hemisphere. */
  GLOBAL: 'global',
});

export const MODEL_TRACKS = Object.freeze({
  /**
   * The shortlist, in render and selector order.
   *
   * `tech` is the ATCF code as it appears in column 4 of the deck. `label` is
   * what a human is shown — the UI never prints a tech code, because "AVNO"
   * means nothing and "GFS" means something.
   *
   * TVCN AND HCCA SHARE ONE SLOT AND ONE COLOR. Both are consensus aids;
   * TVCN is preferred and HCCA fills in only when TVCN is absent from the
   * deck, so the two are never drawn together. They share `pref` for the same
   * reason: a user who switched "Consensus" off must not have it come back
   * under a different name when TVCN drops out of a cycle.
   *
   * `sub` is the second line in the selector. EVERY FIGURE IN IT IS FROM
   * NHC's own model table (`nhc.noaa.gov/modelsummary.shtml`, read
   * 2026-07-25), not from recollection: GFS runs 00/06/12/18 UTC out to
   * 240 h, UKMET runs 00/12 only, out to 144 h. **If those cadences change,
   * this copy is wrong on screen and nothing will fail** — it is prose, and
   * prose has no test. Re-read the table before trusting it in a season
   * where the models have been upgraded.
   *
   * Consensus is the only row making an accuracy claim, and it is the only
   * one that can safely make one: "the best models were the consensus aids"
   * is NHC's own verification finding and has held for two decades.
   */
  techs: Object.freeze([
    Object.freeze({
      tech: 'TVCN', label: 'Consensus', pref: 'consensus', group: MODEL_GROUP.CONSENSUS,
      family: MODEL_FAMILY.NHC,
      sub: 'Blend of all models — usually the most accurate',
    }),
    Object.freeze({
      tech: 'HCCA', label: 'Consensus', pref: 'consensus', group: MODEL_GROUP.CONSENSUS,
      family: MODEL_FAMILY.NHC,
      sub: 'Blend of all models — usually the most accurate',
    }),
    Object.freeze({
      tech: 'AVNO', label: 'GFS', pref: 'avno', group: MODEL_GROUP.GLOBAL,
      family: MODEL_FAMILY.NHC,
      sub: 'Updated 4× a day · longest range',
    }),
    Object.freeze({
      tech: 'UKX', label: 'UKMET', pref: 'ukx', group: MODEL_GROUP.GLOBAL,
      family: MODEL_FAMILY.NHC,
      sub: 'Updated 2× a day · ends at 6 days',
    }),
    Object.freeze({
      tech: 'HFSA', label: 'HAFS-A', pref: 'hfsa', group: MODEL_GROUP.HURRICANE,
      family: MODEL_FAMILY.NHC,
      /* AMPERSAND, not "and": the spelled-out version wraps to a second line
       * in the 340px rail, and a two-line subtitle under a one-line name makes
       * the row taller than every other row in the selector. */
      sub: 'Hurricane Analysis & Forecast System (US)',
    }),

    /* --- UCAR TCGP, for the basins NOAA does not publish (§15) -------------
     *
     * THREE CENTRES, EACH ONE'S OWN PUBLISHED AVERAGE OF ITS OWN ENSEMBLE.
     * The `*EMN` codes are produced by the modelling centres themselves —
     * we do not average the members, because that would be a second answer to
     * a question the source has already answered.
     *
     * MEMBER COUNTS ARE MEASURED, not recalled: a live West Pacific deck on
     * 2026-07-26 carried AP01..AP30 (30), NP01..NP20 (20) and CP01..CP20 (20).
     * If a centre resizes its ensemble this copy is wrong on screen and
     * nothing will fail — it is prose, and prose has no test.
     *
     * LABELS ARE THE ABBREVIATIONS (Aaron, 2026-07-26). "GEFS" over
     * "American": the app names agencies elsewhere and these are the names
     * the model plots everywhere else use.
     *
     * NO ACCURACY CLAIM ON ANY OF THESE ROWS. Consensus earns one in the NHC
     * set because NHC publishes verification showing it. No equivalent
     * ranking was found for these three, and inventing one from reputation is
     * exactly the thing this project has a rule against.
     */
    Object.freeze({
      tech: 'AEMN', label: 'GEFS', pref: 'aemn', group: MODEL_GROUP.ENSEMBLE,
      family: MODEL_FAMILY.GLOBAL,
      sub: 'Average of 30 forecast runs (US)',
    }),
    Object.freeze({
      tech: 'NEMN', label: 'NAVGEM', pref: 'nemn', group: MODEL_GROUP.ENSEMBLE,
      family: MODEL_FAMILY.GLOBAL,
      sub: 'Average of 20 forecast runs (US Navy)',
    }),
    Object.freeze({
      tech: 'CEMN', label: 'GEPS', pref: 'cemn', group: MODEL_GROUP.ENSEMBLE,
      family: MODEL_FAMILY.GLOBAL,
      sub: 'Average of 20 forecast runs (Canada)',
    }),
  ]),

  /** Forecast hours past this are noise — guidance seven days out disagrees
   *  with itself more than it disagrees with the other models. */
  maxTau: 168,

  /** Per-model point cap. Taus run 6–12 h apart, so 32 covers the whole
   *  window with room to spare; the cap exists to bound a malformed deck,
   *  not to trim a healthy one. */
  maxPoints: 32,

  /**
   * A model's own latest cycle must be within this many hours of the DECK's
   * newest cycle, or the model is dropped.
   *
   * Two rules in one number. Raw models lag the official forecast by a cycle,
   * so taking each tech's OWN latest cycle (rather than one shared cycle) is
   * what keeps them on the map at all. But a model that stopped running
   * entirely must not keep drawing a days-old track that looks exactly as
   * current as the others — a stale line among fresh ones is a confident lie
   * about where a storm might go (§5).
   */
  staleHours: 12,

  /** Below this many points a "track" is a stub, not guidance. Dropped
   *  rather than drawn as a two-pixel stub the user cannot interpret. */
  minPoints: 2,

  /**
   * How many storms' decks are fetched at once while warming.
   *
   * ONE, not the geometry warmer's two. Decks are an order of magnitude
   * bigger than a MapServer bundle even after the relay's filter, and this
   * rides the same phone radio as the basemap tiles and the storm feed. The
   * layer is warm-ahead detail nobody is waiting on, so it should be the
   * politest thing on the connection, not a competitor.
   */
  warmConcurrency: 1,
});

/* ---------------------------------------------------------------------------
 * ADVISORY TEXT — Phase 6 step 6 (SPEC §16 item 7)
 *
 * The words a forecaster actually wrote, in the storm drawer. It is NOT a map
 * layer and has no toggle: a layer is something drawn on the globe, this is
 * prose, and it is inherently per-storm — there is no advisory without a
 * selected storm. The collapsed section IS the fetch gate, which is a better
 * one than a global switch because it is per storm and on demand.
 * ------------------------------------------------------------------------ */

export const ADVISORY_TEXT = Object.freeze({
  /**
   * Which NHC product the panel shows.
   *
   * TCP — the Public Advisory. Plain language, and the only one of the three
   * written for a person rather than a machine: TCM is the coded forecast
   * advisory (fixed-column wind radii), and TCD is the forecaster discussion,
   * which is the most interesting read in the whole app and also the most
   * technical. Both are one constant away; neither is the default.
   */
  kind: 'TCP',

  /**
   * How many storms' advisories are held in memory. Matches the geometry
   * cache for the same reason: the NHC basins have peaked at eight or nine
   * concurrent storms, and a cap below that evicts a storm the user is still
   * moving between. Bound every cache (§4).
   */
  lruStorms: 12,

  /**
   * How long the JTWC name index is trusted before it is re-fetched.
   *
   * Longer than the relay's own 15-minute window on purpose — this is the
   * CLIENT's copy, and its job is to keep a second storm selection from
   * costing a round trip at all. A new storm appearing in JTWC's list inside
   * this window shows as `none_matched`, which reads honestly ("JTWC has no
   * warning under that name") rather than as an error. Re-opening the section
   * is the recovery, same as everywhere else.
   */
  indexTtl: 15 * MINUTE,
});

/* ---------------------------------------------------------------------------
 * IMAGERY (SPEC §4, §7) — satellite discs around each storm's eye
 *
 * EVERY NUMBER AND EVERY URL BELOW WAS MEASURED, not inherited. The probe that
 * produced them ran from the deployed site on 2026-07-25 (tools/imagery-probe
 * plus /api/imagery/inspect) because the sandbox cannot reach any of these
 * hosts. Where a value came from a measurement, the measurement is stated.
 * ------------------------------------------------------------------------- */

/**
 * NO TIME PARAMETER IS EVER SENT. This is the single most load-bearing line in
 * the imagery code and it is a MEASURED result, not a preference.
 *
 * Asking GIBS for a specific timestamp hits empty frames unpredictably: on one
 * afternoon's ladder GOES-East returned a blank 512x512 at 0 and 20 minutes
 * back, GOES-West at 60 and 120, Himawari at 0 — while every request that sent
 * NO time at all returned real imagery on all three satellites. The server
 * knows which frame is its newest complete one and we do not.
 *
 * So Landfall carries no per-satellite lag constant. There is nothing to tune
 * and nothing to go stale. If playback lands in v2.0 it will need explicit
 * times and will have to solve this properly — the time dimension IS
 * advertised (measured), it is just not safe to guess a value from.
 */
export const IMAGERY_SENDS_NO_TIME = true;

/**
 * The satellite ring. Four birds, two vendors, the whole tropical belt.
 *
 * THE `black`/`white` GREY ANCHORS ARE GONE. They existed only to normalize
 * brightness onto a shared coldness scale, and that whole approach was retired
 * with the color knockout (see IMAGERY below) — nothing reads them now, so
 * they are deleted rather than left as dead config. The measurements they held
 * (GOES 13..250, Himawari 8..226, Meteosat 9..218) are re-derivable from
 * tools/imagery-probe.html if a brightness path is ever needed again.
 *
 * `lonMin`/`lonMax` are the longitudes each satellite OWNS, not the extent it
 * can technically see — the discs overlap heavily and the boundaries are
 * chosen where the picture is best, which is measured:
 *
 *  - The dateline handoff is FREE. GOES-West and Himawari both returned real
 *    imagery for a box straddling 180 degrees, so 180 is picked because it is
 *    the obvious number, not because either satellite runs out there.
 *  - The eastern Indian Ocean handoff is NOT free. Himawari at 95-105E came
 *    back washed out (luminance 95..141, a narrow band near its horizon) where
 *    Meteosat IODC over the same box was clean. IODC owns it.
 */
export const SATELLITES = Object.freeze([
  Object.freeze({
    id: 'goes-east',
    label: 'GOES-East',
    vendor: 'NASA GIBS',
    /* ABI band 13, "clean longwave infrared", 10.3 microns. */
    layer: 'GOES-East_ABI_Band13_Clean_Infrared',
    endpoint: 'https://gibs.earthdata.nasa.gov/wms/epsg3857/best/wms.cgi',
    wms: '1.1.1',
    /* CONFIRMED ON GLASS 2026-07-25: vivid thermal color. */
    enhanced: true,
    lonMin: -105,
    lonMax: -30,
  }),
  Object.freeze({
    id: 'goes-west',
    label: 'GOES-West',
    vendor: 'NASA GIBS',
    layer: 'GOES-West_ABI_Band13_Clean_Infrared',
    endpoint: 'https://gibs.earthdata.nasa.gov/wms/epsg3857/best/wms.cgi',
    wms: '1.1.1',
    /* CONFIRMED ON GLASS 2026-07-25: vivid thermal color. */
    enhanced: true,
    lonMin: -180,
    lonMax: -105,
  }),
  Object.freeze({
    id: 'himawari',
    label: 'Himawari',
    vendor: 'NASA GIBS',
    /* AHI band 13 — the same 10.4 micron channel as ABI band 13. Choosing the
     * matching channel on every satellite is what makes one palette honest. */
    layer: 'Himawari_AHI_Band13_Clean_Infrared',
    endpoint: 'https://gibs.earthdata.nasa.gov/wms/epsg3857/best/wms.cgi',
    wms: '1.1.1',
    /* CONFIRMED ON GLASS 2026-07-25: vivid thermal color. */
    enhanced: true,
    lonMin: 105,
    lonMax: 180,
  }),
  Object.freeze({
    id: 'meteosat-iodc',
    label: 'Meteosat IODC',
    vendor: 'EUMETSAT',
    /* SEVIRI IR 10.8 — same physical channel again.
     *
     * THE ONLY BIRD WHOSE COLOR IS STILL UNVERIFIED. A 2026-07-25 probe
     * reported this layer as pure grey (mean saturation 0.00, max 0.00), and
     * that same probe run also called the three GIBS layers mostly grey —
     * which is FLATLY WRONG, confirmed on glass 2026-07-25 with vivid thermal
     * color on GOES-West (Genevieve, Fausto) and Himawari (NOUL-26). So the
     * grey reading here is not evidence of anything; it is a run that got the
     * other three wrong. Look at an Indian Ocean or east-Atlantic storm and
     * read the `[landfall] imagery meteosat-iodc chromaMax=` line before
     * believing either answer. If it really is grey, the knockout keys to
     * nothing and map/imagery.js says so by name. */
    layer: 'msg_iodc:ir108',
    endpoint: 'https://view.eumetsat.int/geoserver/ows',
    wms: '1.3.0',
    /* CONFIRMED ON GLASS 2026-07-25 by Aaron, after test storms were dropped
     * across the whole IODC footprint: this product is PLAIN GREY. It takes the
     * brightness knockout instead of the chroma one, and `black`/`white` below
     * are the anchors that path normalizes against.
     *
     * The one earlier probe that said the same thing also called the three GIBS
     * birds grey, which is flatly wrong — so this is believed because it was
     * SEEN, not because that probe agreed. lib/imagery-paint.js re-checks the
     * claim on every frame and warns if a frame contradicts it. */
    enhanced: false,

    /* Grey range for the brightness path, 0..255. Deleted along with the old
     * coldness scale and brought back deliberately: ONE bird, ONE path, and it
     * genuinely needs them. The values are the earlier probe's (9..218) and are
     * therefore a STARTING POINT, not a measurement to trust — the pass logs
     * this frame's own 2nd and 98th luma percentiles so they can be corrected
     * from a real cyclone. */
    black: 9,
    white: 218,
    lonMin: -30,
    lonMax: 105,
  }),
]);

/** Extracted so `maxDiscs` and the frame cache's cap can both name it — the
 *  cache holds two frames per disc, and writing 24 as a literal beside a 12
 *  would be a relationship nobody could see. */
const MAX_DISCS = 12;

export const IMAGERY = Object.freeze({
  /**
   * Radius of the disc drawn around each eye.
   *
   * 900, up from 600, and the reason is on glass: with the color knockout
   * doing the work, a major hurricane's shield RAN OUT OF DISC. Genevieve and
   * Fausto both reached the rim and got cut, which is the one thing the
   * feather cannot hide — it fades an edge, it cannot invent the cloud past it.
   * 600 km was sized for a knockout that erased most of the frame anyway.
   *
   * The ceiling is storms drawing into each other: two discs closer than
   * 1800 km apart now overlap, and the overlap composites to a slightly hotter
   * patch. Feathered rims blend rather than seam, so it reads as weather, but
   * this is the number that decides it.
   */
  discRadiusKm: 900,

  /**
   * Pixels per side requested per storm.
   *
   * DERIVED, not picked, and it moves with the radius: an 1800 km box across
   * 768 px is 2.3 km per pixel — the same sampling as the old 1200/512, and
   * ABI/AHI band 13 is a 2 km channel at nadir. Holding the ratio is what
   * keeps a bigger disc from being a blurrier one.
   *
   * Cost is real and worth stating: 768² is 2.25x the pixels and roughly
   * 2.25x the bytes of 512², per storm, per five-minute refresh. Asking for
   * more than this would upscale noise for battery.
   */
  requestPx: 768,

  /**
   * Where the feather starts, as a fraction of the disc radius. Inside this
   * the image is fully opaque; from here to the rim it falls to nothing.
   * A hard rim reads as a sticker on the globe — the whole reason this is a
   * disc and not a rectangle.
   *
   * STORED AS THE FADE WIDTH, not as where the fade starts, and that is on
   * purpose: it is the number the Settings slider shows and the number a person
   * thinks in ("how soft is the edge"). The geometry wants the opposite end, so
   * `lib/imagery-paint.js` computes `featherStart = 1 - fadeWidth` at the one
   * place that needs it. ONE name for one idea; two would drift.
   *
   * 0.38 at a 900 km radius is a 342 km blur. It was 0.42 (378 km) until
   * 2026-07-25; the slightly harder edge keeps a little more of the outer
   * bands, which is what the note under the slider warns a wide fade eats.
   *
   * THIS IS THE DEFAULT, NOT THE VALUE. Settings overrides it per device
   * (`imageryFade` in data/settings-prefs.js); this is what a fresh install
   * gets and what Reset returns to.
   */
  fadeWidth: 0.38,

  /**
   * Bounds for the two Settings sliders (SPEC §16). Here rather than in the
   * view because they are behavioural limits, not styling — the same rule that
   * puts poll intervals and zoom thresholds in this file.
   *
   * The ceilings are not arbitrary. 1500 km of radius is a 3000 km box, at
   * which point a "disc on a storm" has become a repainted ocean and discs
   * overlap almost everywhere. A 0.70 fade eats deep into any real cloud
   * shield. Both ends are reachable so the shape can be seen, but the useful
   * range lives nearer the defaults.
   */
  tuning: Object.freeze({
    radiusKm: Object.freeze({ min: 300, max: 1500, step: 50 }),
    fade: Object.freeze({ min: 0.05, max: 0.7, step: 0.01 }),

    /**
     * How long the sliders must sit still before the map acts on them, in ms.
     *
     * The controls fire on `input` so the readout tracks the thumb, which
     * means one drag emits dozens of changes. Acting on each would repaint
     * twelve discs per pixel of travel, or worse, refetch them from NASA.
     *
     * 180 ms is under the ~250 ms where a delay starts reading as lag, and
     * long enough that a normal drag settles exactly once.
     */
    settleMs: 180,
  }),

  /* --- THE COLOR KNOCKOUT ---------------------------------------------------
   * Ported verbatim from the HA integration's `#extract-clouds` SVG filter,
   * values and all. A color-enhanced infrared product draws cold storm tops in
   * VIVID COLOR and warm ground, low cloud and clear sky in GREY, so the key
   * is SATURATION and the vendor's own RGB survives untouched.
   *
   * These four replaced `clearBelow` / `solidAbove` / `colorSat` /
   * `coloredFloor` and the normalized-coldness scale they belonged to. That
   * approach repainted every pixel from a palette of ours and produced a white
   * and blue smear where the HA card, on the same weather at the same minute,
   * produced a red/yellow/green storm. Aaron shot the pair side by side.
   *
   * THEY WERE TUNED AGAINST IEM'S `conus_ch13` PALETTE, NOT OURS. The edge and
   * purple fades in particular exist because that specific enhancement renders
   * its cold edge blue/purple. Our vendors may enhance differently, so treat
   * all four as starting points, not settled values.
   * ------------------------------------------------------------------------ */

  /**
   * Sharpness of the color cutoff. Higher means a colored pixel ramps to
   * full opacity faster once past the cutoff (crisper edge); lower is a softer
   * fade. Alpha before the fades is `satSlope * chroma + satIntercept`.
   */
  satSlope: 4,

  /**
   * Where the cutoff sits, as `-satIntercept / satSlope` of full chroma —
   * 0.125 at these values. MORE NEGATIVE means a higher cutoff, so more grey
   * and more faintly-tinted pixels are removed.
   *
   * This is the first dial to reach for if the discs keep too much haze (more
   * negative) or eat the storm's outer bands (less negative).
   */
  satIntercept: -0.5,

  /**
   * Cold-edge fade. Scales alpha by `1 - edgeFade * blue`, so the enhancement's
   * blue/purple outer band drops back while the green/yellow/orange/red cores
   * stay full. 0 turns it off. MULTIPLICATIVE — it can only ever remove
   * opacity, never add it.
   */
  edgeFade: 0.5,

  /**
   * Purple-only fade, stacked on top of `edgeFade`. Scales alpha by
   * `1 - purpleFade * red * blue`; `red * blue` is a magenta detector, since
   * purple is the one band with both channels high. Pure blue and the red and
   * orange cores are untouched. 0 turns it off.
   */
  purpleFade: 0.5,

  /* --- THE BRIGHTNESS KNOCKOUT (greyscale vendors) --------------------------
   * Same shape as the color knockout above, different signal: `t` is the
   * pixel's brightness normalized against that vendor's black/white anchors,
   * where 0 is the warmest thing it renders and 1 the coldest. In every IR
   * product brighter means colder means higher tops means the storm.
   *
   * DERIVED FROM WHERE OCEAN ENDS AND CLOUD BEGINS, not picked. Tropical ocean
   * on infrared sits around raw 26..61 against Meteosat's 9..218 range — t of
   * roughly 0.08 to 0.25 — and cloud starts climbing near raw 79..96, t of
   * about 0.33. So the floor belongs just above the ocean at t = 0.30, reaching
   * solid by t = 0.55. Those two points give slope 4 and intercept -1.2.
   *
   * Slope 4 matching the color path's `satSlope` is a coincidence, but a
   * convenient one: both keys ramp equally hard once past their floor.
   *
   * FIRST DIAL if Meteosat looks wrong: `greyIntercept`. More negative lifts
   * the floor and strips more low cloud; less negative keeps more haze. Check
   * the logged `luma=` range first, though — a floor tuned against wrong
   * anchors is tuning the wrong number.
   * ------------------------------------------------------------------------ */
  greySlope: 4,
  greyIntercept: -1.2,

  /**
   * Below this fraction of the disc surviving, a frame has NOTHING TO DRAW and
   * the disc is hidden rather than painted.
   *
   * ==> IT REPLACES A BARE `0.005` THAT ONLY EVER RAN ON SATELLITE. <==
   *
   * The radar path never measured anything at all: `keptFraction` was
   * initialised to 1 and only the satellite branch overwrote it, so
   * `rec.empty` was mathematically unreachable for radar. A completely blank
   * radar frame therefore drew a fully transparent raster over a live
   * hurricane and the row said NOTHING — §5's silence-on-failure, and the
   * exact "blank raster reads as clear sky" failure the file warns about three
   * separate times elsewhere.
   *
   * MEASURED 2026-07-26 through the deployed relay, one 900 km disc per point,
   * counting non-transparent pixels inside the rim:
   *
   *   0.00%  Genevieve (12.9N 108.3W) and Fausto (19.7N 139.8W), open Pacific
   *          — both returned a 334-byte PNG, which is the empty signature
   *   0.06%  mid-Atlantic 25N 60W
   *   0.08%  San Juan
   *   0.58%  Anchorage
   *   2.20%  ~100 nm off Louisiana
   *   2.55%  100 nm off Cape Hatteras
   *   3.66%  Miami, over land
   *
   * 0.002 sits in the wide gap between the near-empty cluster and the first
   * real echo, with margin on both sides. THE OLD 0.005 WOULD NOT HAVE DONE:
   * it is close enough to Anchorage's 0.58% to be uncomfortable, and that is a
   * real radar picture of a real city.
   *
   * Satellite is nowhere near either number — the same day measured Fausto at
   * 4.85% and Genevieve at 36.8% kept — so one constant serves both paths, and
   * one constant is right: the question ("did the pass keep anything worth
   * drawing") is identical whichever knockout asked it.
   */
  emptyKeptFraction: 0.002,

  /**
   * Below this peak chroma, a frame is GREYSCALE and the knockout above cannot
   * work on it — every pixel keys to zero and the disc renders as nothing.
   *
   * This is a SAFETY CONSTANT, not a look constant. An empty disc over a live
   * cyclone reads as clear sky, which §5 forbids, so the caller turns this into
   * a named fault instead. A 2026-07-25 probe reported EUMETSAT's `ir108` at
   * exactly 0.00 max saturation; whether that still holds is what the pass now
   * measures and reports rather than assumes.
   */
  greyscaleChroma: 0.02,

  /** Ceiling on how many storm discs are held at once. Bound every cache
   *  (§7). Matches the geometry and advisory LRUs for the same reason: the
   *  basins have peaked at eight or nine storms at once. */
  maxDiscs: MAX_DISCS,

  /* --- THE FRAME CACHE -------------------------------------------------------
   * Added 2026-07-26 after Aaron noticed identical frames being re-downloaded
   * on every toggle. He was right, and the measurements are worse than the
   * symptom suggested. From the deployed site, same minute:
   *
   *   GIBS sends `Cache-Control: max-age=0, no-store, no-cache,
   *   must-revalidate` plus `Expires: Thu, 1 Jan 1970` plus `Pragma: no-cache`.
   *   A triple-belt refusal — the browser cannot help even in principle.
   *
   *   Four identical back-to-back fetches of one disc: 2523 ms, 11785 ms,
   *   30728 ms, 779 ms. The full 826 KB every time. THIRTY SECONDS on one of
   *   four, which is what a first look at a hurricane can cost.
   *
   *   Two of those four returned 826100 bytes and two returned 826635 — GIBS
   *   serves DIFFERENT frames on consecutive requests, so a fresh fetch can
   *   legitimately hand back an older frame than the one already on screen.
   *   That is an argument for caching, not against it.
   *
   * Radar was already fine, and the asymmetry is why it felt instant: it goes
   * through our own relay, which sets max-age=300, and the browser served the
   * repeat in 3 ms with zero bytes transferred. Satellite now takes the same
   * road (functions/api/imagery/satellite.js), so these numbers are the client
   * layer on top of an edge cache rather than the only defence.
   *
   * THE AGE WE REPORT IS DOWNLOAD TIME, NOT FRAME TIME, and the wording on the
   * row says "Downloaded". We send no TIME parameter (see
   * IMAGERY_SENDS_NO_TIME) so the vendor never tells us when the picture was
   * taken, and cross-origin CORS would not let us read `Date` or `Age` even if
   * it did. Claiming otherwise would be a §5 confident-wrong-answer.
   * ------------------------------------------------------------------------ */
  cache: Object.freeze({
    /**
     * Younger than this, a cached frame IS what a fresh fetch would return —
     * so it is served with no refetch and no age note. DERIVED FROM THE POLL
     * CADENCE, not hand-set: the timer already owns how often frames are
     * replaced, and a second independent number would drift from it.
     */
    currentFor: POLL.imagery,

    /**
     * Older than this, a cached frame is treated as ABSENT: the disc shows
     * loading and waits for real bytes.
     *
     * §5 says stale data plus a visible timestamp beats a blank screen, always
     * — which is why there is no threshold between `currentFor` and here. A
     * twenty-minute-old frame is served instantly, labelled, while the new one
     * downloads. This is the outer bound where "labelled" stops being enough:
     * an hour-old frame is not a picture of the current sky.
     *
     * THE COST OF STALENESS HERE IS NOT POSITION. A storm at 13 kt moves about
     * 12 km in half an hour against a 900 km disc radius — invisible. What
     * changes on that scale is what the CLOUD is doing: convective bursts,
     * eyewall cycles, rapid intensification. That is the thing an old frame
     * misreports, and it is why this is measured in minutes and not hours.
     */
    maxServeAge: 60 * MINUTE,

    /**
     * Frames held at once. Bound every cache (§7). Two per storm, because a
     * user toggling satellite/radar wants BOTH sides to come back instantly —
     * holding one would make every toggle a miss and rebuild the exact problem
     * this cache exists to fix.
     *
     * Compressed PNGs, not decoded buffers: measured 477 KB (quiet frame) to
     * 826 KB (Genevieve at 36.8% kept), so the ceiling is roughly 20 MB. The
     * device reported a 10.7 GB quota against 4.4 MB in use, so this is not
     * close to a constraint — the cap is here to bound a leak, not a budget.
     */
    maxFrames: MAX_DISCS * 2,
  }),

  /** Satellite, which now takes the same road radar always did. See the cache
   *  note above for the measurements that put it there — the short version is
   *  that GIBS forbids caching outright and answers between 0.8 and 30.7
   *  seconds, and behind our own route we own both of those facts. */
  satellite: Object.freeze({
    relay: '/api/imagery/satellite',
  }),

  /**
   * Radar — RAINVIEWER, a global composite of 1200+ radars across 150+
   * countries, drawn as a TILE LAYER rather than a per-storm disc (§4.9).
   *
   * ==> IT IS THE ONE IMAGERY LAYER THAT IS NOT A DISC, AND THAT ASYMMETRY IS
   * THE SERVICE'S RATHER THAN A COMPROMISE. <== Satellite comes from a WMS: ask
   * for a rectangle, get one picture, so a disc around the eye is the natural
   * shape and 768 px across 1800 km is a real 2.3 km/px. RainViewer is a tile
   * pyramid. Asking it for one picture caps the pixel budget at 512 no matter
   * how big the area, so a wider view is a blurrier one — at the radius
   * slider's maximum that was 8.5 km/px, seven times coarser than RainViewer's
   * own site at the same zoom. Served as tiles, MapLibre asks for exactly what
   * the viewport needs at the zoom it is drawing, and the blur is gone.
   *
   * WHAT THAT COSTS, RECORDED SO NOBODY REDISCOVERS IT: radar no longer obeys
   * the Cloud radius or fade sliders, because it has no disc and no rim. Those
   * are satellite controls now, which is what the "Cloud radius" label has said
   * all along. And radar covers the whole globe rather than a ring around each
   * eye — turn it on over a Pacific typhoon and there is live rain over
   * Louisiana too.
   */
  radar: Object.freeze({
    /** One tile. Takes an explicit frame, so every tile in a viewport is the
     *  same moment and each answer is immutable. */
    relay: '/api/imagery/radar',

    /** Which frames exist. Read ONCE per refresh, not once per tile — thirty
     *  tiles fill a viewport, and letting each pick "the newest" independently
     *  would let two of them straddle a ten-minute boundary and paint a seam
     *  between two different minutes. */
    framesRelay: '/api/imagery/radar-frames',

    /** The coverage mask — transparent where radar exists, opaque black where
     *  it does not. ==> THIS IS WHAT THE §5 CONTRACT HANGS FROM, AND IT CARRIES
     *  MORE WEIGHT NOW THAN IT DID. <== With a per-storm disc the app measured
     *  the frame's own alpha to tell "blank" from "absent". A tile layer has no
     *  single frame to measure, so the mask is the ONLY thing standing between
     *  an empty screen and an all-clear over ground nobody is watching. */
    coverageRelay: '/api/imagery/radar-coverage',

    /**
     * Pixels per tile image, against a 256 px tile SLOT. That mismatch is the
     * standard retina trick, not an error: MapLibre lays the tile out at 256
     * CSS px, so a 512 px image is exactly one image pixel per device pixel on
     * a 2x screen. RainViewer offers 256 or 512 and nothing else.
     */
    requestPx: 512,
    tileSize: 256,

    /**
     * The deepest zoom RainViewer publishes. Declared to MapLibre as the
     * source's `maxzoom` so it OVERZOOMS above this — stretching a z7 tile —
     * rather than asking for tiles that do not exist and getting 404s.
     *
     * z7 at 512 px is 0.61 km/px, which is at or past the composite's own
     * native resolution, so nothing is being left on the table.
     */
    maxTileZoom: 7,

    /**
     * The shallowest zoom radar is drawn at.
     *
     * ==> THIS AND `boundsPadDeg` EXIST BECAUSE THE FIRST TILE BUILD TOOK THE
     * APP DOWN. <== Shipped with a `maxzoom` and no floor and no bounds, and on
     * a GLOBE that is a request flood: MapLibre shows a whole hemisphere at
     * once, so it asked for the entire world pyramid — z0 through z7 — and
     * re-asked on every pan. Cloudflare rate-limited the whole `/api/` path
     * with 429s, which took SATELLITE down with it, because both go through
     * the same origin. Aaron found it on glass as "toggling back doesn't work".
     *
     * Below z3 a radar tile spans 45° of longitude and the echoes inside it are
     * invisible specks, so nothing is lost by not drawing — and a whole-planet
     * globe view stops asking for anything at all.
     */
    minTileZoom: 3,

    /**
     * How far around the live storms radar is fetched, in degrees.
     *
     * ==> BOUNDS ARE THE REAL LIMITER, NOT THE ZOOM FLOOR. <== MapLibre only
     * requests tiles inside a source's `bounds`, so this is what turns "radar
     * everywhere on Earth forever" into a finite, cacheable set. Eight degrees
     * is roughly 880 km at the equator — comfortably past the rainbands of even
     * a large cyclone, which is the thing worth seeing beyond the eye.
     *
     * It also settles the open question from the tile pass honestly: a global
     * radar layer was a judgement call about NOISE, and it turns out to have
     * been a correctness problem as well. Clipping answers both.
     */
    boundsPadDeg: 8,

    /**
     * How many tile failures in a row before the layer gives up and says so.
     *
     * A rate limit does not announce itself — it arrives as dozens of identical
     * 429s while the map keeps drawing whatever tiles it already had. That is a
     * PARTIAL picture presented as a whole one, which over a storm is the §5
     * failure. Past this count the layer hides itself and the row says radar is
     * being throttled, which is true and actionable, rather than showing half a
     * rain field with no caveat.
     *
     * Twelve rather than three: a viewport legitimately holds dozens of tiles
     * and the odd one can fail on a flaky phone connection without anything
     * being wrong.
     */
    maxTileFailures: 12,

    /**
     * The zoom of the coverage box asked about each storm — one z5 tile, about
     * 626 km across at the equator.
     *
     * FIXED RATHER THAN DERIVED FROM ANYTHING THE USER CAN MOVE, deliberately.
     * The question is "is there a radar network near this storm", which does not
     * change because somebody dragged a slider, and a coverage answer that moved
     * with a control would be uncacheable for no benefit.
     */
    coverageZoom: 5,

    /**
     * The relay's three URL fields, mirrored here so `test-relay-mirrors.mjs`
     * fails when the two sides drift. A Pages Function cannot import this file
     * (§3), so these are hand-copies, and every hand-copy in this project gets
     * a test.
     *
     * ==> `smooth` MUST BE 0, AND THIS ONE WOULD HAVE SHIPPED A BUG. <==
     * Measured: an open-Pacific tile with NO radar coverage at all came back
     * 10 KB with muddy blended colour at `smooth=1`, and 1,096 bytes with
     * nothing in it at `smooth=0`. Blur invents alpha outside the data, so a
     * smoothed tile paints haze over ground no radar can see — and with the
     * per-frame alpha measurement gone, there is nothing downstream that would
     * catch it.
     *
     * `colorScheme` 2 is "Universal Blue", and it is the ONLY scheme offered —
     * the NEXRAD Level-III option an earlier pass assumed existed does not.
     * Sampled off real weather it runs cyan → blue → orange → red → magenta.
     */
    colorScheme: 2,
    smooth: 0,
    snow: 0,

    /**
     * At or above this fraction of the mask being opaque, the box has NO RADAR
     * NETWORK in it, and an empty screen there means nobody is looking rather
     * than nothing is happening.
     *
     * Not 1.0, and the margin is the point: PNG resampling and the mask's own
     * edges leave a handful of not-quite-opaque pixels around a coastline, and
     * an exact test would call a genuinely empty box "covered" on the strength
     * of three pixels. Measured reference points from §4.9 — Miami 0.07,
     * Madagascar 0.99, open Pacific and Mozambique 1.00 — so 0.995 sits in open
     * space between the worst real coverage and none at all.
     *
     * ==> A MASK THAT FAILS TO LOAD IS NEITHER STATE. <== It is "could not
     * tell", and it must never collapse into "no coverage", which reads as an
     * all-clear (§5).
     */
    noCoverageFraction: 0.995,
  }),
});

/* ---------------------------------------------------------------------------
 * PERF (SPEC §17 A5)
 *
 * Thresholds for lib/perf.js, which measures where a slow load actually went.
 * Read that file's header before changing anything here.
 * ------------------------------------------------------------------------- */
export const PERF = Object.freeze({
  /** What counts as the main thread being blocked, in ms.
   *
   *  50 is not a taste call — it is the figure the browser's own `longtask`
   *  observer uses, and picking a different number here would mean counting
   *  something the platform does not report. */
  longTaskMs: 50,

  /** Interactions faster than this are never reported to us at all.
   *
   *  The browser filters BEFORE calling back, so this is a performance knob
   *  as much as a data one: without it a fast-tapping user triggers a
   *  callback per tap, inside the interaction we are trying not to slow down.
   *  40ms is comfortably below the 200ms "feels instant" line, so nothing
   *  that would ever be judged slow can slip under it. */
  eventThresholdMs: 40,

  /** The app's own boot milestones, and the ONLY names mark() will accept.
   *
   *  - `globe`  the map style installed and the globe became touchable
   *  - `data`   the first storm data arrived from the store
   *  - `storms` a storm was actually painted on screen
   *
   *  The GAPS between these are the whole point. A long globe->data gap is a
   *  network or upstream problem; a long data->storms gap is ours. */
  /* ==> 'scripts' SPLITS THE BIGGEST UNKNOWN STAGE OF THE LOAD. <==
   * Added 2026-08-14. Field data showed the gap between first paint and
   * `globe` was the LARGEST single stage on every platform — 691ms on iOS,
   * 983ms on Android, and up to 11 SECONDS on the worst real sessions — with
   * nothing measuring inside it.
   *
   * Two very different things live in that gap: the browser unpacking and
   * running 1.5 MB of vendored MapLibre + Three (index.html), and the app
   * then building the map. The fixes are unrelated — one is a bundling
   * problem, the other is a code problem — so a single number spanning both
   * cannot choose between them. `scripts` fires at the boundary. */
  marks: Object.freeze(['scripts', 'globe', 'data', 'storms']),

  /** Hard ceiling on stored marks. A mark name that slips past the list above
   *  cannot grow the map without bound. */
  maxMarks: 16,
});

/* ---------------------------------------------------------------------------
 * TELEMETRY (SPEC §17 A5)
 *
 * How Aaron finds out the app is broken for somebody who is not him. Read
 * lib/telemetry.js's header for the privacy contract before touching any of
 * this — the short version is that home coordinates never leave the device,
 * and no field here exists to identify a person.
 *
 * Every number below is a CEILING, not a target. They exist so that a
 * client-side bug cannot turn into a traffic problem of its own, which §17
 * lists as one of the ways a public launch goes wrong.
 * ------------------------------------------------------------------------- */
export const TELEMETRY = Object.freeze({
  /** Same-origin relay. Never a third-party host: a beacon to somebody else's
   *  domain is a tracker no matter what it carries. */
  endpoint: '/api/beacon',

  /** Identifies the BUILD, never the user — the same string for everyone on
   *  this deploy. Bump it when a release needs to be told apart in the data.
   *  Kept in step with the service worker's own VERSION by hand; they are
   *  separate on purpose (a worker cannot import this file, §14 Phase 5). */
  appVersion: 'v3',

  /** Fraction of sessions that report at all, decided ONCE per session
   *  (see telemetry.js on why per-session and not per-event).
   *
   *  ==> 1.0 AS OF 2026-07-28. BACK UP FROM 0.25, AND THE REASON IT WAS EVER
   *  TURNED DOWN NO LONGER EXISTS. <==
   *
   *  0.25 was set on 2026-07-26 because the sink was a CONSOLE. Cloudflare's
   *  real-time Worker log has no aggregation and no query, so volume there
   *  was never a bill — it was ILLEGIBILITY, and past a few hundred lines a
   *  second the one message that matters is unreadable. That argument died
   *  when the sink became D1 (§17): a database does not get harder to read
   *  as rows arrive, it gets more useful.
   *
   *  ==> THE SIZING ARGUMENT, WITH REAL NUMBERS. <==
   *  D1's free tier is 100,000 ROWS WRITTEN PER DAY, and "rows written"
   *  counts index updates — one logical insert costs more than one row.
   *  Measured against this schema on 2026-07-28: a `sessions` insert cost 4,
   *  a `source_rollup` upsert about 2.
   *
   *  A visit at full sampling is one session row plus roughly four feed
   *  transitions (nhc and gdacs, each loading -> ok):
   *
   *      1 x 4  +  4 x 2   ~=  12 rows written per visit
   *
   *  2026-07-27 was a deliberate traffic peak — a forum post — and produced
   *  386 visits. That is ~4,600 rows, under 5% of a day's budget. The
   *  ceiling is roughly 8,300 visits a day, about 21x the busiest day this
   *  app has ever had.
   *
   *  ==> THE CASE THAT WOULD ACTUALLY BREAK THIS, SO IT IS NOT A SURPRISE.
   *  Errors are per-session and rare. SOURCE STATE TRANSITIONS ARE GLOBAL:
   *  when NHC flips to `unavailable`, EVERY live session reports it within
   *  one visibilitychange. Five thousand CONCURRENT readers is five thousand
   *  beacons describing one fact, and the per-minute rollup bounds the
   *  STORAGE of that, not the writes. Daily totals are what matter, and one
   *  such spike is ~10,000 rows — survivable. Several a day during a
   *  landfall with genuinely viral traffic is the scenario to watch.
   *
   *  **The lever is this line. 0.25 is a quarter of the load and still a
   *  large sample; 0.05 is the floor worth having.** A one-line push, not a
   *  rebuild. Revisit if sustained traffic passes a few thousand a day. */
  sampleRate: 1.0,

  /** Length of the anonymous device number, in hex characters (lib/device-id.js).
   *
   *  16 hex characters is 64 bits. The collision arithmetic, since the whole
   *  point of this field is counting: at 8,300 visits a day — the ceiling
   *  `sampleRate` is sized against — a full year of every visit being a
   *  DIFFERENT device is ~3 million numbers, and the chance any two of them
   *  collide is about one in four billion. Two devices counted as one is a
   *  wrong answer to the only question this field exists to answer, so it is
   *  sized to make that impossible rather than unlikely.
   *
   *  ==> IT IS ALSO THE SERVER'S VALIDATION RULE. <== functions/api/beacon.js
   *  accepts exactly this many lowercase hex characters and nothing else, so
   *  the column can never hold caller-controlled text. Changing this number
   *  changes that gate; the two must move together. */
  deviceIdHexChars: 16,

  /** Events held before the oldest is dropped. A cascade is one fact repeated;
   *  the newest events describe the current state. */
  maxQueue: 20,

  /** Beacons per session, ever. The backstop against a render-loop bug
   *  becoming a request storm — past this the module goes quiet for good. */
  maxSendsPerSession: 10,

  /** Field caps. An unbounded message is how page content or a URL ends up
   *  in a log by accident. */
  maxMessageChars: 300,
  maxStackChars: 600,

  /** Stack frames kept. Enough to name the failing module; not so many that
   *  the payload becomes a document. */
  stackFrames: 5,
});

/**
 * POPULATION — the town list, the heat layer, and the in-path headcount.
 * SPEC §7 (layer manifest), SPEC.md §5 (three states).
 *
 * ==> ONE DATA FILE, TWO READERS, AND THAT IS THE WHOLE DESIGN. <== The heat
 * layer and the number in the storm drawer are the same 107,464 towns. Whoever
 * needs it first pays for it; the second gets it free. A visitor who never
 * opens a storm and never switches the layer on downloads nothing at all.
 *
 * WHY IT IS LAZY RATHER THAN WARMED. 670 KB gzipped is not a lot, and it is
 * also not nothing on the phone connection of somebody checking a hurricane
 * during a hurricane. Every byte on the critical path competes with the cone.
 * The file is service-worker cacheable, so the cost is once per device.
 */
export const POPULATION = Object.freeze({
  /** Built by tools/build-population.mjs. Flat [lon, lat, pop, …]. */
  url: 'assets/hazards/population-towns.json',

  /** What the shipped file holds, stated so a test can catch a silent
   *  truncation — a half-downloaded list would still parse and would still
   *  produce a plausible-looking, wrong headcount. */
  expectedTowns: 107464,

  /** The population floor of the source list. Surfaced in the UI note: this
   *  is the number that makes the count an undercount, so it is a fact the
   *  user is entitled to rather than an implementation detail. */
  minTownPopulation: 1000,

  /**
   * ==> A TOWN FADES IN. IT DOES NOT POP IN. <== The first build gated the
   * heat with a `step` filter on population, so at zoom 3 every town between
   * 50,000 and 300,000 arrived in a single frame. Aaron caught it on glass and
   * the description was exact: "the detailed data just pops in".
   *
   * A filter is binary; a threshold that slides with zoom is not. So the gate
   * moved onto WEIGHT rather than membership. Each town's contribution ramps
   * from nothing to full as the threshold passes it, which means nothing ever
   * appears — things only get louder.
   *
   * THE THRESHOLD IS IN LOG10 OF POPULATION, because that is the space the
   * weight already lives in, and two different ideas of "how big is this town"
   * are two things that can drift apart. 5.0 is 100,000 people; 3.0 is the
   * floor of the shipped file.
   *
   * Read as: at this zoom a town of exactly 10^log contributes nothing, and
   * one of 10^(log + fadeWidthLog) contributes its full weight.
   */
  fadeThresholdLog: Object.freeze([
    Object.freeze({ zoom: 0, log: 5.0 }),  // planet — 100k enters, 500k full
    Object.freeze({ zoom: 3, log: 4.3 }),  // basin — 20k enters
    Object.freeze({ zoom: 5, log: 3.6 }),  // regional — 4k enters
    Object.freeze({ zoom: 7, log: 2.8 }),  // local — under the floor, all in
  ]),

  /** How much population a town crosses while fading in, in log10. 0.7 is a
   *  factor of five: wide enough to read as a fade rather than a fast edge,
   *  narrow enough that the threshold still means something. */
  fadeWidthLog: 0.7,

  /**
   * ==> THE FILTER STILL EXISTS, AND IT MUST NEVER CUT A TOWN THAT WOULD BE
   * VISIBLE. <== Drawing all 107,464 points at every zoom is real work, so a
   * cheap membership test still earns its place. But a `step` is discrete and
   * the fade is continuous, so a filter set at the CURRENT threshold would
   * clip towns mid-fade and reintroduce the exact pop it exists to prevent.
   *
   * Each entry is therefore the LOWEST threshold its zoom range will reach —
   * which is the threshold at the START of the next range. A town enters the
   * source already weighing zero and fades up from there.
   *
   * These are not independent numbers. They are `fadeThresholdLog` read one
   * row ahead, and they change when it changes.
   */
  filterFloor: Object.freeze([
    /* ==> ROUNDED DOWN, NOT TO THE NEAREST ROUND NUMBER. <== 10^4.3 is 19,952
     * and 10^3.6 is 3,981. Writing the tidy 20,000 and 4,000 puts the filter a
     * hair ABOVE the threshold it is meant to sit under, which clips a sliver
     * of towns mid-fade — the pop-in bug back again, too small to see and
     * still wrong. The test asserts this and caught exactly that. */
    Object.freeze({ zoom: 0, pop: 19000 }),  // under 10^4.3, the z3 threshold
    Object.freeze({ zoom: 3, pop: 3900 }),   // under 10^3.6, the z5 threshold
    Object.freeze({ zoom: 5, pop: 1000 }),   // z7's threshold is under the floor
  ]),

  /**
   * Heat radius, by zoom.
   *
   * ==> THE BUG AARON DESCRIBED — "so large over Japan, then as you zoom it
   * shrinks and disappears" — IS ONE MISTAKE SEEN FROM BOTH ENDS. <== The
   * radius was in SCREEN pixels and grew only gently with zoom, so the ground
   * distance it stood for was wildly different at every altitude. At the basin
   * band a 20 px blur covered roughly 400 km, which turned Honshu into one
   * continuous smear and claimed a density nobody measured. At the local band
   * the same curve had fallen to a fraction of that in ground terms, so cities
   * thinned into separate specks and the field appeared to evaporate.
   *
   * ==> SO THE RADIUS IS NOW ANCHORED TO THE GROUND, NOT THE SCREEN. <== A
   * town's catchment is a real distance — call it `groundRadiusKm` — and the
   * pixel figure below is that distance converted at each zoom. Web Mercator
   * doubles its scale per zoom level, so these values double too. That is the
   * curve that keeps a blob the same size ON THE PLANET while the planet
   * changes size on the phone, which is the only version of this that is
   * making an honest claim.
   *
   * TWO CLAMPS, BOTH FOR REASONS THE MATHS DOES NOT KNOW ABOUT:
   *   - A FLOOR near the planet band. True ground-scale would put a town under
   *     one pixel out there, which is not a density field, it is noise. The
   *     floor holds cities at a readable dot — honest, because a dot claims
   *     far less than a smear did.
   *   - A CEILING past the local band. Heatmap cost is per-point and scales
   *     with the square of the radius, and unbounded doubling would put a
   *     several-hundred-pixel quad under every town. This is where the layer
   *     stops being exactly ground-true, and it is a deliberate trade rather
   *     than an oversight.
   */
  groundRadiusKm: 20,

  heatRadius: Object.freeze([
    Object.freeze({ zoom: 0, px: 5 }),    // floor — a city is a dot out here
    Object.freeze({ zoom: 4, px: 6 }),    // floor still binding
    Object.freeze({ zoom: 5, px: 9 }),    // ground scale takes over
    Object.freeze({ zoom: 6, px: 17 }),
    Object.freeze({ zoom: 7, px: 33 }),
    Object.freeze({ zoom: 8, px: 60 }),
    Object.freeze({ zoom: 9, px: 90 }),   // ceiling starts to bite
    Object.freeze({ zoom: 11, px: 110 }),
  ]),

  /**
   * ==> WEIGHT IS THE LOG OF POPULATION, NOT POPULATION. <== Tokyo is 22.3
   * million and a small town is 1,000 — a ratio of 22,000:1. Fed in raw, the
   * ramp saturates at Tokyo and is mathematically indistinguishable from black
   * everywhere else, which is a map of Tokyo, not a map of people.
   *
   * `log10(pop)` compresses the same range into 3 to 7.35, and those are the
   * two numbers below. Everything between lands on a usable part of the ramp.
   */
  weightMinLog: 3,      // log10(1,000)
  weightMaxLog: 7.35,   // log10(~22.3M), the largest place in the file

  /**
   * ==> THE SMALLEST TOWN MUST NOT WEIGH EXACTLY ZERO. <== Normalising 3.0 to
   * 0 makes every thousand-person town contribute literally nothing — and so a
   * hundred of them scattered across a rural county sum to nothing as well,
   * which is the opposite of what a density field is for. This floor is what
   * lets a scatter of small places read as somewhere people live.
   */
  weightFloor: 0.12,

  /**
   * Which wind band the drawer headcount uses. Aaron's call: the
   * tropical-storm-force band, not the cone.
   *
   * ==> THE CONE IS NOT AN IMPACT AREA AND COUNTING PEOPLE IN IT WOULD TEACH
   * THAT IT IS. <== The cone is where the CENTRE is likely to go — two thirds
   * of the time, historically. It says nothing about how far the damaging wind
   * reaches, which is the entire question "how many people are affected" is
   * asking. The wind swath is the shape that answers it, and both NHC and
   * GDACS publish one.
   *
   * 34 kt (GDACS: ~60 km/h) is the threshold, because tropical-storm-force
   * wind is where outdoor work stops, power lines come down, and evacuation
   * windows close. The stronger bands are a smaller, more alarming number
   * about a smaller area; this is the one that matches the plain-English
   * phrase "in the path".
   */
  pathSlot: 'windSwath',
  pathThresholdKt: 34,

  /**
   * The forward-only half of the envelope, used to split the headcount into
   * what is still coming and what has already happened.
   *
   * ==> `pathSlot` IS THE STORM'S WHOLE LIFE AND NOTHING INSIDE IT SAYS WHERE
   * THE PAST ENDS. <== NHC's swept envelope merges the past track, the current
   * field and the forecast into one polygon (`lib/windswath.js`). Counted whole
   * under a heading reading "in the path", it warns about wind that fell days
   * ago. Measured on Hurricane Lala, advisory 34A, 2026-08-21: 1,337,723 people
   * in 121 towns, all of them Hawaii, all of them behind the storm, and zero
   * people anywhere ahead of it.
   *
   * `data/nhc-mapserver.js` builds this slot with the same sweep and the past
   * tier withheld. NHC only — GDACS publishes no past wind field, so its swath
   * is already forward-only and its storms simply have no slot here.
   */
  aheadSlot: 'windAhead',
});

/* ---------------------------------------------------------------------------
 * SEASONS — the historical globe
 * ------------------------------------------------------------------------- */

/**
 * SPEC-SEASONS-BUILD.md §57. Every number the history parser and indexer use.
 *
 * ==> ALL OF THIS IS MEASURED, NOT REMEMBERED. <== The field counts, the
 * sentinels, the storm-number bands and the ATCF column positions were all
 * counted off NOAA's own files on 2026-08-24 — 55,605 Atlantic data rows and
 * 32,026 Pacific ones, plus all fourteen 2026 b-decks. Where a number here
 * disagrees with a remembered format document, the file won.
 */
export const SEASONS = Object.freeze({
  /* --- HURDAT2 row shape (§57.4) ------------------------------------------ */

  /** A data row is exactly this many comma-separated fields. Counted across
   *  BOTH whole files: 87,631 rows, not one of them any other width. A row
   *  that is not this wide is a parse failure and is reported, never guessed
   *  at — the step 0 probe's first run reported "18, 21 — not consistent" and
   *  that was its own truncation lying, not the data. */
  hurdatDataFields: 21,

  /** A header row is three fields plus the trailing comma the format writes,
   *  so splitting yields four. This is the ONLY thing that distinguishes a
   *  header from a data row, and keeping the test that dumb means a change in
   *  the data columns cannot break the storm splitter. */
  hurdatHeaderFields: 4,

  /** The missing-value marker. 10,681 of them in the Atlantic file alone,
   *  which is what a century of unmeasured wind radii looks like. */
  hurdatMissing: '-999',

  /** A SECOND missing marker, and it means something different: no intensity
   *  was ever assigned. §57.6 attributes it to the non-developing depressions
   *  of 1967; the first one actually in the file is AL021971, on ONE row of a
   *  storm whose other four carry a real wind. Both markers become `null`, but
   *  they are listed separately because a reader asking "why is there no wind
   *  speed here" deserves the real answer. */
  hurdatNoIntensity: '-99',

  /* --- ATCF b-deck column positions (§57.4a) ------------------------------ */

  /**
   * ZERO-BASED column indices, measured off `bcp012026.dat` and
   * `bal022026.dat` rather than recalled.
   *
   * ==> §57.4a HAD THREE OF THESE OFF BY ONE AND THE SPEC IS FIXED. <== It put
   * the wind threshold at field 11 and the storm name at field 27. The real
   * file puts the STATUS at field 11 (one-based), the threshold at 12, the
   * quadrant code at 13, and the name at 28. A parser built to the old text
   * would have read a storm's status as its wind threshold.
   */
  atcf: Object.freeze({
    basin: 0,
    cycloneNumber: 1,
    dtg: 2,
    tech: 4,
    tau: 5,
    lat: 6,
    lon: 7,
    windKt: 8,
    pressureMb: 9,
    status: 10,
    radThresholdKt: 11,
    quadrantCode: 12,
    radNe: 13,
    radSe: 14,
    radSw: 15,
    radNw: 16,
    rmwNm: 19,
    gustKt: 20,
    name: 27,
    /** Fields 1-35 (one-based) are positional; from 36 on the row is a run of
     *  `key, value` pairs — `genesis-num, 004`, `SPAWNINVEST, al762026 to
     *  al932026`. Measured: 36 fields on Lala, 38 on Bertha, and Bertha's
     *  extra two are exactly one such pair. A parser that indexes from the END
     *  of the row breaks on the first storm that spawns an invest. */
    positionalFields: 35,
  }),

  /** Only `BEST` rows are the working best track. A b-deck holds nothing else
   *  today, but the filter exists because ATCF is a shared format and one that
   *  is present and never fires costs nothing. */
  atcfBestTech: 'BEST',

  /** The quadrant order the four radii columns are written in, for every
   *  `NEQ` row — the only code present across all fourteen 2026 b-decks. */
  quadrantOrder: Object.freeze(['ne', 'se', 'sw', 'nw']),

  /** The three wind thresholds a storm's field is published at. HURDAT2 puts
   *  all three on one row as twelve numbers; ATCF puts each on its own line
   *  sharing a timestamp, which is why the ATCF reader MERGES. */
  radiiThresholdsKt: Object.freeze([34, 50, 64]),

  /* --- Which storms are real (§57.13) ------------------------------------- */

  /** From NHC's own README. 01-30 are real storms; 90-99 are invests and those
   *  numbers are REUSED several times inside one season, so an unfiltered
   *  mirror ships three different systems all called 92 and they overwrite
   *  each other; 80-89 are internal test systems. The ceiling is set above 30
   *  because a season can run past it — 2005 reached AL31 — and below 80 so
   *  nothing in either reserved band can slip through. */
  realStormNumberMin: 1,
  realStormNumberMax: 49,

  /** The basins NHC's own files cover. Anything else in a filename is not ours
   *  to read here — §57.30 step 13 owns the rest of the world. */
  nhcBasins: Object.freeze(['AL', 'EP', 'CP']),

  /* --- The season in progress (§57.30 step 5b, §58) ----------------------- */

  /**
   * ==> WHICH ATCF BASIN TOKENS BELONG TO WHICH ARCHIVE BASIN, AND THE
   * CENTRAL PACIFIC IS THE WHOLE REASON THIS EXISTS. <== `seasons/index.json`
   * keys the settled record on `atlantic` and `epacific`; the live b-decks are
   * filed under `AL`, `EP` and `CP`. The mapping is NOAA'S OWN and was
   * measured in this repo's files rather than assumed: `epacific-2024`
   * contains CP012024, and `epacific-2025` contains CP012025 and CP022025. The
   * reviewed record keeps one file for both, so anything else here would make
   * the season in progress disagree with the 77 years behind it — and would
   * drop Lala and Moke off the board with nothing said.
   *
   * A basin absent from this table has no live half at all, which is the
   * honest state for the rest of the world until step 13.
   */
  liveBasins: Object.freeze({
    atlantic: Object.freeze(['AL']),
    epacific: Object.freeze(['EP', 'CP']),
  }),

  /** How many b-decks to fetch at once when a reader opens the current
   *  season. FOUR, and the ceiling is the READER'S phone rather than NOAA's
   *  server: fifteen parallel requests on a cell connection is fifteen slow
   *  requests, not one fast one, and these are not warmed (§58.3) so several
   *  of them reach upstream. Four keeps the last storm's wait to roughly four
   *  round trips on a fifteen-storm season. */
  liveFetchConcurrency: 4,

  /* --- Derived facts (§57.15) --------------------------------------------- */

  /** A storm counts as NAMED for a season total when it reached at least this,
   *  which is the tropical-storm threshold. Fixed meteorology, not a choice. */
  namedStormKt: 34,

  /** Hurricane and major-hurricane thresholds, for "days at strength" and the
   *  season scorecard. The same numbers `lib/category.js` grades a dot with —
   *  a Cat 3 in 1935 and a Cat 3 today have to be the same claim. */
  hurricaneKt: 64,
  majorKt: 96,

  /** ACE counts only SYNOPTIC records — 00, 06, 12 and 18Z on the hour. The
   *  landfall and peak rows NOAA inserts between them are NOT synoptic (Ida's
   *  Louisiana landfall is stamped 1655Z), and counting them inflates the
   *  figure for exactly the storms people look up. */
  aceSynopticHours: Object.freeze([0, 6, 12, 18]),

  /** ACE is the sum of squared wind in knots, divided by this. The convention
   *  is fixed; it lives here so no file writes 10000 without a reason. */
  aceDivisor: 10000,

  /** Statuses that count as a tropical or subtropical cyclone, for ACE and for
   *  "days at strength". `EX` extratropical, `LO` low, `WV` wave and `DB`
   *  disturbance are all in the file and none of them is one. */
  cycloneStatuses: Object.freeze(['TD', 'TS', 'HU', 'SD', 'SS']),

  /** The window the fastest-intensification figure is measured over. Twenty-
   *  four hours is the meteorological convention for rapid intensification and
   *  it lines up with four six-hourly records. */
  intensificationWindowHours: 24,

  /** ==> THE THRESHOLD THAT TURNS A NUMBER INTO A FACT THE READER CAN PLACE.
   *  <== 30 knots in 24 hours is the National Hurricane Center's own
   *  definition of rapid intensification, and it is the phrase a reader will
   *  have heard on the news. The panel states the gain either way; this is
   *  what lets it add "that meets what forecasters call rapid
   *  intensification" rather than leaving the reader to know the convention.
   *
   *  IT IS A LABEL, NEVER A FILTER. Nothing is hidden for falling under it —
   *  a 25 kt gain in a day is still the fastest this storm ever strengthened
   *  and is still shown. */
  rapidIntensificationKt: 30,

  /** ==> THE TWELVE YEARS WHERE AN EMPTY LANDFALL LIST MEANS "NOBODY WROTE IT
   *  DOWN" RATHER THAN "IT STAYED AT SEA". <== §57.7.
   *
   *  This is the one absence in the archive that LOOKS LIKE A FACT. Everywhere
   *  else an empty landfall list is real information — the storm went out to
   *  sea. Across these years NOAA simply did not mark US landfalls in the best
   *  track, so a storm that plainly came ashore in Texas shows none, and the
   *  panel would appear to state something false. It gets its own sentence.
   *
   *  MEASURED 2026-08-25 over every mirrored Atlantic season: 1971 through
   *  1982 inclusive carry ZERO `L` records, twelve consecutive years. **The
   *  spec said 1971-1990 until step 2 measured it** — Hugo '89 is marked, so
   *  the hole is twelve years and not twenty. 1922 also carries zero and is
   *  NOT part of this: it is a single isolated year outside the run, which is
   *  what a genuinely quiet season looks like rather than a gap in the
   *  marking. Widening this range to swallow it would silence a true "no
   *  landfall" answer for one year to tidy up a boundary. */
  landfallMarkerHoleFrom: 1971,
  landfallMarkerHoleTo: 1982,

  /** ==> BEFORE THIS, STORMS ARE SIMPLY MISSING FROM THE RECORD. <== Nobody
   *  saw the ones that stayed at sea. A quiet-looking 1935 season page is not
   *  evidence of a quiet season, and the board has to say so — which is a
   *  claim about the ERA, decidable only from the year, because the numbers
   *  are exactly what cannot show it. §57.6. */
  satelliteEraFrom: 1966,

  /* --- The Wall of Years (§57.29, §57.36) ---------------------------------- */

  /** ==> ONE ROW IS ONE TOUCH TARGET AND NO EXCEPTION WAS CARVED OUT FOR IT.
   *  <== §13's 44px floor. Aaron judged this on glass 2026-08-26 against the
   *  alternative — a denser wall that fits more years on a phone — and kept
   *  the target. 175 rows at 44px is a long scroll on purpose: the length IS
   *  the record, and a wall you can flick through in two swipes stops being
   *  about how much history there is. */
  wallRowPx: 44,

  /** The dot bounds. `dotSizeFor` divides the strip by the BUSIEST season in
   *  the basin, so these two decide what happens at the extremes rather than
   *  in the ordinary case.
   *
   *  ==> THE FLOOR EXISTS BECAUSE THE ATLANTIC'S BUSIEST SEASON IS 31 STORMS.
   *  <== Measured off `seasons/wall.json`: 2005 and 2020, both 31. That single
   *  number sets the scale for all 175 rows, because a violent year has to
   *  physically look longer than a quiet one or there is no reason to draw a
   *  wall at all.
   *
   *  ==> AND IT IS WHY "BIGGER DOTS AND WIDER GAPS" CANNOT BOTH BE HAD. <==
   *  Aaron asked for both on glass, 2026-08-26. The strip has roughly 300 CSS
   *  pixels on a 390px phone, so 31 storms get about 9.7px each INCLUDING the
   *  gap — dot plus gap cannot exceed that without the busiest rows spilling
   *  past the count column, and clipping 2005 would make the wall lie about
   *  the year it exists to show. The room was found by trimming the year and
   *  count columns instead, and the glow is what does the rest of the work:
   *  a 7px dot with `--dot-glow-blur` around it reads considerably larger than
   *  a 7px dot without one.
   *
   *  The ceiling stops a sparse basin — or a wide desktop rail — drawing a
   *  quiet year as a row of beach balls, which would make 1914's single storm
   *  louder than 2005's thirty-one. */
  wallDotMin: 4,
  wallDotMax: 14,

  /** Between dots. Two pixels is enough to read thirty-one of them as
   *  thirty-one rather than as a bar, and small enough that a quiet year's
   *  strip is still visibly short. */
  wallDotGap: 2,

  /* --- The wall's filters and sort (§57.36, step 3) ------------------------
   * ==> EVERY THRESHOLD BELOW IS A REAL PERCENTILE OFF `seasons/wall.json`,
   * NOT A ROUND NUMBER SOMEBODY LIKED. <== Measured 2026-08-26 over both
   * basins, 3,266 storms. A ceiling above the strongest storm on record gives
   * a slider a dead zone at the top and a reader no way to know it is dead;
   * one just past the record keeps every position meaningful.
   * ---------------------------------------------------------------------- */

  /** ACE contributed by ONE storm. Median 4.5, 90th percentile 21.7, and the
   *  most violent storm in the record is 85.3 — so the ceiling is 90 and the
   *  step is 5, which puts the useful part of the range (0 to 25) in the first
   *  third of the travel where a thumb actually lands. */
  wallAceMin: 0,
  wallAceMax: 90,
  wallAceStep: 5,

  /** How long a storm lasted, in days. Median 5.5, 90th percentile 11.8, and
   *  the longest-lived storm in the record ran 32.8 days. A half-day step is
   *  the record's own resolution — HURDAT2 fixes are six-hourly, so anything
   *  finer would be filtering on arithmetic rather than on measurement. */
  wallDaysMin: 0,
  wallDaysMax: 35,
  wallDaysStep: 0.5,

  /** ==> LOWEST PRESSURE RUNS THE OTHER WAY AND THAT IS THE WHOLE TRAP. <== A
   *  LOWER number is a STRONGER storm, so this is a ceiling ("under 950 mb")
   *  where the other two are floors. Wilma's 882 mb is the Atlantic record and
   *  872 is the lowest in the file, so the floor sits at 870; the top is 1010
   *  because a storm at 1010 mb is barely a storm and a slider that runs to
   *  1016 spends its last third on rows nothing filters out.
   *
   *  ==> AND A STORM WITH NO PRESSURE READING IS EXCLUDED, NOT SWEPT IN. <==
   *  §5. 1,258 of the 3,266 carry no central pressure at all, almost all of
   *  them before aircraft reconnaissance. Treating "not measured" as "not low"
   *  is defensible; treating it as "low" would put the entire 19th century
   *  under a 950 mb filter on the strength of a reading nobody took. */
  wallPressureMin: 870,
  wallPressureMax: 1010,
  wallPressureStep: 5,

  /** ==> THE FIVE SORT KEYS, AND THERE MUST NEVER BE A SIXTH OF THE SHAPE
   *  "MOST CATEGORY 5s". <== §57.36. Every question of that form falls out of
   *  a filter stacked on one of these, which is the entire reason the two
   *  controls exist as two controls. Named here so `lib/wall-filter.js` and
   *  the control markup cannot disagree about which keys exist. */
  wallSortKeys: Object.freeze(['year', 'count', 'strongest', 'landfalls', 'ace']),

  /** The wall opens newest-year-first, which is the order it has always been
   *  in and the only order in which the satellite-era line can be drawn. */
  wallSortDefault: 'year',
  wallSortDirDefault: 'desc',

  /* --- Near home (§57.19) -------------------------------------------------- */

  /** The radius slider. Under 10 miles is noise against a position every six
   *  hours; over 500 and everything in the Atlantic matches.
   *
   *  ==> IT IS DEFINED TWICE, ONCE PER UNIT SYSTEM, AND THAT IS NOT
   *  DUPLICATION. <== §57.19 wrote this range in miles because a reader
   *  thinks in miles. This app has a metric reader too (`lib/units.js`), and
   *  the two ways of serving them are both worse than this one: converting
   *  500 miles gives a slider that runs to 805 and steps by 16, and holding
   *  the slider in miles while every other distance on screen is in
   *  kilometres is a control lying about its own units. So each system gets
   *  round numbers of its own, covering the same ground — 800 km is 432 nm
   *  and 500 mi is 434 nm, which is the same circle to within half a percent.
   *
   *  `default` is the radius the Home dashboard's standing line quotes as
   *  well as the one the slider opens on, deliberately: a door that says
   *  "within 120 miles" and then opens a screen set to a different number is
   *  the app disagreeing with itself in two taps. */
  nearHomeRange: Object.freeze({
    imperial: Object.freeze({ min: 10, max: 500, step: 10, default: 120, unit: 'mi' }),
    metric: Object.freeze({ min: 20, max: 800, step: 20, default: 200, unit: 'km' }),
  }),

  /** How far out the whole-archive answer is KEPT, in statute miles.
   *
   *  ==> IT IS THE LARGER OF THE TWO SLIDER MAXIMA, AND THAT IS THE WHOLE
   *  RULE. <== The index pass runs once and its result is stored; anything
   *  further from home than the slider can ever ask about is weight with no
   *  question behind it. 500 mi covers the imperial maximum exactly and the
   *  metric one (800 km = 497 mi) with room to spare, so switching units can
   *  never reach past what was kept. Measured on the real archive: 526
   *  storms for New Orleans, 775 for Miami, 112 for Honolulu — 10 to 65 KB
   *  of JSON, which is why this can be stored at all. */
  nearHomeKeepMi: 500,

  /** ==> THE WHOLE-ARCHIVE PASS WAITS UNTIL AFTER THE APP HAS DRAWN. <==
   *  §57.35 fault 4. It reads two files that together are 0.93 MB over the
   *  wire, and it exists to fill in one sentence at the foot of the
   *  dashboard. Starting it during boot would put that megabyte in front of
   *  the storm a reader actually opened the app for. Long enough that first
   *  paint and the first poll are both done; short enough that the sentence
   *  is there before anyone scrolls to the bottom. */
  nearHomeIndexDelayMs: 4000,

  /** ==> THE INDEX MEASURES AGAINST THE LINE, NOT THE POINTS. <== A storm
   *  moving 20 mph covers 120 miles between six-hourly records, so a fast
   *  mover can hop clean over the circle without one recorded position landing
   *  inside it. Without this the feature quietly lies about fast storms, which
   *  is the worst kind of bug: it looks like it works. Measured on Ida against
   *  New Orleans, her closest approach falls BETWEEN two records — the first
   *  storm it was tried on. This flag turns the segment measurement off and
   *  exists ONLY so the suite can prove the points-only answer is wrong. Never
   *  set false in the app. */
  nearHomeMeasureSegments: true,

  /** A cheap latitude-only reject before any great-circle arithmetic. A degree
   *  of latitude is 60 nm everywhere — no longitude, no seam, no frames — so a
   *  segment whose whole latitude band sits further than the best answer so
   *  far cannot beat it. Exact rather than approximate, so it cannot change a
   *  result, only save work. */
  nmPerDegreeLat: 60,

  /* --- The dateline (§57.2) ------------------------------------------------ */

  /** ==> A LONGITUDE STEP LARGER THAN THIS IS THE SEAM, NOT WEATHER. <== The
   *  files write every longitude inside -180..180 with a hemisphere letter, so
   *  a storm crossing the antimeridian publishes 179.2W and then 179.9E: two
   *  positions 0.9deg apart whose numbers differ by 359.1. Hurricane Della,
   *  CP011957, does exactly that at record 35 of 48 — she is the fixture, and
   *  she is real. Anything above this threshold is unwrapped rather than
   *  believed. A genuine 180deg jump in six hours would be 2,000 mph. */
  seamJumpDeg: 180,

  /** Every normalised point carries BOTH longitudes: `lon` is the true value
   *  the file published, and `lonU` is the continuous one that may run past
   *  ±180 so a line drawn through it does not travel the long way round the
   *  planet. That is this app's existing convention (`lib/trackline.js`,
   *  `lib/adeck.js`), and the two are computed once at parse time rather than
   *  by every consumer. Distances and facts read `lon`; drawing reads `lonU`. */
  carryUnwrappedLongitude: true,

  /* --- The shareable link (§57.20) ----------------------------------------- */

  /**
   * ==> THESE THREE WERE READ BY `seasons/deep-link.js` BEFORE THEY EXISTED.
   * <== Step 4 shipped the link parser and step 2 shipped this block, and the
   * three names the parser needs never landed in it. Nothing caught that:
   * `check-syntax.mjs` proves an IMPORT resolves, and `SEASONS` imported fine
   * — it was the PROPERTIES that were absent, which is a runtime undefined,
   * not a broken module.
   *
   * The symptom was silent and was exactly §5's shape. `year < undefined` is
   * false and `year > undefined` is false, so EVERY comparison passed and the
   * range check was inert: `?season=1066` was accepted, resolved to a season
   * with no storms in it, and opened the archive on an empty globe with
   * nothing said. A year outside the record and a genuinely quiet season
   * looked identical, which is the one distinction the words exist to make.
   * `tools/test-archive-mode.mjs` had been red on main since step 4 and is
   * what named it.
   */

  /** The first season in the record, from the files themselves rather than
   *  recollection: `AL011851` is the first header row of the Atlantic file and
   *  `seasons/index.json` agrees. THE ATLANTIC IS THE FLOOR FOR THE WHOLE
   *  FEATURE, not each basin's own start — the Pacific record only opens in
   *  1949, and a link to 1900 is a real year with real Atlantic storms that
   *  happens to have no Pacific half. Rejecting it would be wrong; the empty
   *  basin is the roster's problem to describe, not the link's. */
  firstSeason: 1851,

  /** How far past the current year a link may point. ONE, and the reason is
   *  timezones rather than generosity: a link made at 23:00 on 31 December in
   *  New York is opened on 1 January in London, and `nowYear` is whatever the
   *  READER's clock says. Without the extra year that link is "out of range"
   *  to the person it was sent to and fine to the person who sent it, which is
   *  unexplainable. Two would start accepting seasons that cannot exist. */
  seasonLinkFutureYears: 1,

  /** The most storm slugs one link may carry. A season's roster tops out near
   *  30 (2005 reached AL31), so 24 is generous for "here are the ones I mean"
   *  while still bounding what a hand-built or hostile URL can ask the globe
   *  to draw at once. The list is capped, not rejected — a link with 500 slugs
   *  in it still opens on its season. */
  deepLinkMaxStorms: 24,

  /** ==> HOW MANY VERTICES ONE ARCHIVE TRACK MAY SPEND ON BEING CURVED, AND
   *  WHY IT IS A THIRD OF THE LIVE GLOBE'S. <==
   *
   *  Archive tracks go through the same centripetal Catmull-Rom as every live
   *  track (`lib/trackline.js` `smoothPath`), because a corner at every
   *  six-hourly fix is the tell that says "this globe is a different app". What
   *  differs is how MANY of them are on screen: the live globe draws one
   *  storm's track, and a reader who ticks all of 2005 draws twenty-eight.
   *
   *  `TRACK_LINE.spacingDeg` is what actually decides the count for a typical
   *  storm — roughly 5 nm between output vertices, so a 3,000 nm track lands
   *  near 600 whatever the ceiling says. This ceiling therefore does nothing at
   *  all to an ordinary storm and bites only on the long-lived monsters, which
   *  are exactly the ones a full season has several of. 400 holds a fully
   *  ticked 2005 near eleven thousand vertices instead of twenty thousand.
   *
   *  Same trade as `TRACK_LINE.maxVertices` and `RING_POLISH.maxSamples` before
   *  it: a pathological track costs a slightly coarser line, never the frame
   *  budget. Raise it if a long track reads faceted at close zoom on glass. */
  trackMaxVertices: 400,

  /** ==> THE FIRST SEASON HURDAT2 RECORDS A WIND FIELD FOR, AND IT DECIDES
   *  WHICH SENTENCE IS SAID — NEVER WHETHER A FOOTPRINT IS BUILT. <==
   *
   *  §57.25 rule 2: a thing that COULD have existed and does not for this
   *  storm is shown with the reason, and *"Wind field size wasn't recorded
   *  before 2004"* is a sentence that teaches the reader something true about
   *  the record. This is the year in it.
   *
   *  ==> IT IS NOT A GATE, AND §57.6 IS THE REASON THAT DISTINCTION IS
   *  WRITTEN DOWN. <== Nothing in `lib/hurdat.js` asks what year it is —
   *  every missing value is decided by reading the sentinel on the row,
   *  because AL011852 carries a radius of maximum wind 169 years before that
   *  cliff. `lib/season-windswath.js` follows the same rule: a storm has a
   *  footprint if its rows carry radii, whatever the year. This number only
   *  chooses the WORDING when `season-facts.js` has already established there
   *  is nothing to draw — an era sentence before 2004, a bare one after, so
   *  the app never claims an era rule it has not checked.
   *
   *  MEASURED 2026-08-24 across both mirrored basins, every season 1851-2025:
   *  zero storms before 2004 carry any radii; from 2004 on it is every storm
   *  in every year in both basins. AL012004 ALEX and EP012004 AGATHA are the
   *  first. 826 of 3,266 storms have a wind field — three quarters of the
   *  archive gets the sentence instead of a shape. */
  windFieldFirstSeason: 2004,

  /* --- The season still running, on the roster (§57.21c) ------------------ */

  /**
   * ==> HOW RECENT A STORM'S LAST FIX HAS TO BE FOR THE ROSTER TO CALL IT
   * RUNNING. <== §57.21c.
   *
   * A b-deck does not carry a "this storm is over" flag. NHC simply stops
   * appending rows, and the file sits there looking exactly as it did while the
   * storm was alive — so the only signal available is how long ago the last row
   * was written.
   *
   * TWELVE HOURS IS TWO MISSED CYCLES, AND THE CADENCE IS THE REASON. NHC
   * writes a best-track row every six hours, so a storm that is genuinely
   * running has a fix inside six. Twelve absorbs one skipped or slow cycle
   * without ever reaching back far enough to call a storm that dissipated
   * yesterday "active".
   *
   * ==> IT IS ONLY ASKED ON THE SEASON IN PROGRESS. <== A settled year cannot
   * have a running storm however recent its rows look, so `provisional` gates
   * this before the arithmetic runs. Nothing in a reviewed file can trip it.
   *
   * ==> AND ERRING LATE IS THE SAFE DIRECTION HERE, WHICH IS THE OPPOSITE OF
   * THE USUAL. <== Calling a finished storm "active" for a few extra hours
   * leaves it off the archive globe, where it costs the reader one track they
   * could have drawn. Calling a running storm finished puts a LIVE system on
   * the sepia globe, which is the thing §57.21c exists to stop.
   */
  activeWithinHours: 12,

  /* --- Where the archive's camera goes (§57.21c) --------------------------- */

  /**
   * ==> WHERE THE GLOBE OPENS WHEN THE ARCHIVE IS ENTERED FROM THE STORM LIST.
   * <== §57.21c. The reader came from a list of live storms and asked for
   * history; they are looking for the ocean the storms are in, not for their
   * own house. The home door is the other case and keeps home (§57.16 already
   * gives the two doors different `data-door` values for exactly this).
   *
   * ==> THESE ARE CAMERA REST POSITIONS, NOT CLAIMS ABOUT WHERE A BASIN IS.
   * <== Nothing is drawn from them and no figure is derived from them, so they
   * are a UI constant rather than data — the one place in this feature where a
   * hand-chosen coordinate is legitimate. They are the middle of the water each
   * record covers, read off the basins' own storm tracks:
   *
   *   - Atlantic runs roughly 100°W to 10°W and 5°N to 50°N.
   *   - The east Pacific file carries the CENTRAL Pacific too (`liveBasins`
   *     above records why), so it runs past 160°W rather than stopping at 140.
   *
   * `ZOOM.basin` rather than a number: at that floor storm names appear and the
   * whole basin is still in frame, which is the view this is trying to be.
   * A basin absent from this table falls back to home, which is what the app
   * does everywhere else it has nowhere better to point.
   */
  basinView: Object.freeze({
    atlantic: Object.freeze({ lon: -55, lat: 25 }),
    epacific: Object.freeze({ lon: -125, lat: 17 }),
  }),

  /**
   * ==> HOW FAR IN THE CAMERA GOES WHEN A STORM'S PANEL IS OPENED, AND IT
   * FRAMES THE START OF THE TRACK RATHER THAN THE WHOLE OF IT. <== Aaron's
   * call on glass, 2026-08-25, and it reversed the design that was written
   * first. Fitting the entire track sounded right — a finished storm is a
   * curve, not a point, and Katrina is a two-thousand-mile arc — but the zoom
   * that fits that arc is roughly `ZOOM.basin`, which is a long way out for a
   * panel about one storm, and it framed mostly open water.
   *
   * The START fix is the one with a claim to the camera. It is where the
   * record opens, it is where §57.21a already puts the white direction ring
   * and the name, and it is where §57.21c's glyph sits — so the thing the
   * reader is flown to is the thing that is marked.
   *
   * ==> IT STARTS AT `GLOBE.flyToZoom`'S VALUE ON PURPOSE, AND IT IS A
   * SEPARATE DIAL ON PURPOSE. <== 5 is what the live app uses to frame a
   * selected storm, and framing one point is the same question here. It is
   * its own constant because the two are allowed to diverge: an archive track
   * runs away from its start fix and a live storm does not, so this is the
   * number to move if the opening frame wants more of the curve in it.
   */
  stormZoom: 5,

  /* --- The archive's ridge (§57.21c) --------------------------------------- */

  /**
   * ==> THE WHOLE-SET CEILING ON ARCHIVE RIDGE POINTS, AND IT EXISTS BECAUSE
   * THE ARCHIVE CAN TICK A WHOLE SEASON. <== `MESH_TRACK.maxPointsPerStorm`
   * bounds ONE storm and is sized for the live globe, which draws at most
   * fifteen. A reader who presses the master box on 2005 draws twenty-eight
   * storms of roughly fifty six-hourly fixes each — about 1,400 points, which
   * is already the live globe's busiest hour, and 2005 is not the ceiling of
   * what the record holds.
   *
   * Every point is tested against every one of the cage's 1,440 nodes on a
   * recompute (`map/heightfield.js` `influenceAt`), so this number IS the work
   * a tick does. 1,600 sits just above the live globe's own peak, which is the
   * budget already proven on a phone.
   *
   * ==> IT IS SPENT EVENLY AND SPENT BY THINNING, NEVER BY DROPPING STORMS.
   * <== Each ticked storm gets an equal share and `thin` drops alternate fixes
   * to reach it, so a ridge over a busy season is COARSER rather than shorter
   * and no storm silently loses its mountain. A season ticked whole is exactly
   * the case where a missing storm would be impossible to notice.
   */
  meshMaxPointsTotal: 1600,

  /** The floor under that share. Below three fixes a storm's ridge stops being
   *  a ridge and becomes a single bump in the wrong place, so a season busy
   *  enough to push the share under this spends more than the ceiling rather
   *  than drawing something misleading. The overrun is bounded by the roster:
   *  the largest season in the record is under fifty storms. */
  meshMinPointsPerStorm: 3,

  /* --- Tapping a glyph on the archive globe (§57.21d) ---------------------- */

  /**
   * ==> HOW FAR IN THE GLYPH GOES ON ANSWERING TAPS, AND IT IS READ OFF THE
   * FADE THAT DRAWS IT RATHER THAN CHOSEN. <== §57.21d.
   *
   * `map/globe3d.js` fades the surface glyphs out across `DIVE.fade.nodes`,
   * which is dive phase 0.14 to 0.60 — map zoom 2.42 to 3.80. This is the
   * NEAR end of that band: the glyph answers a tap only while it is at full
   * strength, and the track owns every zoom after that.
   *
   * ==> THE TWO TESTS ARE DISJOINT BY ZOOM ON PURPOSE, SO THEY CANNOT ARGUE.
   * <== NOW.md's worry was the glyph test fighting the track test at closer
   * zooms. It cannot, because it is switched off there — and nothing is lost,
   * because the glyph is stamped on the track's FIRST fix, so in the fading
   * band the track hit-test resolves the same storm from the same pixels.
   *
   * ==> IT IS A REFERENCE, NOT A COPY OF THE NUMBER. <== Written as `0.14` it
   * would be two numbers that have to be kept in agreement by hand, and the
   * symptom of them drifting is a glyph you can plainly see that will not
   * answer a tap — which reads as a broken app rather than as a threshold.
   */
  glyphTapMaxPhase: DIVE.fade.nodes[0],

  /**
   * ==> IS THE GLYPH ON THE NEAR SIDE OF THE PLANET. <== §57.21d. The hit-test
   * projects each drawn storm's first fix through MapLibre, and MapLibre
   * returns a screen point for a position on the FAR side of the globe just as
   * happily as for one you can see. Without this, a tap on the Atlantic could
   * open a storm sitting behind the Earth.
   *
   * The test is the dot product of the storm's direction against the direction
   * the map is centred on. This is the floor it must clear.
   *
   * ==> DERIVED FROM THE CAMERA RATHER THAN GUESSED. <== A point at radius `r`
   * from the centre is over the horizon of the unit globe, seen from a camera
   * at distance `d`, when `r · (p̂ · â) < 1`. So the floor is `1 / (r · d)`,
   * with `r` the radius the glyphs are stamped at and `d` the camera's
   * distance at the space floor. It works out at about 0.324 — a cap a little
   * smaller than a hemisphere, which is what a camera at finite distance can
   * actually see.
   *
   * `d` genuinely shrinks as you zoom in, which would raise the true floor —
   * but this test only runs at the space floor (`glyphTapMaxPhase` above),
   * where the camera is at `spaceDistance`, so using it is right rather than
   * approximate.
   */
  glyphFacingMin: 1 / (DIVE.stormDotRadius * DIVE.spaceDistance),

  /** ==> THE FIRST YEAR NOAA WROTE A REPORT ON A STORM, AND IT ONLY EVER
   *  PICKS A SENTENCE. <== §57.22a.
   *
   *  Same rule as `windFieldFirstSeason` above and worth restating because the
   *  temptation is identical: this NEVER decides whether to look a report up.
   *  `seasons/reports.json` is the only thing that answers that, storm by
   *  storm. This chooses between *"NOAA did not begin writing these until
   *  1958"* — a fact about the record that teaches the reader something — and
   *  *"NOAA did not write one about this storm"*, which is what a 1994 gap
   *  means.
   *
   *  MEASURED 2026-08-25 by `tools/tcr-index.mjs` against NOAA's own two
   *  indexes: 1,524 of 3,266 storms have one, the earliest is 1958, and
   *  coverage is partial even in modern seasons — 2005 has 31 against 48
   *  storms. So "no report for this one" is the ORDINARY answer, not an error,
   *  and §57.25 rule 2 rather than §5's failure states is what applies. */
  reportsFirstSeason: 1958,
});
